// ---------------------------------------------------------------------------
// Hashing / HMAC / HKDF

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum HashAlg {
    Sha256,
    Sha384,
}

impl HashAlg {
    fn md(self) -> *const EVP_MD {
        unsafe {
            match self {
                HashAlg::Sha256 => EVP_sha256(),
                HashAlg::Sha384 => EVP_sha384(),
            }
        }
    }
    pub fn len(self) -> usize {
        match self {
            HashAlg::Sha256 => 32,
            HashAlg::Sha384 => 48,
        }
    }
}

pub struct Hasher {
    ctx: *mut EVP_MD_CTX,
    alg: HashAlg,
}

unsafe impl Send for Hasher {}

impl Hasher {
    pub fn new(alg: HashAlg) -> Self {
        unsafe {
            let ctx = EVP_MD_CTX_new();
            EVP_DigestInit_ex(ctx, alg.md(), ptr::null_mut());
            Hasher { ctx, alg }
        }
    }
    pub fn update(&mut self, data: &[u8]) {
        unsafe {
            EVP_DigestUpdate(self.ctx, data.as_ptr() as *const c_void, data.len());
        }
    }
    /// Returns the digest of everything fed so far without consuming the state.
    pub fn snapshot(&self) -> Vec<u8> {
        unsafe {
            let c = EVP_MD_CTX_new();
            EVP_MD_CTX_copy_ex(c, self.ctx);
            let mut out = vec![0u8; 64];
            let mut l: c_uint = 0;
            EVP_DigestFinal_ex(c, out.as_mut_ptr(), &mut l);
            EVP_MD_CTX_free(c);
            out.truncate(l as usize);
            out
        }
    }
    pub fn alg(&self) -> HashAlg {
        self.alg
    }
}

impl Drop for Hasher {
    fn drop(&mut self) {
        unsafe { EVP_MD_CTX_free(self.ctx) }
    }
}

pub fn hash(alg: HashAlg, data: &[u8]) -> Vec<u8> {
    let mut h = Hasher::new(alg);
    h.update(data);
    h.snapshot()
}

pub fn hmac(alg: HashAlg, key: &[u8], data: &[u8]) -> Vec<u8> {
    let mut out = vec![0u8; 64];
    let mut l: c_uint = 0;
    unsafe {
        HMAC(
            alg.md(),
            key.as_ptr() as *const c_void,
            key.len() as c_int,
            data.as_ptr(),
            data.len(),
            out.as_mut_ptr(),
            &mut l,
        );
    }
    out.truncate(l as usize);
    out
}

pub fn hkdf_extract(alg: HashAlg, salt: &[u8], ikm: &[u8]) -> Vec<u8> {
    let salt_owned;
    let salt = if salt.is_empty() {
        salt_owned = vec![0u8; alg.len()];
        &salt_owned[..]
    } else {
        salt
    };
    hmac(alg, salt, ikm)
}

pub fn hkdf_expand(alg: HashAlg, prk: &[u8], info: &[u8], len: usize) -> Vec<u8> {
    let mut out = Vec::with_capacity(len);
    let mut t: Vec<u8> = Vec::new();
    let mut counter = 1u8;
    while out.len() < len {
        let mut input = t.clone();
        input.extend_from_slice(info);
        input.push(counter);
        t = hmac(alg, prk, &input);
        out.extend_from_slice(&t);
        counter += 1;
    }
    out.truncate(len);
    out
}

pub fn hkdf_expand_label(alg: HashAlg, secret: &[u8], label: &[u8], context: &[u8], len: usize) -> Vec<u8> {
    let mut info = Vec::with_capacity(4 + 6 + label.len() + context.len());
    info.extend_from_slice(&(len as u16).to_be_bytes());
    info.push((6 + label.len()) as u8);
    info.extend_from_slice(b"tls13 ");
    info.extend_from_slice(label);
    info.push(context.len() as u8);
    info.extend_from_slice(context);
    hkdf_expand(alg, secret, &info, len)
}

// ---------------------------------------------------------------------------
// AEAD

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Suite {
    Aes128Gcm,
    Aes256Gcm,
    Chacha20Poly1305,
}

impl Suite {
    pub fn from_tls_id(id: u16) -> Option<Suite> {
        match id {
            0x1301 => Some(Suite::Aes128Gcm),
            0x1302 => Some(Suite::Aes256Gcm),
            0x1303 => Some(Suite::Chacha20Poly1305),
            _ => None,
        }
    }
    pub fn tls_id(self) -> u16 {
        match self {
            Suite::Aes128Gcm => 0x1301,
            Suite::Aes256Gcm => 0x1302,
            Suite::Chacha20Poly1305 => 0x1303,
        }
    }
    pub fn hash(self) -> HashAlg {
        match self {
            Suite::Aes256Gcm => HashAlg::Sha384,
            _ => HashAlg::Sha256,
        }
    }
    pub fn key_len(self) -> usize {
        match self {
            Suite::Aes128Gcm => 16,
            _ => 32,
        }
    }
    fn aead_cipher(self) -> *const EVP_CIPHER {
        unsafe {
            match self {
                Suite::Aes128Gcm => EVP_aes_128_gcm(),
                Suite::Aes256Gcm => EVP_aes_256_gcm(),
                Suite::Chacha20Poly1305 => EVP_chacha20_poly1305(),
            }
        }
    }
}

pub const TAG_LEN: usize = 16;

pub struct Aead {
    enc: *mut EVP_CIPHER_CTX,
    dec: *mut EVP_CIPHER_CTX,
    iv: [u8; 12],
}

unsafe impl Send for Aead {}

impl Aead {
    pub fn new(suite: Suite, key: &[u8], iv: &[u8]) -> Aead {
        unsafe {
            let enc = EVP_CIPHER_CTX_new();
            let dec = EVP_CIPHER_CTX_new();
            let c = suite.aead_cipher();
            EVP_EncryptInit_ex(enc, c, ptr::null_mut(), ptr::null(), ptr::null());
            EVP_CIPHER_CTX_ctrl(enc, 0x9, 12, ptr::null_mut());
            EVP_EncryptInit_ex(enc, ptr::null(), ptr::null_mut(), key.as_ptr(), ptr::null());
            EVP_DecryptInit_ex(dec, c, ptr::null_mut(), ptr::null(), ptr::null());
            EVP_CIPHER_CTX_ctrl(dec, 0x9, 12, ptr::null_mut());
            EVP_DecryptInit_ex(dec, ptr::null(), ptr::null_mut(), key.as_ptr(), ptr::null());
            let mut ivb = [0u8; 12];
            ivb.copy_from_slice(&iv[..12]);
            Aead { enc, dec, iv: ivb }
        }
    }

    fn nonce(&self, pn: u64) -> [u8; 12] {
        let mut n = self.iv;
        let p = pn.to_be_bytes();
        for i in 0..8 {
            n[4 + i] ^= p[i];
        }
        n
    }

    /// Encrypts `payload` in place, writing the tag into `tag`.
    pub fn seal(&self, pn: u64, aad: &[u8], payload: &mut [u8], tag: &mut [u8]) {
        let nonce = self.nonce(pn);
        unsafe {
            let mut outl: c_int = 0;
            EVP_EncryptInit_ex(self.enc, ptr::null(), ptr::null_mut(), ptr::null(), nonce.as_ptr());
            EVP_EncryptUpdate(self.enc, ptr::null_mut(), &mut outl, aad.as_ptr(), aad.len() as c_int);
            if !payload.is_empty() {
                EVP_EncryptUpdate(
                    self.enc,
                    payload.as_mut_ptr(),
                    &mut outl,
                    payload.as_ptr(),
                    payload.len() as c_int,
                );
            }
            let mut fin = [0u8; 32];
            EVP_EncryptFinal_ex(self.enc, fin.as_mut_ptr(), &mut outl);
            EVP_CIPHER_CTX_ctrl(self.enc, 0x10, 16, tag.as_mut_ptr() as *mut c_void);
        }
    }

    /// Decrypts `payload` (ciphertext without tag) in place, verifying `tag`.
    pub fn open(&self, pn: u64, aad: &[u8], payload: &mut [u8], tag: &[u8]) -> bool {
        let nonce = self.nonce(pn);
        unsafe {
            let mut outl: c_int = 0;
            EVP_DecryptInit_ex(self.dec, ptr::null(), ptr::null_mut(), ptr::null(), nonce.as_ptr());
            EVP_DecryptUpdate(self.dec, ptr::null_mut(), &mut outl, aad.as_ptr(), aad.len() as c_int);
            if !payload.is_empty() {
                EVP_DecryptUpdate(
                    self.dec,
                    payload.as_mut_ptr(),
                    &mut outl,
                    payload.as_ptr(),
                    payload.len() as c_int,
                );
            }
            let mut t = [0u8; 16];
            t.copy_from_slice(&tag[..16]);
            EVP_CIPHER_CTX_ctrl(self.dec, 0x11, 16, t.as_mut_ptr() as *mut c_void);
            let mut fin = [0u8; 32];
            let r = EVP_DecryptFinal_ex(self.dec, fin.as_mut_ptr(), &mut outl);
            if r != 1 {
                ERR_clear_error();
            }
            r == 1
        }
    }
}

impl Drop for Aead {
    fn drop(&mut self) {
        unsafe {
            EVP_CIPHER_CTX_free(self.enc);
            EVP_CIPHER_CTX_free(self.dec);
        }
    }
}

/// QUIC header protection.
pub struct HeaderKey {
    ctx: *mut EVP_CIPHER_CTX,
    chacha_key: Option<[u8; 32]>,
}

unsafe impl Send for HeaderKey {}

impl HeaderKey {
    pub fn new(suite: Suite, key: &[u8]) -> HeaderKey {
        unsafe {
            let ctx = EVP_CIPHER_CTX_new();
            match suite {
                Suite::Aes128Gcm => {
                    EVP_EncryptInit_ex(ctx, EVP_aes_128_ecb(), ptr::null_mut(), key.as_ptr(), ptr::null());
                    EVP_CIPHER_CTX_set_padding(ctx, 0);
                    HeaderKey { ctx, chacha_key: None }
                }
                Suite::Aes256Gcm => {
                    EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), ptr::null_mut(), key.as_ptr(), ptr::null());
                    EVP_CIPHER_CTX_set_padding(ctx, 0);
                    HeaderKey { ctx, chacha_key: None }
                }
                Suite::Chacha20Poly1305 => {
                    let mut k = [0u8; 32];
                    k.copy_from_slice(&key[..32]);
                    HeaderKey { ctx, chacha_key: Some(k) }
                }
            }
        }
    }

    pub fn mask(&self, sample: &[u8]) -> [u8; 5] {
        let mut out = [0u8; 32];
        unsafe {
            let mut outl: c_int = 0;
            match &self.chacha_key {
                None => {
                    EVP_EncryptUpdate(self.ctx, out.as_mut_ptr(), &mut outl, sample.as_ptr(), 16);
                }
                Some(k) => {
                    EVP_EncryptInit_ex(self.ctx, EVP_chacha20(), ptr::null_mut(), k.as_ptr(), sample.as_ptr());
                    let zeros = [0u8; 5];
                    EVP_EncryptUpdate(self.ctx, out.as_mut_ptr(), &mut outl, zeros.as_ptr(), 5);
                }
            }
        }
        let mut m = [0u8; 5];
        m.copy_from_slice(&out[..5]);
        m
    }
}

impl Drop for HeaderKey {
    fn drop(&mut self) {
        unsafe { EVP_CIPHER_CTX_free(self.ctx) }
    }
}

// ---------------------------------------------------------------------------
// Key exchange (X25519)

pub struct X25519 {
    pkey: *mut EVP_PKEY,
    pub public: [u8; 32],
}

impl X25519 {
    pub fn generate() -> X25519 {
        let mut priv_ = [0u8; 32];
        random_bytes(&mut priv_);
        unsafe {
            let pkey = EVP_PKEY_new_raw_private_key(EVP_PKEY_X25519, ptr::null_mut(), priv_.as_ptr(), 32);
            let mut public = [0u8; 32];
            let mut l: usize = 32;
            EVP_PKEY_get_raw_public_key(pkey, public.as_mut_ptr(), &mut l);
            X25519 { pkey, public }
        }
    }

    pub fn agree(&self, peer: &[u8]) -> Option<Vec<u8>> {
        if peer.len() != 32 {
            return None;
        }
        unsafe {
            let peer_key = EVP_PKEY_new_raw_public_key(EVP_PKEY_X25519, ptr::null_mut(), peer.as_ptr(), 32);
            if peer_key.is_null() {
                ERR_clear_error();
                return None;
            }
            let ctx = EVP_PKEY_CTX_new(self.pkey, ptr::null_mut());
            let mut ok = EVP_PKEY_derive_init(ctx) == 1;
            ok = ok && EVP_PKEY_derive_set_peer(ctx, peer_key) == 1;
            let mut out = vec![0u8; 32];
            let mut l: usize = 32;
            ok = ok && EVP_PKEY_derive(ctx, out.as_mut_ptr(), &mut l) == 1;
            EVP_PKEY_CTX_free(ctx);
            EVP_PKEY_free(peer_key);
            if !ok {
                ERR_clear_error();
                return None;
            }
            out.truncate(l);
            Some(out)
        }
    }
}

impl Drop for X25519 {
    fn drop(&mut self) {
        unsafe { EVP_PKEY_free(self.pkey) }
    }
}

// ---------------------------------------------------------------------------
// Signing keys

pub struct PrivateKey {
    pkey: *mut EVP_PKEY,
}

unsafe impl Send for PrivateKey {}
unsafe impl Sync for PrivateKey {}

impl Drop for PrivateKey {
    fn drop(&mut self) {
        unsafe { EVP_PKEY_free(self.pkey) }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum KeyKind {
    Rsa,
    EcP256,
    EcP384,
    Ed25519,
    Other,
}

impl PrivateKey {
    /// Parses a DER encoded private key (PKCS#8, PKCS#1 or SEC1).
    pub fn from_der(der: &[u8], hint: Option<i32>) -> Option<PrivateKey> {
        unsafe {
            let mut p = der.as_ptr();
            let pkey = match hint {
                Some(t) => d2i_PrivateKey(t, ptr::null_mut(), &mut p, der.len() as c_long),
                None => d2i_AutoPrivateKey(ptr::null_mut(), &mut p, der.len() as c_long),
            };
            if pkey.is_null() {
                ERR_clear_error();
                None
            } else {
                Some(PrivateKey { pkey })
            }
        }
    }

    pub fn generate_p256() -> Option<PrivateKey> {
        unsafe {
            let ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_EC, ptr::null_mut());
            if ctx.is_null() {
                return None;
            }
            let mut pkey: *mut EVP_PKEY = ptr::null_mut();
            let ok = EVP_PKEY_keygen_init(ctx) == 1
                && EVP_PKEY_CTX_set_ec_paramgen_curve_nid(ctx, NID_X9_62_PRIME256V1) == 1
                && EVP_PKEY_keygen(ctx, &mut pkey) == 1;
            EVP_PKEY_CTX_free(ctx);
            if !ok || pkey.is_null() {
                ERR_clear_error();
                return None;
            }
            Some(PrivateKey { pkey })
        }
    }

    pub fn kind(&self) -> KeyKind {
        unsafe {
            match EVP_PKEY_get_base_id(self.pkey) {
                EVP_PKEY_RSA | EVP_PKEY_RSA_PSS => KeyKind::Rsa,
                EVP_PKEY_EC => match EVP_PKEY_get_bits(self.pkey) {
                    256 => KeyKind::EcP256,
                    384 => KeyKind::EcP384,
                    _ => KeyKind::Other,
                },
                EVP_PKEY_ED25519 => KeyKind::Ed25519,
                _ => KeyKind::Other,
            }
        }
    }

    /// DER encoded SubjectPublicKeyInfo of the public half.
    pub fn public_spki(&self) -> Vec<u8> {
        unsafe {
            let mut p: *mut c_uchar = ptr::null_mut();
            let l = i2d_PUBKEY(self.pkey, &mut p);
            if l <= 0 || p.is_null() {
                ERR_clear_error();
                return Vec::new();
            }
            let v = std::slice::from_raw_parts(p, l as usize).to_vec();
            CRYPTO_free(p as *mut c_void, b"perf\0".as_ptr() as *const c_char, 0);
            v
        }
    }

    /// Signs `msg` with the given TLS SignatureScheme.
    pub fn sign(&self, scheme: u16, msg: &[u8]) -> Option<Vec<u8>> {
        unsafe {
            let ctx = EVP_MD_CTX_new();
            let mut pctx: *mut EVP_PKEY_CTX = ptr::null_mut();
            let md = match scheme {
                0x0403 | 0x0804 | 0x0401 => EVP_sha256(),
                0x0503 | 0x0805 | 0x0501 => EVP_sha384(),
                0x0603 | 0x0806 | 0x0601 => EVP_sha512(),
                _ => ptr::null(),
            };
            let mut ok = EVP_DigestSignInit(ctx, &mut pctx, md, ptr::null_mut(), self.pkey) == 1;
            if ok && matches!(scheme, 0x0804 | 0x0805 | 0x0806) {
                ok = EVP_PKEY_CTX_set_rsa_padding(pctx, 6) == 1 && EVP_PKEY_CTX_set_rsa_pss_saltlen(pctx, -1) == 1;
            }
            let mut siglen: usize = 0;
            ok = ok && EVP_DigestSign(ctx, ptr::null_mut(), &mut siglen, msg.as_ptr(), msg.len()) == 1;
            let mut sig = vec![0u8; siglen];
            ok = ok && EVP_DigestSign(ctx, sig.as_mut_ptr(), &mut siglen, msg.as_ptr(), msg.len()) == 1;
            EVP_MD_CTX_free(ctx);
            if !ok {
                ERR_clear_error();
                return None;
            }
            sig.truncate(siglen);
            Some(sig)
        }
    }
}

/// Verifies a TLS 1.3 signature made with the key in the given SPKI.
pub fn verify_signature(spki: &[u8], scheme: u16, msg: &[u8], sig: &[u8]) -> bool {
    unsafe {
        let mut p = spki.as_ptr();
        let pkey = d2i_PUBKEY(ptr::null_mut(), &mut p, spki.len() as c_long);
        if pkey.is_null() {
            ERR_clear_error();
            return false;
        }
        let ctx = EVP_MD_CTX_new();
        let mut pctx: *mut EVP_PKEY_CTX = ptr::null_mut();
        let md = match scheme {
            0x0403 | 0x0804 | 0x0401 => EVP_sha256(),
            0x0503 | 0x0805 | 0x0501 => EVP_sha384(),
            0x0603 | 0x0806 | 0x0601 => EVP_sha512(),
            _ => ptr::null(),
        };
        let mut ok = EVP_DigestVerifyInit(ctx, &mut pctx, md, ptr::null_mut(), pkey) == 1;
        if ok && matches!(scheme, 0x0804 | 0x0805 | 0x0806) {
            ok = EVP_PKEY_CTX_set_rsa_padding(pctx, 6) == 1 && EVP_PKEY_CTX_set_rsa_pss_saltlen(pctx, -1) == 1;
        }
        ok = ok && EVP_DigestVerify(ctx, sig.as_ptr(), sig.len(), msg.as_ptr(), msg.len()) == 1;
        EVP_MD_CTX_free(ctx);
        EVP_PKEY_free(pkey);
        if !ok {
            ERR_clear_error();
        }
        ok
    }
}
