        let s = &self.buf[self.pos..];
        self.pos = self.buf.len();
        s
    }
    pub fn varint(&mut self) -> Option<u64> {
        let first = *self.buf.get(self.pos)?;
        let len = 1usize << (first >> 6);
        let b = self.bytes(len)?;
        let mut v = (b[0] & 0x3f) as u64;
        for x in &b[1..] {
            v = (v << 8) | *x as u64;
        }
        Some(v)
    }
    pub fn vec8(&mut self) -> Option<&'a [u8]> {
        let l = self.u8()? as usize;
        self.bytes(l)
    }
    pub fn vec16(&mut self) -> Option<&'a [u8]> {
        let l = self.u16()? as usize;
        self.bytes(l)
    }
    pub fn vec24(&mut self) -> Option<&'a [u8]> {
        let l = self.u24()? as usize;
        self.bytes(l)
    }
}

pub fn put_u16(out: &mut Vec<u8>, v: u16) {
    out.extend_from_slice(&v.to_be_bytes());
}
pub fn put_u24(out: &mut Vec<u8>, v: u32) {
    out.extend_from_slice(&v.to_be_bytes()[1..]);
}
pub fn put_u32(out: &mut Vec<u8>, v: u32) {
    out.extend_from_slice(&v.to_be_bytes());
}

/// Appends `f`'s output prefixed with a length of `len_bytes` bytes.
pub fn put_vec<F: FnOnce(&mut Vec<u8>)>(out: &mut Vec<u8>, len_bytes: usize, f: F) {
    let start = out.len();
    out.extend(std::iter::repeat(0).take(len_bytes));
    f(out);
    let l = out.len() - start - len_bytes;
    let lb = (l as u32).to_be_bytes();
    for i in 0..len_bytes {
        out[start + i] = lb[4 - len_bytes + i];
    }
}

pub fn hex(b: &[u8]) -> String {
    let mut s = String::with_capacity(b.len() * 2);
    for x in b {
        s.push_str(&format!("{:02x}", x));
    }
    s
}

pub fn unhex(s: &str) -> Option<Vec<u8>> {
    let s = s.trim();
    if s.len() % 2 != 0 {
        return None;
    }
    let mut out = Vec::with_capacity(s.len() / 2);
    for i in (0..s.len()).step_by(2) {
        out.push(u8::from_str_radix(&s[i..i + 2], 16).ok()?);
    }
    Some(out)
}
