                        return None;
                    }
                    let hi = smallest - gap - 2;
                    if hi < len {
                        return None;
                    }
                    smallest = hi - len;
                    ranges.push((smallest, hi));
                }
                let ecn = if t == ty::ACK_ECN { Some((r.varint()?, r.varint()?, r.varint()?)) } else { None };
