            }
            ty::RETIRE_CONNECTION_ID => Frame::RetireConnectionId { seq: r.varint()? },
            ty::PATH_CHALLENGE => {
                let mut b = [0u8; 8];
                b.copy_from_slice(r.bytes(8)?);
                Frame::PathChallenge(b)
            }
            ty::PATH_RESPONSE => {
                let mut b = [0u8; 8];
                b.copy_from_slice(r.bytes(8)?);
                Frame::PathResponse(b)
            }
            ty::CONNECTION_CLOSE => {
                let error = r.varint()?;
                let frame_type = r.varint()?;
                let len = r.varint()? as usize;
                Frame::ConnectionClose { error, frame_type, reason: r.bytes(len)? }
            }
            ty::APPLICATION_CLOSE => {
                let error = r.varint()?;
                let len = r.varint()? as usize;
                Frame::ApplicationClose { error, reason: r.bytes(len)? }
            }
            ty::HANDSHAKE_DONE => Frame::HandshakeDone,
            ty::IMMEDIATE_ACK => Frame::ImmediateAck,
            ty::DATAGRAM => Frame::Datagram { data: r.rest() },
            ty::DATAGRAM_LEN => {
                let len = r.varint()? as usize;
                Frame::Datagram { data: r.bytes(len)? }
            }
            ty::ACK_FREQUENCY => Frame::AckFrequency {
                seq: r.varint()?,
                ack_eliciting_threshold: r.varint()?,
                request_max_ack_delay: r.varint()?,
                reordering_threshold: r.varint()?,
            },
            _ => return None,
        })
    }
}

impl<'a> Iterator for FrameIter<'a> {
    type Item = Frame<'a>;
    fn next(&mut self) -> Option<Frame<'a>> {
        if self.error || self.r.is_empty() {
            return None;
        }
        match self.parse() {
            Some(f) => Some(f),
            None => {
                self.error = true;
                None
            }
        }
    }
}

/// Encodes an ACK frame from ascending, non-overlapping ranges [start, end).
pub fn encode_ack(out: &mut Vec<u8>, ranges: &[(u64, u64)], delay: u64, ecn: Option<(u64, u64, u64)>, max_ranges: usize) {
    let n = ranges.len();
    if n == 0 {
        return;
    }
    put_varint(out, if ecn.is_some() { ty::ACK_ECN } else { ty::ACK });
    let (s, e) = ranges[n - 1];
    let largest = e - 1;
    put_varint(out, largest);
    put_varint(out, delay);
    let count = (n - 1).min(max_ranges.saturating_sub(1));
    put_varint(out, count as u64);
    put_varint(out, e - 1 - s);
    let mut prev_smallest = s;
    for i in 0..count {
        let (s2, e2) = ranges[n - 2 - i];
        let gap = prev_smallest - e2 - 1;
        put_varint(out, gap);
        put_varint(out, e2 - 1 - s2);
        prev_smallest = s2;
    }
    if let Some((a, b, c)) = ecn {
        put_varint(out, a);
        put_varint(out, b);
        put_varint(out, c);
    }
}
