//! QUIC transport parameters (RFC 9000 section 18).
#![allow(dead_code)]

use crate::coding::*;

pub mod id {
    pub const ORIGINAL_DCID: u64 = 0x00;
    pub const MAX_IDLE_TIMEOUT: u64 = 0x01;
    pub const STATELESS_RESET_TOKEN: u64 = 0x02;
    pub const MAX_UDP_PAYLOAD_SIZE: u64 = 0x03;
    pub const INITIAL_MAX_DATA: u64 = 0x04;
    pub const INITIAL_MAX_STREAM_DATA_BIDI_LOCAL: u64 = 0x05;
    pub const INITIAL_MAX_STREAM_DATA_BIDI_REMOTE: u64 = 0x06;
    pub const INITIAL_MAX_STREAM_DATA_UNI: u64 = 0x07;
    pub const INITIAL_MAX_STREAMS_BIDI: u64 = 0x08;
    pub const INITIAL_MAX_STREAMS_UNI: u64 = 0x09;
    pub const ACK_DELAY_EXPONENT: u64 = 0x0a;
    pub const MAX_ACK_DELAY: u64 = 0x0b;
    pub const DISABLE_ACTIVE_MIGRATION: u64 = 0x0c;
    pub const PREFERRED_ADDRESS: u64 = 0x0d;
    pub const ACTIVE_CONNECTION_ID_LIMIT: u64 = 0x0e;
    pub const INITIAL_SCID: u64 = 0x0f;
    pub const RETRY_SCID: u64 = 0x10;
    pub const MAX_DATAGRAM_FRAME_SIZE: u64 = 0x20;
    pub const GREASE_QUIC_BIT: u64 = 0x2ab2;
    pub const MIN_ACK_DELAY: u64 = 0xff04de1b;
}

#[derive(Clone, Debug)]
pub struct TransportParams {
    pub original_dcid: Option<Vec<u8>>,
    pub max_idle_timeout: u64,
    pub stateless_reset_token: Option<[u8; 16]>,
    pub max_udp_payload_size: u64,
    pub initial_max_data: u64,
    pub initial_max_stream_data_bidi_local: u64,
    pub initial_max_stream_data_bidi_remote: u64,
    pub initial_max_stream_data_uni: u64,
    pub initial_max_streams_bidi: u64,
    pub initial_max_streams_uni: u64,
    pub ack_delay_exponent: u64,
    pub max_ack_delay: u64,
    pub disable_active_migration: bool,
    pub active_connection_id_limit: u64,
    pub initial_scid: Option<Vec<u8>>,
    pub retry_scid: Option<Vec<u8>>,
    pub max_datagram_frame_size: Option<u64>,
    pub grease_quic_bit: bool,
    pub min_ack_delay: Option<u64>,
}

impl Default for TransportParams {
    fn default() -> Self {
        TransportParams {
            original_dcid: None,
            max_idle_timeout: 0,
            stateless_reset_token: None,
            max_udp_payload_size: 65527,
            initial_max_data: 0,
            initial_max_stream_data_bidi_local: 0,
            initial_max_stream_data_bidi_remote: 0,
            initial_max_stream_data_uni: 0,
            initial_max_streams_bidi: 0,
            initial_max_streams_uni: 0,
            ack_delay_exponent: 3,
            max_ack_delay: 25,
            disable_active_migration: false,
            active_connection_id_limit: 2,
            initial_scid: None,
            retry_scid: None,
            max_datagram_frame_size: None,
            grease_quic_bit: false,
            min_ack_delay: None,
        }
    }
}

fn put_param_int(out: &mut Vec<u8>, id: u64, v: u64) {
    put_varint(out, id);
    put_varint(out, varint_len(v) as u64);
    put_varint(out, v);
}

fn put_param_bytes(out: &mut Vec<u8>, id: u64, v: &[u8]) {
    put_varint(out, id);
    put_varint(out, v.len() as u64);
    out.extend_from_slice(v);
}

impl TransportParams {
    pub fn encode(&self) -> Vec<u8> {
        // Parameters are emitted in a shuffled order, with a reserved (GREASE) parameter.
        let mut items: Vec<Vec<u8>> = Vec::new();
        let mut push = |f: &dyn Fn(&mut Vec<u8>)| {
            let mut v = Vec::new();
            f(&mut v);
            items.push(v);
        };
        if let Some(o) = &self.original_dcid {
            push(&|v| put_param_bytes(v, id::ORIGINAL_DCID, o));
        }
        if self.max_idle_timeout != 0 {
            push(&|v| put_param_int(v, id::MAX_IDLE_TIMEOUT, self.max_idle_timeout));
        }
        if let Some(t) = &self.stateless_reset_token {
            push(&|v| put_param_bytes(v, id::STATELESS_RESET_TOKEN, t));
        }
        if self.max_udp_payload_size != 65527 {
            push(&|v| put_param_int(v, id::MAX_UDP_PAYLOAD_SIZE, self.max_udp_payload_size));
        }
        if self.initial_max_data != 0 {
            push(&|v| put_param_int(v, id::INITIAL_MAX_DATA, self.initial_max_data));
        }
        if self.initial_max_stream_data_bidi_local != 0 {
            push(&|v| put_param_int(v, id::INITIAL_MAX_STREAM_DATA_BIDI_LOCAL, self.initial_max_stream_data_bidi_local));
        }
        if self.initial_max_stream_data_bidi_remote != 0 {
            push(&|v| put_param_int(v, id::INITIAL_MAX_STREAM_DATA_BIDI_REMOTE, self.initial_max_stream_data_bidi_remote));
        }
        if self.initial_max_stream_data_uni != 0 {
            push(&|v| put_param_int(v, id::INITIAL_MAX_STREAM_DATA_UNI, self.initial_max_stream_data_uni));
        }
        if self.initial_max_streams_bidi != 0 {
            push(&|v| put_param_int(v, id::INITIAL_MAX_STREAMS_BIDI, self.initial_max_streams_bidi));
        }
        if self.initial_max_streams_uni != 0 {
            push(&|v| put_param_int(v, id::INITIAL_MAX_STREAMS_UNI, self.initial_max_streams_uni));
        }
        if self.ack_delay_exponent != 3 {
            push(&|v| put_param_int(v, id::ACK_DELAY_EXPONENT, self.ack_delay_exponent));
        }
        if self.max_ack_delay != 25 {
            push(&|v| put_param_int(v, id::MAX_ACK_DELAY, self.max_ack_delay));
        }
        if self.disable_active_migration {
            push(&|v| put_param_bytes(v, id::DISABLE_ACTIVE_MIGRATION, &[]));
        }
        if self.active_connection_id_limit != 2 {
            push(&|v| put_param_int(v, id::ACTIVE_CONNECTION_ID_LIMIT, self.active_connection_id_limit));
        }
        if let Some(s) = &self.initial_scid {
            push(&|v| put_param_bytes(v, id::INITIAL_SCID, s));
        }
        if let Some(s) = &self.retry_scid {
            push(&|v| put_param_bytes(v, id::RETRY_SCID, s));
        }
        if let Some(m) = self.max_datagram_frame_size {
            push(&|v| put_param_int(v, id::MAX_DATAGRAM_FRAME_SIZE, m));
        }
        if self.grease_quic_bit {
            push(&|v| put_param_bytes(v, id::GREASE_QUIC_BIT, &[]));
        }
        if let Some(m) = self.min_ack_delay {
            push(&|v| put_param_int(v, id::MIN_ACK_DELAY, m));
        }
        // Reserved transport parameter: 31 * N + 27
        {
            let n = crate::crypto::random_u64() % (1 << 50);
            let rid = 31 * n + 27;
            let mut val = vec![0u8; (crate::crypto::random_u64() % 16) as usize];
            crate::crypto::random_bytes(&mut val);
            push(&|v| put_param_bytes(v, rid, &val));
        }
        // Fisher-Yates shuffle
        for i in (1..items.len()).rev() {
            let j = (crate::crypto::random_u64() % (i as u64 + 1)) as usize;
            items.swap(i, j);
        }
        items.concat()
    }

    pub fn decode(buf: &[u8], from_server: bool) -> Result<TransportParams, &'static str> {
        let mut p = TransportParams::default();
        let mut r = Reader::new(buf);
        let mut seen: Vec<u64> = Vec::new();
        while !r.is_empty() {
            let pid = r.varint().ok_or("malformed")?;
            let len = r.varint().ok_or("malformed")? as usize;
            let val = r.bytes(len).ok_or("malformed")?;
            if pid < 0x40 || pid == id::GREASE_QUIC_BIT || pid == id::MIN_ACK_DELAY {
                if seen.contains(&pid) {
                    return Err("duplicate parameter");
                }
                seen.push(pid);
            }
            let int = || -> Result<u64, &'static str> {
                let mut rr = Reader::new(val);
                let v = rr.varint().ok_or("malformed")?;
                if !rr.is_empty() {
                    return Err("malformed");
                }
                Ok(v)
            };
            match pid {
                id::ORIGINAL_DCID => {
                    if !from_server {
                        return Err("illegal client parameter");
                    }
                    p.original_dcid = Some(val.to_vec())
                }
                id::MAX_IDLE_TIMEOUT => p.max_idle_timeout = int()?,
                id::STATELESS_RESET_TOKEN => {
                    if !from_server || len != 16 {
                        return Err("illegal reset token");
                    }
                    let mut t = [0u8; 16];
                    t.copy_from_slice(val);
                    p.stateless_reset_token = Some(t);
                }
                id::MAX_UDP_PAYLOAD_SIZE => {
                    p.max_udp_payload_size = int()?;
                    if p.max_udp_payload_size < 1200 {
                        return Err("max_udp_payload_size too small");
                    }
                }
                id::INITIAL_MAX_DATA => p.initial_max_data = int()?,
                id::INITIAL_MAX_STREAM_DATA_BIDI_LOCAL => p.initial_max_stream_data_bidi_local = int()?,
                id::INITIAL_MAX_STREAM_DATA_BIDI_REMOTE => p.initial_max_stream_data_bidi_remote = int()?,
                id::INITIAL_MAX_STREAM_DATA_UNI => p.initial_max_stream_data_uni = int()?,
                id::INITIAL_MAX_STREAMS_BIDI => p.initial_max_streams_bidi = int()?,
                id::INITIAL_MAX_STREAMS_UNI => p.initial_max_streams_uni = int()?,
                id::ACK_DELAY_EXPONENT => {
                    p.ack_delay_exponent = int()?;
                    if p.ack_delay_exponent > 20 {
                        return Err("ack_delay_exponent too large");
                    }
                }
                id::MAX_ACK_DELAY => {
                    p.max_ack_delay = int()?;
                    if p.max_ack_delay >= (1 << 14) {
                        return Err("max_ack_delay too large");
                    }
                }
                id::DISABLE_ACTIVE_MIGRATION => p.disable_active_migration = true,
                id::PREFERRED_ADDRESS => {
                    if !from_server {
                        return Err("illegal client parameter");
                    }
                }
                id::ACTIVE_CONNECTION_ID_LIMIT => {
                    p.active_connection_id_limit = int()?;
                    if p.active_connection_id_limit < 2 {
                        return Err("active_connection_id_limit too small");
                    }
                }
                id::INITIAL_SCID => p.initial_scid = Some(val.to_vec()),
                id::RETRY_SCID => {
                    if !from_server {
                        return Err("illegal client parameter");
                    }
                    p.retry_scid = Some(val.to_vec())
                }
                id::MAX_DATAGRAM_FRAME_SIZE => p.max_datagram_frame_size = Some(int()?),
                id::GREASE_QUIC_BIT => p.grease_quic_bit = true,
                id::MIN_ACK_DELAY => p.min_ack_delay = Some(int()?),
                _ => {}
            }
        }
        if p.initial_max_streams_bidi > (1 << 60) || p.initial_max_streams_uni > (1 << 60) {
            return Err("too many streams");
        }
        Ok(p)
    }
}
