//! Minimal TLS 1.3 handshake for QUIC (RFC 8446 / RFC 9001).
#![allow(dead_code)]

use crate::coding::*;
use crate::crypto::*;
use std::io::Write;
use std::sync::Arc;

pub const ALPN_PERF: &[u8] = b"perf";

// alert codes
pub const ALERT_UNEXPECTED_MESSAGE: u8 = 10;
pub const ALERT_HANDSHAKE_FAILURE: u8 = 40;
pub const ALERT_BAD_CERTIFICATE: u8 = 42;
pub const ALERT_ILLEGAL_PARAMETER: u8 = 47;
pub const ALERT_DECODE_ERROR: u8 = 50;
pub const ALERT_DECRYPT_ERROR: u8 = 51;
pub const ALERT_PROTOCOL_VERSION: u8 = 70;
pub const ALERT_INTERNAL_ERROR: u8 = 80;
pub const ALERT_MISSING_EXTENSION: u8 = 109;
pub const ALERT_NO_APPLICATION_PROTOCOL: u8 = 120;

#[derive(Debug, Clone)]
pub struct TlsError {
    pub alert: u8,
    pub reason: String,
}

fn err<T>(alert: u8, reason: &str) -> Result<T, TlsError> {
    Err(TlsError { alert, reason: reason.to_string() })
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Level {
    Initial = 0,
    Handshake = 1,
    OneRtt = 2,
}

pub struct ServerCrypto {
    pub cert_chain: Vec<Vec<u8>>,
    pub key: PrivateKey,
}

/// Keys negotiated by the handshake.
pub struct Secrets {
    pub level: Level,
    pub suite: Suite,
    pub local: Vec<u8>,
    pub remote: Vec<u8>,
}

#[derive(PartialEq, Eq, Debug, Clone, Copy)]
enum State {
    ClientWaitServerHello,
    ClientWaitEncryptedExtensions,
    ClientWaitCertificate,
    ClientWaitCertificateVerify,
    ClientWaitFinished,
    ServerWaitClientHello,
    ServerWaitFinished,
    Connected,
}

pub struct KeyLog {
    path: Option<std::path::PathBuf>,
}

impl KeyLog {
    pub fn from_env() -> Option<KeyLog> {
        match std::env::var_os("SSLKEYLOGFILE") {
            Some(p) if !p.is_empty() => Some(KeyLog { path: Some(p.into()) }),
            _ => None,
        }
    }
    fn log(&self, label: &str, client_random: &[u8], secret: &[u8]) {
        if let Some(p) = &self.path {
            if let Ok(mut f) = std::fs::OpenOptions::new().append(true).create(true).open(p) {
                let _ = writeln!(f, "{} {} {}", label, hex(client_random), hex(secret));
            }
        }
    }
}

pub struct Tls {
    is_client: bool,
    state: State,
    suite: Option<Suite>,
    transcript: Option<Hasher>,
    pending_transcript: Vec<u8>,
    kx: Option<X25519>,
    client_random: [u8; 32],
    handshake_secret: Vec<u8>,
    master_secret: Vec<u8>,
    c_hs: Vec<u8>,
    s_hs: Vec<u8>,
    c_ap: Vec<u8>,
    s_ap: Vec<u8>,
    recv_buf: [Vec<u8>; 3],
    /// Outgoing handshake data per level.
    pub outgoing: Vec<(Level, Vec<u8>)>,
    /// Newly available secrets.
    pub secrets: Vec<Secrets>,
    pub peer_params: Option<Vec<u8>>,
    local_params: Vec<u8>,
    server_name: String,
    keylog: Option<KeyLog>,
    server: Option<Arc<ServerCrypto>>,
    pub complete: bool,
    pub alpn: Option<Vec<u8>>,
    peer_cert_spki: Option<Vec<u8>>,
}

const HRR_RANDOM: [u8; 32] = [
    0xCF, 0x21, 0xAD, 0x74, 0xE5, 0x9A, 0x61, 0x11, 0xBE, 0x1D, 0x8C, 0x02, 0x1E, 0x65, 0xB8, 0x91, 0xC2, 0xA2, 0x11,
    0x16, 0x7A, 0xBB, 0x8C, 0x5E, 0x07, 0x9E, 0x09, 0xE2, 0xC8, 0xA8, 0x33, 0x9C,
];

fn put_ext<F: FnOnce(&mut Vec<u8>)>(out: &mut Vec<u8>, ty: u16, f: F) {
    put_u16(out, ty);
    put_vec(out, 2, f);
}

fn handshake_msg<F: FnOnce(&mut Vec<u8>)>(ty: u8, f: F) -> Vec<u8> {
    let mut m = vec![ty];
    put_vec(&mut m, 3, f);
    m
}

impl Tls {
    pub fn new_client(server_name: &str, local_params: Vec<u8>, keylog: Option<KeyLog>) -> Tls {
        let mut t = Tls::blank(true, local_params, keylog);
        t.server_name = server_name.to_string();
        t.state = State::ClientWaitServerHello;
        let ch = t.build_client_hello();
        t.pending_transcript.extend_from_slice(&ch);
        t.outgoing.push((Level::Initial, ch));
        t
    }

    pub fn new_server(crypto: Arc<ServerCrypto>, local_params: Vec<u8>, keylog: Option<KeyLog>) -> Tls {
        let mut t = Tls::blank(false, local_params, keylog);
        t.server = Some(crypto);
        t.state = State::ServerWaitClientHello;
        t
    }

    fn blank(is_client: bool, local_params: Vec<u8>, keylog: Option<KeyLog>) -> Tls {
        Tls {
            is_client,
            state: State::Connected,
            suite: None,
            transcript: None,
            pending_transcript: Vec::new(),
            kx: None,
            client_random: [0u8; 32],
            handshake_secret: Vec::new(),
            master_secret: Vec::new(),
            c_hs: Vec::new(),
            s_hs: Vec::new(),
            c_ap: Vec::new(),
            s_ap: Vec::new(),
            recv_buf: [Vec::new(), Vec::new(), Vec::new()],
            outgoing: Vec::new(),
            secrets: Vec::new(),
            peer_params: None,
            local_params,
            server_name: String::new(),
            keylog,
            server: None,
            complete: false,
            alpn: None,
            peer_cert_spki: None,
        }
    }

    pub fn is_handshaking(&self) -> bool {
        self.state != State::Connected
    }

    pub fn suite(&self) -> Option<Suite> {
        self.suite
    }

    fn build_client_hello(&mut self) -> Vec<u8> {
        random_bytes(&mut self.client_random);
        let kx = X25519::generate();
        let public = kx.public;
        self.kx = Some(kx);
        let random = self.client_random;
        let params = self.local_params.clone();
        let sni = self.server_name.clone();
        let sni_is_ip = sni.parse::<std::net::IpAddr>().is_ok() || sni.is_empty();
        handshake_msg(1, |m| {
            put_u16(m, 0x0303);
            m.extend_from_slice(&random);
            m.push(0); // legacy session id
            put_vec(m, 2, |c| {
                put_u16(c, 0x1301);
                put_u16(c, 0x1302);
                put_u16(c, 0x1303);
            });
            m.push(1);
            m.push(0);
            put_vec(m, 2, |e| {
                put_ext(e, 0x39, |x| x.extend_from_slice(&params));
                put_ext(e, 5, |x| x.extend_from_slice(&[1, 0, 0, 0, 0]));
                put_ext(e, 10, |x| {
                    put_vec(x, 2, |g| {
                        put_u16(g, 0x001d);
                        put_u16(g, 0x0017);
                        put_u16(g, 0x0018);
                    })
                });
                put_ext(e, 16, |x| {
                    put_vec(x, 2, |l| {
                        put_vec(l, 1, |p| p.extend_from_slice(ALPN_PERF));
                    })
                });
                if !sni_is_ip {
                    put_ext(e, 0, |x| {
                        put_vec(x, 2, |l| {
                            l.push(0);
                            put_vec(l, 2, |n| n.extend_from_slice(sni.as_bytes()));
                        })
                    });
                }
                put_ext(e, 51, |x| {
                    put_vec(x, 2, |l| {
                        put_u16(l, 0x001d);
                        put_vec(l, 2, |k| k.extend_from_slice(&public));
                    })
                });
                put_ext(e, 43, |x| {
                    put_vec(x, 1, |l| put_u16(l, 0x0304));
                });
                put_ext(e, 13, |x| {
                    put_vec(x, 2, |l| {
                        for s in [0x0503u16, 0x0403, 0x0807, 0x0806, 0x0805, 0x0804, 0x0601, 0x0501, 0x0401] {
                            put_u16(l, s);
                        }
                    })
                });
                put_ext(e, 45, |x| x.extend_from_slice(&[1, 1]));
                put_ext(e, 11, |x| x.extend_from_slice(&[1, 0]));
                put_ext(e, 23, |_| {});
            });
        })
    }

    fn transcript_add(&mut self, msg: &[u8]) {
        match &mut self.transcript {
            Some(h) => h.update(msg),
            None => self.pending_transcript.extend_from_slice(msg),
        }
    }

    fn transcript_hash(&self) -> Vec<u8> {
        self.transcript.as_ref().unwrap().snapshot()
    }

    fn start_transcript(&mut self, suite: Suite) {
        let mut h = Hasher::new(suite.hash());
        h.update(&self.pending_transcript);
        self.pending_transcript.clear();
        self.transcript = Some(h);
    }

    /// Feeds in-order crypto stream data received at `level`.
    pub fn read_handshake(&mut self, level: Level, data: &[u8]) -> Result<(), TlsError> {
        let idx = level as usize;
        self.recv_buf[idx].extend_from_slice(data);
        loop {
            let buf = &self.recv_buf[idx];
            if buf.len() < 4 {
                return Ok(());
            }
            let len = ((buf[1] as usize) << 16) | ((buf[2] as usize) << 8) | buf[3] as usize;
            if len > 1 << 16 {
                return err(ALERT_DECODE_ERROR, "message too large");
            }
            if buf.len() < 4 + len {
                return Ok(());
            }
            let msg: Vec<u8> = buf[..4 + len].to_vec();
            self.recv_buf[idx].drain(..4 + len);
            self.handle_message(level, &msg)?;
        }
    }

    fn expect_level(&self, level: Level, want: Level) -> Result<(), TlsError> {
        if level != want {
            return err(ALERT_UNEXPECTED_MESSAGE, "message at wrong encryption level");
        }
        Ok(())
    }

    fn handle_message(&mut self, level: Level, msg: &[u8]) -> Result<(), TlsError> {
        let ty = msg[0];
        let body = &msg[4..];
        match (self.state, ty) {
            (State::ClientWaitServerHello, 2) => {
                self.expect_level(level, Level::Initial)?;
                self.client_handle_server_hello(msg, body)
            }
            (State::ClientWaitEncryptedExtensions, 8) => {
                self.expect_level(level, Level::Handshake)?;
                self.client_handle_ee(msg, body)
            }
            (State::ClientWaitCertificate, 11) => {
                self.expect_level(level, Level::Handshake)?;
                self.client_handle_certificate(msg, body)
            }
            (State::ClientWaitCertificateVerify, 15) => {
                self.expect_level(level, Level::Handshake)?;
                self.client_handle_cert_verify(msg, body)
            }
            (State::ClientWaitFinished, 20) => {
                self.expect_level(level, Level::Handshake)?;
                self.client_handle_finished(msg, body)
            }
            (State::ServerWaitClientHello, 1) => {
                self.expect_level(level, Level::Initial)?;
                self.server_handle_client_hello(msg, body)
            }
            (State::ServerWaitFinished, 20) => {
                self.expect_level(level, Level::Handshake)?;
                self.server_handle_finished(msg, body)
            }
            (State::Connected, 4) if self.is_client && level == Level::OneRtt => Ok(()), // NewSessionTicket
            (State::Connected, 24) if level == Level::OneRtt => err(ALERT_UNEXPECTED_MESSAGE, "key update not allowed"),
            _ => err(ALERT_UNEXPECTED_MESSAGE, "unexpected handshake message"),
        }
    }

    fn log_secret(&self, label: &str, secret: &[u8]) {
        if let Some(k) = &self.keylog {
            k.log(label, &self.client_random, secret);
        }
    }

    fn derive_handshake_secrets(&mut self, shared: &[u8]) {
        let suite = self.suite.unwrap();
        let h = suite.hash();
        let zeros = vec![0u8; h.len()];
        let early = hkdf_extract(h, &[], &zeros);
        let empty_hash = hash(h, b"");
        let derived = hkdf_expand_label(h, &early, b"derived", &empty_hash, h.len());
        self.handshake_secret = hkdf_extract(h, &derived, shared);
        let th = self.transcript_hash();
        self.c_hs = hkdf_expand_label(h, &self.handshake_secret, b"c hs traffic", &th, h.len());
        self.s_hs = hkdf_expand_label(h, &self.handshake_secret, b"s hs traffic", &th, h.len());
        let derived2 = hkdf_expand_label(h, &self.handshake_secret, b"derived", &empty_hash, h.len());
        self.master_secret = hkdf_extract(h, &derived2, &zeros);
        self.log_secret("CLIENT_HANDSHAKE_TRAFFIC_SECRET", &self.c_hs.clone());
        self.log_secret("SERVER_HANDSHAKE_TRAFFIC_SECRET", &self.s_hs.clone());
        let (local, remote) =
            if self.is_client { (self.c_hs.clone(), self.s_hs.clone()) } else { (self.s_hs.clone(), self.c_hs.clone()) };
        self.secrets.push(Secrets { level: Level::Handshake, suite, local, remote });
    }

    fn derive_app_secrets(&mut self) {
        let suite = self.suite.unwrap();
        let h = suite.hash();
        let th = self.transcript_hash();
        self.c_ap = hkdf_expand_label(h, &self.master_secret, b"c ap traffic", &th, h.len());
        self.s_ap = hkdf_expand_label(h, &self.master_secret, b"s ap traffic", &th, h.len());
        let exp = hkdf_expand_label(h, &self.master_secret, b"exp master", &th, h.len());
        self.log_secret("CLIENT_TRAFFIC_SECRET_0", &self.c_ap.clone());
        self.log_secret("SERVER_TRAFFIC_SECRET_0", &self.s_ap.clone());
        self.log_secret("EXPORTER_SECRET", &exp);
        let (local, remote) =
            if self.is_client { (self.c_ap.clone(), self.s_ap.clone()) } else { (self.s_ap.clone(), self.c_ap.clone()) };
        self.secrets.push(Secrets { level: Level::OneRtt, suite, local, remote });
    }

    fn finished_verify_data(&self, base: &[u8]) -> Vec<u8> {
        let h = self.suite.unwrap().hash();
        let key = hkdf_expand_label(h, base, b"finished", b"", h.len());
        hmac(h, &key, &self.transcript_hash())
    }

    // ---------------- client side ----------------

    fn client_handle_server_hello(&mut self, msg: &[u8], body: &[u8]) -> Result<(), TlsError> {
        let mut r = Reader::new(body);
        let bad = || TlsError { alert: ALERT_DECODE_ERROR, reason: "malformed ServerHello".into() };
        let _ver = r.u16().ok_or_else(bad)?;
        let random = r.bytes(32).ok_or_else(bad)?;
        if random == HRR_RANDOM {
            return err(ALERT_HANDSHAKE_FAILURE, "HelloRetryRequest not supported");
        }
        let _sid = r.vec8().ok_or_else(bad)?;
        let suite_id = r.u16().ok_or_else(bad)?;
        let _comp = r.u8().ok_or_else(bad)?;
        let exts = r.vec16().ok_or_else(bad)?;
        let suite = Suite::from_tls_id(suite_id)
            .ok_or_else(|| TlsError { alert: ALERT_ILLEGAL_PARAMETER, reason: "bad cipher suite".into() })?;
        let mut er = Reader::new(exts);
        let mut share: Option<Vec<u8>> = None;
        let mut version_ok = false;
        while !er.is_empty() {
            let t = er.u16().ok_or_else(bad)?;
            let d = er.vec16().ok_or_else(bad)?;
            match t {
                43 => version_ok = d == [0x03, 0x04],
                51 => {
                    let mut kr = Reader::new(d);
                    let g = kr.u16().ok_or_else(bad)?;
                    let k = kr.vec16().ok_or_else(bad)?;
                    if g != 0x001d {
                        return err(ALERT_ILLEGAL_PARAMETER, "unsupported key share group");
                    }
                    share = Some(k.to_vec());
                }
                _ => {}
            }
        }
        if !version_ok {
            return err(ALERT_PROTOCOL_VERSION, "TLS 1.3 required");
        }
        let share = share.ok_or_else(|| TlsError { alert: ALERT_MISSING_EXTENSION, reason: "no key share".into() })?;
        self.suite = Some(suite);
        self.start_transcript(suite);
        self.transcript_add(msg);
        let shared = self
            .kx
            .as_ref()
            .unwrap()
            .agree(&share)
            .ok_or_else(|| TlsError { alert: ALERT_ILLEGAL_PARAMETER, reason: "bad key share".into() })?;
        self.derive_handshake_secrets(&shared);
        self.state = State::ClientWaitEncryptedExtensions;
        Ok(())
    }

    fn client_handle_ee(&mut self, msg: &[u8], body: &[u8]) -> Result<(), TlsError> {
        let bad = || TlsError { alert: ALERT_DECODE_ERROR, reason: "malformed EncryptedExtensions".into() };
        let mut r = Reader::new(body);
        let exts = r.vec16().ok_or_else(bad)?;
        let mut er = Reader::new(exts);
        while !er.is_empty() {
            let t = er.u16().ok_or_else(bad)?;
            let d = er.vec16().ok_or_else(bad)?;
            match t {
                16 => {
                    let mut ar = Reader::new(d);
                    let list = ar.vec16().ok_or_else(bad)?;
                    let mut lr = Reader::new(list);
                    let p = lr.vec8().ok_or_else(bad)?;
                    self.alpn = Some(p.to_vec());
                }
                0x39 => self.peer_params = Some(d.to_vec()),
                _ => {}
            }
        }
        if self.peer_params.is_none() {
            return err(ALERT_MISSING_EXTENSION, "missing QUIC transport parameters");
        }
        match &self.alpn {
            Some(a) if a == ALPN_PERF => {}
            _ => return err(ALERT_NO_APPLICATION_PROTOCOL, "no application protocol"),
        }
        self.transcript_add(msg);
        self.state = State::ClientWaitCertificate;
        Ok(())
    }

    fn client_handle_certificate(&mut self, msg: &[u8], body: &[u8]) -> Result<(), TlsError> {
        let bad = || TlsError { alert: ALERT_DECODE_ERROR, reason: "malformed Certificate".into() };
        let mut r = Reader::new(body);
        let _ctx = r.vec8().ok_or_else(bad)?;
        let list = r.vec24().ok_or_else(bad)?;
        let mut lr = Reader::new(list);
        let first = lr.vec24().ok_or_else(bad)?;
        self.peer_cert_spki = crate::cert::extract_spki(first);
        self.transcript_add(msg);
        self.state = State::ClientWaitCertificateVerify;
        Ok(())
    }

    fn client_handle_cert_verify(&mut self, msg: &[u8], body: &[u8]) -> Result<(), TlsError> {
        let bad = || TlsError { alert: ALERT_DECODE_ERROR, reason: "malformed CertificateVerify".into() };
        let mut r = Reader::new(body);
        let scheme = r.u16().ok_or_else(bad)?;
        let sig = r.vec16().ok_or_else(bad)?;
        let mut content = vec![0x20u8; 64];
        content.extend_from_slice(b"TLS 1.3, server CertificateVerify\0");
        content.extend_from_slice(&self.transcript_hash());
        if let Some(spki) = &self.peer_cert_spki {
            if !verify_signature(spki, scheme, &content, sig) {
                return err(ALERT_DECRYPT_ERROR, "invalid peer signature");
            }
        }
        self.transcript_add(msg);
        self.state = State::ClientWaitFinished;
        Ok(())
    }

    fn client_handle_finished(&mut self, msg: &[u8], body: &[u8]) -> Result<(), TlsError> {
        let expected = self.finished_verify_data(&self.s_hs.clone());
        if body != &expected[..] {
            return err(ALERT_DECRYPT_ERROR, "invalid finished");
        }
        self.transcript_add(msg);
        self.derive_app_secrets();
        let vd = self.finished_verify_data(&self.c_hs.clone());
        let fin = handshake_msg(20, |m| m.extend_from_slice(&vd));
        self.transcript_add(&fin);
        self.outgoing.push((Level::Handshake, fin));
        self.state = State::Connected;
        self.complete = true;
        Ok(())
    }

    // ---------------- server side ----------------

    fn server_handle_client_hello(&mut self, msg: &[u8], body: &[u8]) -> Result<(), TlsError> {
        let bad = || TlsError { alert: ALERT_DECODE_ERROR, reason: "malformed ClientHello".into() };
        let mut r = Reader::new(body);
        let _ver = r.u16().ok_or_else(bad)?;
        let random = r.bytes(32).ok_or_else(bad)?;
        self.client_random.copy_from_slice(random);
        let sid = r.vec8().ok_or_else(bad)?.to_vec();
        let suites = r.vec16().ok_or_else(bad)?;
        let _comp = r.vec8().ok_or_else(bad)?;
        let exts = r.vec16().ok_or_else(bad)?;
        let mut client_suites = Vec::new();
        let mut sr = Reader::new(suites);
        while let Some(s) = sr.u16() {
            client_suites.push(s);
        }
        let mut er = Reader::new(exts);
        let mut x25519_share: Option<Vec<u8>> = None;
        let mut tls13 = false;
        let mut alpn_ok = false;
        let mut alpn_present = false;
        let mut sig_schemes: Vec<u16> = Vec::new();
        let mut sni_present = false;
        while !er.is_empty() {
            let t = er.u16().ok_or_else(bad)?;
            let d = er.vec16().ok_or_else(bad)?;
            match t {
                0 => sni_present = true,
                43 => {
                    let mut vr = Reader::new(d);
                    let l = vr.vec8().ok_or_else(bad)?;
                    let mut lr = Reader::new(l);
                    while let Some(v) = lr.u16() {
                        if v == 0x0304 {
                            tls13 = true;
                        }
                    }
                }
                51 => {
                    let mut kr = Reader::new(d);
                    let l = kr.vec16().ok_or_else(bad)?;
                    let mut lr = Reader::new(l);
                    while !lr.is_empty() {
                        let g = lr.u16().ok_or_else(bad)?;
                        let k = lr.vec16().ok_or_else(bad)?;
                        if g == 0x001d && x25519_share.is_none() {
                            x25519_share = Some(k.to_vec());
                        }
                    }
                }
                16 => {
                    alpn_present = true;
                    let mut ar = Reader::new(d);
                    let l = ar.vec16().ok_or_else(bad)?;
                    let mut lr = Reader::new(l);
                    while !lr.is_empty() {
                        let p = lr.vec8().ok_or_else(bad)?;
                        if p == ALPN_PERF {
                            alpn_ok = true;
                        }
                    }
                }
                13 => {
                    let mut sr = Reader::new(d);
                    let l = sr.vec16().ok_or_else(bad)?;
                    let mut lr = Reader::new(l);
                    while let Some(s) = lr.u16() {
                        sig_schemes.push(s);
                    }
                }
                0x39 => self.peer_params = Some(d.to_vec()),
                _ => {}
            }
        }
        if !tls13 {
            return err(ALERT_PROTOCOL_VERSION, "TLS 1.3 required");
        }
        if self.peer_params.is_none() {
            return err(ALERT_MISSING_EXTENSION, "missing QUIC transport parameters");
        }
        if !alpn_present || !alpn_ok {
            return err(ALERT_NO_APPLICATION_PROTOCOL, "peer doesn't support any known protocol");
        }
        self.alpn = Some(ALPN_PERF.to_vec());
        let suite = client_suites
            .iter()
            .filter_map(|s| Suite::from_tls_id(*s))
            .next()
            .ok_or_else(|| TlsError { alert: ALERT_HANDSHAKE_FAILURE, reason: "no common cipher suite".into() })?;
        let share = x25519_share
            .ok_or_else(|| TlsError { alert: ALERT_HANDSHAKE_FAILURE, reason: "no supported key share".into() })?;
        let crypto = self.server.clone().unwrap();
        let scheme = choose_scheme(crypto.key.kind(), &sig_schemes)
            .ok_or_else(|| TlsError { alert: ALERT_HANDSHAKE_FAILURE, reason: "no common signature scheme".into() })?;

        self.suite = Some(suite);
        self.start_transcript(suite);
        self.transcript_add(msg);

        let kx = X25519::generate();
        let shared = kx
            .agree(&share)
            .ok_or_else(|| TlsError { alert: ALERT_ILLEGAL_PARAMETER, reason: "bad key share".into() })?;
        let mut srandom = [0u8; 32];
        random_bytes(&mut srandom);
        let public = kx.public;
        let sh = handshake_msg(2, |m| {
            put_u16(m, 0x0303);
            m.extend_from_slice(&srandom);
            put_vec(m, 1, |s| s.extend_from_slice(&sid));
            put_u16(m, suite.tls_id());
            m.push(0);
            put_vec(m, 2, |e| {
                put_ext(e, 51, |x| {
                    put_u16(x, 0x001d);
                    put_vec(x, 2, |k| k.extend_from_slice(&public));
                });
                put_ext(e, 43, |x| put_u16(x, 0x0304));
            });
        });
        self.transcript_add(&sh);
        self.outgoing.push((Level::Initial, sh));
        self.derive_handshake_secrets(&shared);

        let params = self.local_params.clone();
        let ee = handshake_msg(8, |m| {
            put_vec(m, 2, |e| {
                if sni_present {
                    put_ext(e, 0, |_| {});
                }
                put_ext(e, 16, |x| {
                    put_vec(x, 2, |l| put_vec(l, 1, |p| p.extend_from_slice(ALPN_PERF)));
                });
                put_ext(e, 0x39, |x| x.extend_from_slice(&params));
            });
        });
        self.transcript_add(&ee);
        let cert = handshake_msg(11, |m| {
            m.push(0);
            put_vec(m, 3, |l| {
                for c in &crypto.cert_chain {
                    put_vec(l, 3, |d| d.extend_from_slice(c));
                    put_u16(l, 0);
                }
            });
        });
        self.transcript_add(&cert);
        let mut content = vec![0x20u8; 64];
        content.extend_from_slice(b"TLS 1.3, server CertificateVerify\0");
        content.extend_from_slice(&self.transcript_hash());
        let sig = crypto
            .key
            .sign(scheme, &content)
            .ok_or_else(|| TlsError { alert: ALERT_INTERNAL_ERROR, reason: "signing failed".into() })?;
        let cv = handshake_msg(15, |m| {
            put_u16(m, scheme);
            put_vec(m, 2, |s| s.extend_from_slice(&sig));
        });
        self.transcript_add(&cv);
        let vd = self.finished_verify_data(&self.s_hs.clone());
        let fin = handshake_msg(20, |m| m.extend_from_slice(&vd));
        self.transcript_add(&fin);
        let mut flight = ee;
        flight.extend_from_slice(&cert);
        flight.extend_from_slice(&cv);
        flight.extend_from_slice(&fin);
        self.outgoing.push((Level::Handshake, flight));
        self.derive_app_secrets();
        self.state = State::ServerWaitFinished;
        Ok(())
    }

    fn server_handle_finished(&mut self, msg: &[u8], body: &[u8]) -> Result<(), TlsError> {
        let expected = self.finished_verify_data(&self.c_hs.clone());
        if body != &expected[..] {
            return err(ALERT_DECRYPT_ERROR, "invalid finished");
        }
        self.transcript_add(msg);
        self.state = State::Connected;
        self.complete = true;
        Ok(())
    }
}

fn choose_scheme(kind: KeyKind, offered: &[u16]) -> Option<u16> {
    let prefs: &[u16] = match kind {
        KeyKind::EcP256 => &[0x0403],
        KeyKind::EcP384 => &[0x0503],
        KeyKind::Ed25519 => &[0x0807],
        KeyKind::Rsa => &[0x0806, 0x0805, 0x0804],
        KeyKind::Other => &[],
    };
    prefs.iter().copied().find(|p| offered.contains(p))
}
