fn b64_val(c: u8) -> Option<u8> {
    match c {
        b'A'..=b'Z' => Some(c - b'A'),
        b'a'..=b'z' => Some(c - b'a' + 26),
        b'0'..=b'9' => Some(c - b'0' + 52),
        b'+' => Some(62),
        b'/' => Some(63),
        _ => None,
    }
}

pub fn base64_decode(input: &[u8]) -> Result<Vec<u8>, String> {
    let mut chars: Vec<u8> = Vec::with_capacity(input.len());
    let mut padding = 0usize;
    for &c in input {
        if c == b' ' || c == b'\t' || c == b'\r' || c == b'\n' {
            continue;
        }
        if c == b'=' {
            padding += 1;
            continue;
        }
        let v = b64_val(c).ok_or_else(|| format!("InvalidCharacter({})", c))?;
        if padding > 0 {
            return Err("InvalidTrailingPadding".into());
        }
        chars.push(v);
    }
    if chars.len() % 4 == 1 {
        return Err("InvalidTrailingPadding".into());
    }
    if padding > 0 && (chars.len() + padding) % 4 != 0 {
        return Err("InvalidTrailingPadding".into());
    }
    let mut out = Vec::with_capacity(chars.len() * 3 / 4);
    for chunk in chars.chunks(4) {
        let mut n = 0u32;
        for (i, v) in chunk.iter().enumerate() {
            n |= (*v as u32) << (18 - 6 * i);
        }
        let bytes = n.to_be_bytes();
        let k = chunk.len() - 1;
        out.extend_from_slice(&bytes[1..1 + k]);
    }
    Ok(out)
}

pub fn base64_encode(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut s = String::new();
    for chunk in data.chunks(3) {
        let mut n = 0u32;
        for (i, b) in chunk.iter().enumerate() {
            n |= (*b as u32) << (16 - 8 * i);
        }
        for i in 0..4 {
            if i <= chunk.len() {
                s.push(T[((n >> (18 - 6 * i)) & 63) as usize] as char);
            } else {
                s.push('=');
            }
        }
    }
    s
}

/// Parses all PEM sections in `data`, returning (label, der).
pub fn parse_pem(data: &[u8]) -> Result<Vec<(Vec<u8>, Vec<u8>)>, PemError> {
    let mut out = Vec::new();
    let mut current: Option<(Vec<u8>, Vec<u8>)> = None;
    for raw_line in data.split(|b| *b == b'\n') {
        let mut line = raw_line;
        while let Some((&last, rest)) = line.split_last() {
            if last == b'\r' || last == b' ' || last == b'\t' {
                line = rest;
            } else {
                break;
            }
        }
        match &mut current {
            None => {
                if line.starts_with(b"-----BEGIN ") && line.ends_with(b"-----") && line.len() >= 16 {
                    let label = line[11..line.len() - 5].to_vec();
                    current = Some((label, Vec::new()));
                }
            }
            Some((label, body)) => {
                let mut end = b"-----END ".to_vec();
                end.extend_from_slice(label);
                end.extend_from_slice(b"-----");
                if line.starts_with(&end[..]) {
                    let der = base64_decode(body).map_err(PemError::Base64)?;
                    out.push((label.clone(), der));
                    current = None;
                } else {
                    body.extend_from_slice(line);
                }
            }
        }
    }
    if let Some((label, _)) = current {
        return Err(PemError::MissingSectionEnd(label));
    }
    Ok(out)
}

