// ---------------------------------------------------------------------------
// Minimal DER parsing

fn der_read(buf: &[u8]) -> Option<(u8, &[u8], &[u8])> {
    // returns (tag, content, rest)
    if buf.len() < 2 {
        return None;
    }
    let tag = buf[0];
    let (len, hl) = if buf[1] < 0x80 {
        (buf[1] as usize, 2)
    } else {
        let n = (buf[1] & 0x7f) as usize;
        if n == 0 || n > 4 || buf.len() < 2 + n {
            return None;
        }
        let mut l = 0usize;
        for i in 0..n {
            l = (l << 8) | buf[2 + i] as usize;
        }
        (l, 2 + n)
    };
    if buf.len() < hl + len {
        return None;
    }
    Some((tag, &buf[hl..hl + len], &buf[hl + len..]))
}

fn der_read_full(buf: &[u8]) -> Option<(u8, &[u8], &[u8], &[u8])> {
    // returns (tag, content, full element, rest)
    let (tag, content, rest) = der_read(buf)?;
    let full_len = buf.len() - rest.len();
    Some((tag, content, &buf[..full_len], rest))
}

/// Extracts the DER encoded SubjectPublicKeyInfo from an X.509 certificate.
pub fn extract_spki(cert: &[u8]) -> Option<Vec<u8>> {
    let (tag, cert_body, rest) = der_read(cert)?;
    if tag != 0x30 || !rest.is_empty() {
        return None;
    }
    let (tag, tbs, rest) = der_read(cert_body)?;
    if tag != 0x30 {
        return None;
    }
    // signatureAlgorithm and signature must follow
    let (t2, _, rest2) = der_read(rest)?;
    let (t3, _, rest3) = der_read(rest2)?;
    if t2 != 0x30 || t3 != 0x03 || !rest3.is_empty() {
        return None;
    }
    let mut p = tbs;
    // optional version [0]
    if !p.is_empty() && p[0] == 0xa0 {
        let (_, _, r) = der_read(p)?;
        p = r;
    }
    // serial, signature, issuer, validity, subject
    let (t, _, r) = der_read(p)?;
    if t != 0x02 {
        return None;
    }
    p = r;
    for expected in [0x30u8, 0x30, 0x30, 0x30] {
        let (t, _, r) = der_read(p)?;
        if t != expected {
            return None;
        }
        p = r;
    }
    let (t, _, full, _) = der_read_full(p)?;
    if t != 0x30 {
        return None;
    }
    Some(full.to_vec())
}

// ---------------------------------------------------------------------------
// DER writing

fn der(tag: u8, content: &[u8]) -> Vec<u8> {
    let mut out = vec![tag];
    let l = content.len();
    if l < 0x80 {
        out.push(l as u8);
    } else if l < 0x100 {
        out.push(0x81);
        out.push(l as u8);
    } else if l < 0x10000 {
        out.push(0x82);
        out.push((l >> 8) as u8);
        out.push(l as u8);
    } else {
        out.push(0x83);
        out.push((l >> 16) as u8);
        out.push((l >> 8) as u8);
        out.push(l as u8);
    }
    out.extend_from_slice(content);
    out
}

fn seq(items: &[Vec<u8>]) -> Vec<u8> {
    der(0x30, &items.concat())
}

/// Generates a self-signed ECDSA P-256 certificate for "localhost".
pub fn generate_self_signed() -> Option<(Vec<u8>, PrivateKey)> {
    let key = PrivateKey::generate_p256()?;
    let spki = key.public_spki();
    let ecdsa_sha256 = seq(&[der(0x06, &[0x2a, 0x86, 0x48, 0xce, 0x3d, 0x04, 0x03, 0x02])]);
    let name = seq(&[der(
        0x31,
        &seq(&[der(0x06, &[0x55, 0x04, 0x03]), der(0x0c, b"rcgen self signed cert")]),
    )]);
    let mut serial = [0u8; 20];
    random_bytes(&mut serial);
    serial[0] &= 0x7f;
    if serial[0] == 0 {
        serial[0] = 1;
    }
    let validity = seq(&[der(0x17, b"750101000000Z"), der(0x18, b"40960101000000Z")]);
    let san = seq(&[der(0x82, b"localhost")]);
    let ext = der(0xa3, &seq(&[seq(&[der(0x06, &[0x55, 0x1d, 0x11]), der(0x04, &san)])]));
    let tbs = seq(&[
        der(0xa0, &der(0x02, &[0x02])),
        der(0x02, &serial),
        ecdsa_sha256.clone(),
        name.clone(),
        validity,
        name,
        spki,
        ext,
    ]);
    // Signature over the TBS certificate with ECDSA/SHA-256.
    let sig = key.sign(0x0403, &tbs)?;
    let mut bits = vec![0u8];
    bits.extend_from_slice(&sig);
    let cert = seq(&[tbs, ecdsa_sha256, der(0x03, &bits)]);
    Some((cert, key))
}
