//! Set of non-overlapping half-open u64 ranges.
#![allow(dead_code)]

use std::collections::BTreeMap;
use std::ops::Range;

#[derive(Default, Clone, Debug)]
pub struct RangeSet {
    map: BTreeMap<u64, u64>, // start -> end (exclusive)
}

impl RangeSet {
    pub fn new() -> Self {
        RangeSet { map: BTreeMap::new() }
    }

    pub fn is_empty(&self) -> bool {
        self.map.is_empty()
    }

    pub fn len(&self) -> usize {
        self.map.len()
    }

    pub fn contains(&self, v: u64) -> bool {
        match self.map.range(..=v).next_back() {
            Some((_, &e)) => v < e,
            None => false,
        }
    }

    /// Returns true if the whole range is contained.
    pub fn contains_range(&self, r: Range<u64>) -> bool {
        if r.start >= r.end {
            return true;
        }
        match self.map.range(..=r.start).next_back() {
            Some((_, &e)) => r.end <= e,
            None => false,
        }
    }

    /// Inserts a range, returns true if anything new was added.
    pub fn insert(&mut self, r: Range<u64>) -> bool {
        let (mut start, mut end) = (r.start, r.end);
        if start >= end {
            return false;
        }
        if self.contains_range(start..end) {
            return false;
        }
        // merge with previous
        if let Some((&s, &e)) = self.map.range(..=start).next_back() {
            if e >= start {
                start = s;
                if e > end {
                    end = e;
                }
            }
        }
        // merge with following
        let keys: Vec<u64> = self.map.range(start..=end).map(|(&s, _)| s).collect();
        for k in keys {
            let e = self.map.remove(&k).unwrap();
            if e > end {
                end = e;
            }
        }
        self.map.insert(start, end);
        true
    }

    pub fn insert_one(&mut self, v: u64) -> bool {
        self.insert(v..v + 1)
    }

    /// Removes a range.
    pub fn remove(&mut self, r: Range<u64>) {
        if r.start >= r.end {
            return;
        }
        let mut to_add = Vec::new();
        let keys: Vec<(u64, u64)> = {
            let mut v: Vec<(u64, u64)> = Vec::new();
            if let Some((&s, &e)) = self.map.range(..r.start).next_back() {
                if e > r.start {
                    v.push((s, e));
                }
            }
            for (&s, &e) in self.map.range(r.start..r.end) {
                v.push((s, e));
            }
            v
        };
        for (s, e) in keys {
            self.map.remove(&s);
            if s < r.start {
                to_add.push((s, r.start));
            }
            if e > r.end {
                to_add.push((r.end, e));
            }
        }
        for (s, e) in to_add {
            self.map.insert(s, e);
        }
    }

    pub fn min(&self) -> Option<u64> {
        self.map.iter().next().map(|(&s, _)| s)
    }

    pub fn max(&self) -> Option<u64> {
        self.map.iter().next_back().map(|(_, &e)| e - 1)
    }

    pub fn first_range(&self) -> Option<Range<u64>> {
        self.map.iter().next().map(|(&s, &e)| s..e)
    }

    /// Removes and returns up to `max_len` from the start of the first range.
    pub fn pop_front(&mut self, max_len: u64) -> Option<Range<u64>> {
