pub struct RecvStream {
    pub id: u64,
    ready: VecDeque<u8>,
    pub read_offset: u64,
    contiguous_end: u64,
    out_of_order: BTreeMap<u64, Vec<u8>>,
    pub final_size: Option<u64>,
    pub max_received: u64,
    pub max_data: u64,
    pub window: u64,
    pub reset: Option<u64>,
    pub fin_read: bool,
    pub stop_sending_pending: Option<u64>,
}

pub enum RecvError {
    FlowControl,
    FinalSize,
}

impl RecvStream {
    pub fn new(id: u64, window: u64) -> Self {
        RecvStream {
            id,
            ready: VecDeque::new(),
            read_offset: 0,
            contiguous_end: 0,
            out_of_order: BTreeMap::new(),
            final_size: None,
            max_received: 0,
            max_data: window,
            window,
            reset: None,
            fin_read: false,
            stop_sending_pending: None,
        }
    }

    /// Ingests a STREAM frame. Returns the increase of the highest received offset.
    pub fn ingest(&mut self, offset: u64, data: &[u8], fin: bool) -> Result<u64, RecvError> {
        let end = offset + data.len() as u64;
        if end > self.max_data {
            return Err(RecvError::FlowControl);
        }
        if let Some(fs) = self.final_size {
            if end > fs || (fin && end != fs) {
                return Err(RecvError::FinalSize);
            }
        }
        if fin {
            if end < self.max_received {
                return Err(RecvError::FinalSize);
            }
            self.final_size = Some(end);
        }
        let increase = end.saturating_sub(self.max_received);
        if end > self.max_received {
            self.max_received = end;
        }
        if self.reset.is_some() || data.is_empty() {
            return Ok(increase);
        }
        if end <= self.contiguous_end {
            return Ok(increase);
        }
        if offset <= self.contiguous_end {
            let skip = (self.contiguous_end - offset) as usize;
            self.ready.extend(data[skip..].iter());
            self.contiguous_end = end;
            self.drain_out_of_order();
        } else {
            // store out of order (may overlap; keep larger)
            match self.out_of_order.get(&offset) {
                Some(existing) if existing.len() >= data.len() => {}
                _ => {
                    self.out_of_order.insert(offset, data.to_vec());
                }
            }
        }
        Ok(increase)
    }

    fn drain_out_of_order(&mut self) {
        loop {
            let first = match self.out_of_order.iter().next() {
                Some((&o, _)) => o,
                None => return,
            };
            if first > self.contiguous_end {
                return;
            }
            let seg = self.out_of_order.remove(&first).unwrap();
            let end = first + seg.len() as u64;
            if end > self.contiguous_end {
                let skip = (self.contiguous_end - first) as usize;
                self.ready.extend(seg[skip..].iter());
                self.contiguous_end = end;
            }
        }
    }

    pub fn readable(&self) -> bool {
        !self.ready.is_empty() || self.is_fin_ready() || self.reset.is_some()
    }

    pub fn is_fin_ready(&self) -> bool {
        match self.final_size {
            Some(fs) => self.read_offset == fs,
            None => false,
        }
    }

    /// Reads up to `max` bytes into `out` (if given). Returns number of bytes consumed.
    pub fn read(&mut self, max: usize, out: Option<&mut Vec<u8>>) -> usize {
        let n = max.min(self.ready.len());
        if let Some(o) = out {
            o.extend(self.ready.drain(..n));
        } else {
            self.ready.drain(..n);
        }
        self.read_offset += n as u64;
        n
    }

    /// Whether a MAX_STREAM_DATA update should be sent.
    pub fn should_update_window(&self) -> bool {
        self.final_size.is_none() && self.reset.is_none() && self.max_data - self.read_offset < self.window / 2
    }

    pub fn new_max_data(&mut self) -> u64 {
        self.max_data = self.read_offset + self.window;
        self.max_data
    }
}
