    pub fn new(initial: Duration) -> Self {
        Rtt { latest: initial, smoothed: None, var: initial / 2, min: initial, initial }
    }

    pub fn get(&self) -> Duration {
        self.smoothed.unwrap_or(self.latest)
    }

    pub fn conservative(&self) -> Duration {
        self.get().max(self.latest)
    }

    pub fn pto_base(&self) -> Duration {
        self.get() + (4 * self.var).max(GRANULARITY)
    }

    pub fn update(&mut self, ack_delay: Duration, rtt: Duration) {
        self.latest = rtt;
        match self.smoothed {
            None => {
                self.min = rtt;
                self.smoothed = Some(rtt);
                self.var = rtt / 2;
            }
            Some(srtt) => {
                if rtt < self.min {
                    self.min = rtt;
                }
                let adjusted = if rtt >= self.min + ack_delay { rtt - ack_delay } else { rtt };
                let var_sample = if srtt > adjusted { srtt - adjusted } else { adjusted - srtt };
                self.var = (3 * self.var + var_sample) / 4;
                self.smoothed = Some((7 * srtt + adjusted) / 8);
            }
        }
    }
}

