    k: f64,
    w_max: f64,
    epoch_start: Option<Instant>,
    cwnd_inc: u64,
    w_est: f64,
    pub events: u64,
}

const INITIAL_WINDOW_PACKETS: u64 = 10;
const MIN_WINDOW_PACKETS: u64 = 2;
const BETA_CUBIC: f64 = 0.7;
const C_CUBIC: f64 = 0.4;

impl Congestion {
    pub fn new(alg: CongestionAlgorithm, mtu: u16) -> Self {
