        }
    }

    fn min_window(&self) -> u64 {
        MIN_WINDOW_PACKETS * self.mtu
    }

    pub fn in_recovery(&self, sent: Instant) -> bool {
        match self.recovery_start {
            Some(r) => sent <= r,
            None => false,
        }
    }

    pub fn on_ack(&mut self, now: Instant, sent: Instant, bytes: u64, app_limited: bool, rtt: &Rtt) {
        if app_limited || self.in_recovery(sent) {
            return;
        }
        if self.window < self.ssthresh {
            self.window += bytes;
            return;
        }
        match self.alg {
            CongestionAlgorithm::NewReno => {
                self.bytes_acked += bytes;
                if self.bytes_acked >= self.window {
                    self.bytes_acked -= self.window;
                    self.window += self.mtu;
                }
            }
            CongestionAlgorithm::Cubic | CongestionAlgorithm::Bbr => {
                let start = match self.epoch_start {
                    Some(s) => s,
                    None => {
                        self.epoch_start = Some(now);
                        let cwnd = self.window as f64 / self.mtu as f64;
                        if self.w_max <= cwnd {
                            self.k = 0.0;
                            self.w_max = cwnd;
                        } else {
