                        }
                        self.w_est = cwnd;
                        now
                    }
                };
                let t = (now - start + rtt.get()).as_secs_f64();
                let w_cubic = C_CUBIC * (t - self.k).powi(3) + self.w_max;
                // Reno-friendly estimate
                let cwnd_pkts = self.window as f64 / self.mtu as f64;
