                    self.cwnd_inc += inc.max(1);
                    if self.cwnd_inc >= self.mtu {
                        self.window += self.cwnd_inc;
                        self.cwnd_inc = 0;
                    }
                }
            }
        }
    }

    pub fn on_congestion_event(&mut self, now: Instant, sent: Instant, persistent: bool) {
        if self.in_recovery(sent) {
            return;
        }
        self.events += 1;
        self.recovery_start = Some(now);
        match self.alg {
            CongestionAlgorithm::NewReno => {
                self.window = (self.window / 2).max(self.min_window());
                self.ssthresh = self.window;
            }
            CongestionAlgorithm::Cubic | CongestionAlgorithm::Bbr => {
                let cwnd = self.window as f64 / self.mtu as f64;
                // fast convergence
                if cwnd < self.w_max {
                    self.w_max = cwnd * (1.0 + BETA_CUBIC) / 2.0;
                } else {
                    self.w_max = cwnd;
                }
                self.window = ((self.window as f64 * BETA_CUBIC) as u64).max(self.min_window());
                self.ssthresh = self.window;
                self.epoch_start = None;
                self.cwnd_inc = 0;
            }
        }
        if persistent {
            self.window = self.min_window();
        }
    }
}
