}

pub fn transport_code_desc(code: u64) -> String {
    match code {
        0x0 => "the connection is being closed abruptly in the absence of any error".into(),
        0x1 => "the endpoint encountered an internal error and cannot continue with the connection".into(),
        0x2 => "the server refused to accept a new connection".into(),
        0x3 => "received more data than permitted in advertised data limits".into(),
        0x4 => "received a frame for a stream identifier that exceeded advertised the stream limit for the corresponding stream type".into(),
        0x5 => "received a frame for a stream that was not in a state that permitted that frame".into(),
        0x6 => "received a STREAM frame or a RESET_STREAM frame containing a different final size to the one already established".into(),
        0x7 => "received a frame that was badly formatted".into(),
        0x8 => "received transport parameters that were badly formatted, included an invalid value, was absent even though it is mandatory, was present though it is forbidden, or is otherwise in error".into(),
        0x9 => "the number of connection IDs provided by the peer exceeds the advertised active_connection_id_limit".into(),
        0xa => "detected an error with protocol compliance that was not covered by more specific error codes".into(),
        0xb => "received an invalid Retry Token in a client Initial".into(),
        0xc => "the application or application protocol caused the connection to be closed during the handshake".into(),
        0xd => "received more data in CRYPTO frames than can be buffered".into(),
        0xe => "key update error".into(),
        0xf => "the endpoint has reached the confidentiality or integrity limit for the AEAD algorithm".into(),
        0x10 => "no viable network path exists".into(),
        0x100..=0x1ff => format!("the cryptographic handshake failed: error {}", code & 0xff),
        _ => format!("unknown error code {:#x}", code),
    }
}

fn frame_type_name(t: u64) -> String {
    match t {
        0x00 => "PADDING".into(),
        0x01 => "PING".into(),
        0x02 => "ACK".into(),
        0x03 => "ACK_ECN".into(),
        0x04 => "RESET_STREAM".into(),
        0x05 => "STOP_SENDING".into(),
        0x06 => "CRYPTO".into(),
        0x07 => "NEW_TOKEN".into(),
        0x08..=0x0f => "STREAM".into(),
        0x10 => "MAX_DATA".into(),
        0x11 => "MAX_STREAM_DATA".into(),
        0x12 => "MAX_STREAMS_BIDI".into(),
        0x13 => "MAX_STREAMS_UNI".into(),
        0x14 => "DATA_BLOCKED".into(),
        0x15 => "STREAM_DATA_BLOCKED".into(),
        0x16 => "STREAMS_BLOCKED_BIDI".into(),
