impl fmt::Display for ConnError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConnError::VersionMismatch => f.write_str("peer doesn't implement any supported version"),
            ConnError::Transport { code, frame_type, reason } => {
                f.write_str(&transport_code_desc(*code))?;
                if let Some(t) = frame_type {
                    write!(f, " in {}", frame_type_name(*t))?;
                }
                if !reason.is_empty() {
                    write!(f, ": {}", reason)?;
                }
                Ok(())
            }
            ConnError::ConnectionClosed { code, frame_type, reason } => {
                f.write_str("aborted by peer: ")?;
                f.write_str(&transport_code_desc(*code))?;
                if let Some(t) = frame_type {
                    write!(f, " in {}", frame_type_name(*t))?;
                }
                if !reason.is_empty() {
                    write!(f, ": {}", String::from_utf8_lossy(reason))?;
                }
                Ok(())
            }
            ConnError::ApplicationClosed { code, reason } => {
                f.write_str("closed by peer: ")?;
                if reason.is_empty() {
                    write!(f, "{}", code)
                } else {
                    write!(f, "{} (code {})", String::from_utf8_lossy(reason), code)
                }
            }
            ConnError::Reset => f.write_str("reset by peer"),
            ConnError::TimedOut => f.write_str("timed out"),
            ConnError::LocallyClosed => f.write_str("closed"),
            ConnError::CidsExhausted => f.write_str("CIDs exhausted"),
        }
    }
