// ---------------------------------------------------------------------------
// Internal structures

#[derive(Debug, Clone)]
enum SentFrame {
    Crypto { offset: u64, len: u64 },
    Stream { id: u64, offset: u64, len: u64, fin: bool },
    MaxData,
    MaxStreamData(u64),
    MaxStreams(bool),
    NewCid(u64),
    RetireCid(u64),
    HandshakeDone,
    ResetStream(u64),
    StopSending(u64),
    AckFrequency,
}

struct SentPacket {
    time: Instant,
    size: u16,
    ack_eliciting: bool,
    in_flight: bool,
    frames: Vec<SentFrame>,
    largest_ack: Option<u64>,
    mtu_probe: Option<u16>,
    key_phase: bool,
}

struct CryptoSend {
    data: Vec<u8>,
    next: u64,
    retransmit: RangeSet,
    acked: RangeSet,
}

impl CryptoSend {
    fn new() -> Self {
        CryptoSend { data: Vec::new(), next: 0, retransmit: RangeSet::new(), acked: RangeSet::new() }
    }
    fn has_pending(&self) -> bool {
        !self.retransmit.is_empty() || (self.next as usize) < self.data.len()
    }
}

struct PacketSpace {
    next_pn: u64,
    largest_acked: Option<u64>,
    largest_acked_time: Option<Instant>,
    sent: BTreeMap<u64, SentPacket>,
    ack_eliciting_in_flight: u64,
    in_flight_bytes: u64,
    time_of_last_ack_eliciting: Option<Instant>,
    loss_time: Option<Instant>,
    rx: RangeSet,
    largest_rx: Option<u64>,
    largest_rx_time: Option<Instant>,
    ack_eliciting_since_ack: u64,
    ack_immediate: bool,
    ack_deadline: Option<Instant>,
    unacked_rx: bool,
    crypto_send: CryptoSend,
    crypto_recv: RecvStream,
    probes: u32,
    keys: Option<Keys>,
    ping_pending: bool,
    undecryptable: Vec<Vec<u8>>,
}

impl PacketSpace {
    fn new() -> Self {
        PacketSpace {
            next_pn: 0,
            largest_acked: None,
            largest_acked_time: None,
            sent: BTreeMap::new(),
            ack_eliciting_in_flight: 0,
            in_flight_bytes: 0,
            time_of_last_ack_eliciting: None,
            loss_time: None,
            rx: RangeSet::new(),
            largest_rx: None,
            largest_rx_time: None,
            ack_eliciting_since_ack: 0,
            ack_immediate: false,
            ack_deadline: None,
            unacked_rx: false,
            crypto_send: CryptoSend::new(),
            crypto_recv: RecvStream::new(0, 1 << 40),
            probes: 0,
            keys: None,
            ping_pending: false,
            undecryptable: Vec::new(),
        }
    }
}

struct OneRtt {
    suite: Suite,
    phase: bool,
    local: Aead,
    remote: Aead,
    hp_local: HeaderKey,
    hp_remote: HeaderKey,
    local_secret: Vec<u8>,
    remote_secret: Vec<u8>,
    next_remote: Option<Aead>,
    prev_remote: Option<Aead>,
    sent_in_phase: u64,
    first_pn_in_phase: Option<u64>,
    phase_acked: bool,
}

fn aead_from_secret(suite: Suite, secret: &[u8]) -> Aead {
    let h = suite.hash();
    let key = hkdf_expand_label(h, secret, b"quic key", b"", suite.key_len());
    let iv = hkdf_expand_label(h, secret, b"quic iv", b"", 12);
    Aead::new(suite, &key, &iv)
}

fn hp_from_secret(suite: Suite, secret: &[u8]) -> HeaderKey {
    let h = suite.hash();
    let hp = hkdf_expand_label(h, secret, b"quic hp", b"", suite.key_len());
    HeaderKey::new(suite, &hp)
}

impl OneRtt {
    fn new(suite: Suite, local_secret: Vec<u8>, remote_secret: Vec<u8>) -> Self {
        OneRtt {
            suite,
            phase: false,
            local: aead_from_secret(suite, &local_secret),
            remote: aead_from_secret(suite, &remote_secret),
            hp_local: hp_from_secret(suite, &local_secret),
            hp_remote: hp_from_secret(suite, &remote_secret),
            local_secret,
            remote_secret,
            next_remote: None,
            prev_remote: None,
            sent_in_phase: 0,
            first_pn_in_phase: None,
            phase_acked: true,
        }
    }

    fn next_remote_key(&mut self) -> &Aead {
        if self.next_remote.is_none() {
            let s = next_secret(self.suite, &self.remote_secret);
            self.next_remote = Some(aead_from_secret(self.suite, &s));
        }
        self.next_remote.as_ref().unwrap()
    }

    fn update(&mut self) {
        let ns_local = next_secret(self.suite, &self.local_secret);
        let ns_remote = next_secret(self.suite, &self.remote_secret);
        let new_remote = match self.next_remote.take() {
            Some(k) => k,
            None => aead_from_secret(self.suite, &ns_remote),
        };
        let old_remote = std::mem::replace(&mut self.remote, new_remote);
        self.prev_remote = Some(old_remote);
        self.local = aead_from_secret(self.suite, &ns_local);
        self.local_secret = ns_local;
        self.remote_secret = ns_remote;
        self.phase = !self.phase;
        self.sent_in_phase = 0;
        self.first_pn_in_phase = None;
        self.phase_acked = false;
    }
}

struct LocalCid {
    seq: u64,
    cid: Vec<u8>,
    reset_token: [u8; 16],
}

#[derive(Clone)]
struct RemoteCid {
