impl Connection {
    fn base(
        side: Side,
        cfg: Arc<Config>,
        remote: SocketAddr,
        tls: Tls,
        local_cid: Vec<u8>,
        local_token: [u8; 16],
        now: Instant,
    ) -> Connection {
