            side,
            state: State::Handshake,
            remote,
            tls,
            spaces: [PacketSpace::new(), PacketSpace::new(), PacketSpace::new()],
            one_rtt: None,
            local_cids: vec![LocalCid { seq: 0, cid: local_cid, reset_token: local_token }],
            next_local_cid_seq: 1,
            rem_cids: BTreeMap::new(),
            rem_cid_seq: 0,
            rem_cid: Vec::new(),
            rem_retire_prior_to: 0,
            retire_pending: Vec::new(),
            new_cid_pending: Vec::new(),
            orig_dcid: Vec::new(),
            initial_dcid: Vec::new(),
            got_server_scid: false,
            handshake_complete: false,
            handshake_confirmed: false,
            handshake_done_pending: false,
            address_validated: side == Side::Client,
            bytes_received_unvalidated: 0,
            bytes_sent_unvalidated: 0,
            peer_params: None,
            send_streams: HashMap::new(),
            recv_streams: HashMap::new(),
            pending_streams: VecDeque::new(),
            pending_set: HashSet::new(),
            next_bidi: 0,
            next_uni: 0,
            peer_max_bidi: 0,
            peer_max_uni: 0,
            remote_bidi_opened: 0,
            remote_uni_opened: 0,
            remote_bidi_closed: 0,
            remote_uni_closed: 0,
            local_max_bidi: cfg.max_bidi,
            local_max_uni: cfg.max_uni,
            max_streams_bidi_pending: false,
            max_streams_uni_pending: false,
            accept_bidi: VecDeque::new(),
            accept_uni: VecDeque::new(),
            max_stream_data_pending: HashSet::new(),
            reset_pending: VecDeque::new(),
            stop_pending: VecDeque::new(),
            peer_max_data: 0,
            data_sent: 0,
            total_written: 0,
            total_unacked: 0,
            local_max_data: cfg.conn_window,
            data_received: 0,
            data_consumed: 0,
            max_data_pending: false,
            rtt: Rtt::new(cfg.initial_rtt),
            cc: Congestion::new(cfg.cc, mtu),
            bytes_in_flight: 0,
            pto_count: 0,
            mtu,
            mtud: MtuDiscovery { lower: mtu, upper: mtu, in_flight: None, failures: 0, done: true, next_probe_at: None },
            peer_max_ack_delay: Duration::from_millis(25),
            ack_eliciting_threshold: 1,
            local_max_ack_delay: Duration::from_millis(25),
            reordering_threshold: 1,
            ack_frequency_pending: false,
            idle_deadline: Some(now + cfg.idle_timeout),
            idle_timeout: cfg.idle_timeout,
            close_deadline: None,
            sent_ack_eliciting_since_rx: false,
