            close_app: false,
            close_send_pending: false,
            error: None,
            stats: ConnectionStats::default(),
            events: VecDeque::new(),
            endpoint_events: VecDeque::new(),
            path_responses: VecDeque::new(),
            qlog,
            start: now,
            grease: false,
            cfg,
        }
    }

    pub fn local_params(cfg: &Config, scid: &[u8], side: Side, odcid: Option<&[u8]>, token: Option<[u8; 16]>) -> TransportParams {
        let mut p = TransportParams::default();
        p.max_idle_timeout = cfg.idle_timeout.as_millis() as u64;
        p.max_udp_payload_size = cfg.max_udp_payload as u64;
        p.initial_max_data = cfg.conn_window;
        p.initial_max_stream_data_bidi_local = cfg.stream_window;
        p.initial_max_stream_data_bidi_remote = cfg.stream_window;
        p.initial_max_stream_data_uni = cfg.stream_window;
        p.initial_max_streams_bidi = cfg.max_bidi;
        p.initial_max_streams_uni = cfg.max_uni;
        p.active_connection_id_limit = 5;
        p.initial_scid = Some(scid.to_vec());
        p.max_datagram_frame_size = Some(65535);
        p.grease_quic_bit = true;
        p.min_ack_delay = Some(1000);
        if side == Side::Server {
            p.original_dcid = odcid.map(|o| o.to_vec());
            p.stateless_reset_token = token;
        }
        p
    }

    pub fn new_client(cfg: Arc<Config>, remote: SocketAddr, server_name: &str, now: Instant) -> Connection {
        let scid = random_cid(LOCAL_CID_LEN);
        let dcid = random_cid(20);
        let params = Self::local_params(&cfg, &scid, Side::Client, None, None);
        let keylog = if cfg.keylog { tls::KeyLog::from_env() } else { None };
        let tls = Tls::new_client(server_name, params.encode(), keylog);
        let mut c = Connection::base(Side::Client, cfg, remote, tls, scid, reset_token(), now);
        c.spaces[0].keys = Some(initial_keys(&dcid, true));
        c.rem_cid = dcid.clone();
        c.rem_cids.insert(0, RemoteCid { cid: dcid.clone(), reset_token: None });
        c.initial_dcid = dcid;
        c.process_tls_output();
        c
    }

    pub fn new_server(
        cfg: Arc<Config>,
        crypto: Arc<ServerCrypto>,
        remote: SocketAddr,
        odcid: &[u8],
        client_scid: &[u8],
        local_cid: Vec<u8>,
        now: Instant,
    ) -> Connection {
        let token = reset_token();
        let params = Self::local_params(&cfg, &local_cid, Side::Server, Some(odcid), Some(token));
        let keylog = if cfg.keylog { tls::KeyLog::from_env() } else { None };
        let tls = Tls::new_server(crypto, params.encode(), keylog);
        let mut c = Connection::base(Side::Server, cfg, remote, tls, local_cid, token, now);
        c.spaces[0].keys = Some(initial_keys(odcid, false));
        c.rem_cid = client_scid.to_vec();
        c.rem_cids.insert(0, RemoteCid { cid: client_scid.to_vec(), reset_token: None });
        c.orig_dcid = odcid.to_vec();
        c.initial_dcid = odcid.to_vec();
        c
    }

    pub fn local_cid(&self) -> &[u8] {
        &self.local_cids[0].cid
    }

    pub fn is_drained(&self) -> bool {
        self.state == State::Drained
    }

    pub fn is_closed(&self) -> bool {
        matches!(self.state, State::Closing | State::Draining | State::Drained)
    }

    pub fn is_established(&self) -> bool {
        self.state == State::Established
    }

    pub fn error(&self) -> Option<&ConnError> {
        self.error.as_ref()
    }

    pub fn poll_event(&mut self) -> Option<Event> {
        self.events.pop_front()
    }

    pub fn poll_endpoint_event(&mut self) -> Option<EndpointEvent> {
        self.endpoint_events.pop_front()
    }

    pub fn stats(&self) -> ConnectionStats {
        let mut s = self.stats;
        s.path.rtt = self.rtt.get();
        s.path.cwnd = self.cc.window;
        s.path.congestion_events = self.cc.events;
        s.path.current_mtu = self.mtu;
        s
    }

    fn pto_duration(&self, space: usize) -> Duration {
        let mut d = self.rtt.pto_base();
        if space == 2 {
            d += self.peer_max_ack_delay;
        }
        d
    }

    // ------------------------------------------------------------------
    // TLS integration

    fn process_tls_output(&mut self) {
        for (level, data) in std::mem::take(&mut self.tls.outgoing) {
            let s = &mut self.spaces[level as usize];
            s.crypto_send.data.extend_from_slice(&data);
        }
        for sec in std::mem::take(&mut self.tls.secrets) {
            match sec.level {
                Level::Handshake => {
                    let local = PacketKey::from_secret(sec.suite, &sec.local);
                    let remote = PacketKey::from_secret(sec.suite, &sec.remote);
                    self.spaces[1].keys = Some(Keys { local, remote });
                }
                Level::OneRtt => {
                    self.one_rtt = Some(OneRtt::new(sec.suite, sec.local, sec.remote));
                }
                Level::Initial => {}
            }
        }
    }

    fn on_handshake_complete(&mut self, now: Instant) {
        if self.handshake_complete {
            return;
        }
        self.handshake_complete = true;
        // Validate peer transport parameters
        let raw = self.tls.peer_params.clone().unwrap_or_default();
        let params = match TransportParams::decode(&raw, self.side == Side::Client) {
            Ok(p) => p,
            Err(e) => {
                self.close_transport(now, 0x08, None, e);
                return;
            }
        };
        if self.side == Side::Client {
            if params.original_dcid.as_deref() != Some(&self.initial_dcid[..]) {
                self.close_transport(now, 0x08, None, "original_destination_connection_id mismatch");
                return;
            }
        }
        self.apply_peer_params(params);
        self.state = State::Established;
        if self.side == Side::Server {
            self.handshake_confirmed = true;
            self.handshake_done_pending = true;
            self.discard_space(1);
        }
        // Issue additional connection IDs
        let limit = self.peer_params.as_ref().map(|p| p.active_connection_id_limit).unwrap_or(2).min(5);
        for _ in 1..limit {
            self.issue_cid();
        }
        self.events.push_back(Event::Connected);
        self.start_mtud(now);
    }

    fn apply_peer_params(&mut self, p: TransportParams) {
        self.peer_max_data = p.initial_max_data;
        self.peer_max_bidi = p.initial_max_streams_bidi;
        self.peer_max_uni = p.initial_max_streams_uni;
        self.peer_max_ack_delay = Duration::from_millis(p.max_ack_delay);
        if p.max_idle_timeout != 0 {
            let peer = Duration::from_millis(p.max_idle_timeout);
            if peer < self.idle_timeout || self.idle_timeout.is_zero() {
                self.idle_timeout = peer;
            }
        }
        if let Some(t) = p.stateless_reset_token {
            if let Some(r) = self.rem_cids.get_mut(&0) {
                r.reset_token = Some(t);
            }
        }
        self.grease = p.grease_quic_bit;
        if self.cfg.ack_frequency && p.min_ack_delay.is_some() {
            self.ack_frequency_pending = true;
        }
        self.peer_params = Some(p);
    }

    fn issue_cid(&mut self) {
        let seq = self.next_local_cid_seq;
        self.next_local_cid_seq += 1;
        let cid = random_cid(LOCAL_CID_LEN);
        self.endpoint_events.push_back(EndpointEvent::NewCid(cid.clone()));
        self.local_cids.push(LocalCid { seq, cid, reset_token: reset_token() });
        self.new_cid_pending.push(seq);
    }

    fn start_mtud(&mut self, now: Instant) {
        let peer_max = self.peer_params.as_ref().map(|p| p.max_udp_payload_size).unwrap_or(65527);
        let upper = (self.cfg.mtu_upper as u64).min(peer_max).min(self.cfg.max_udp_payload as u64) as u16;
        if upper > self.mtu {
            self.mtud = MtuDiscovery { lower: self.mtu, upper, in_flight: None, failures: 0, done: false, next_probe_at: Some(now) };
        }
    }

    fn discard_space(&mut self, idx: usize) {
        let s = &mut self.spaces[idx];
        if s.keys.is_none() && s.sent.is_empty() {
            return;
        }
        s.keys = None;
        let mut freed = 0;
        for (_, p) in std::mem::take(&mut s.sent) {
            if p.in_flight {
                freed += p.size as u64;
            }
        }
        s.in_flight_bytes = 0;
        s.ack_eliciting_in_flight = 0;
        s.loss_time = None;
        s.time_of_last_ack_eliciting = None;
        s.probes = 0;
        s.ack_immediate = false;
        s.unacked_rx = false;
        s.ack_deadline = None;
        s.crypto_send.retransmit.clear();
        s.ping_pending = false;
        self.bytes_in_flight = self.bytes_in_flight.saturating_sub(freed);
        self.pto_count = 0;
    }
