    // ------------------------------------------------------------------
    // Receiving

    pub fn handle_datagram(&mut self, now: Instant, data: &mut [u8], segments: usize) {
        self.stats.udp_rx.ios += 1;
        let _ = segments;
        if self.state == State::Drained {
            return;
        }
        self.stats.udp_rx.datagrams += 1;
        self.stats.udp_rx.bytes += data.len() as u64;
        if !self.address_validated {
            self.bytes_received_unvalidated += data.len() as u64;
        }
        let mut off = 0;
        while off < data.len() {
            let rest = &mut data[off..];
            let hdr = match parse_header(rest, LOCAL_CID_LEN) {
                Some(ParsedHeader::Packet(h)) => h,
                _ => return,
            };
            let plen = hdr.packet_len;
            if plen > rest.len() {
                return;
            }
            let pkt = &mut rest[..plen];
            self.handle_packet(now, hdr, pkt);
            if self.state == State::Drained {
                return;
            }
            off += plen;
        }
    }

    fn handle_packet(&mut self, now: Instant, hdr: PlainHeader, pkt: &mut [u8]) {
        let space = match hdr.long {
            Some(LongType::Initial) => 0usize,
            Some(LongType::Handshake) => 1,
            Some(LongType::ZeroRtt) | Some(LongType::Retry) => return,
            None => 2,
        };
        if hdr.long.is_some() && hdr.dcid != self.local_cids[0].cid && self.side == Side::Client {
            // not for us
            return;
        }
        // Key availability
        let have_keys = if space == 2 { self.one_rtt.is_some() } else { self.spaces[space].keys.is_some() };
        if !have_keys {
            if space > 0 && self.spaces[space].undecryptable.len() < MAX_UNDECRYPTABLE && !self.is_closed() {
                // keep for later (only if keys may still arrive)
                let possible = if space == 1 { self.spaces[0].keys.is_some() } else { !self.handshake_complete || self.side == Side::Server };
                if possible {
                    self.spaces[space].undecryptable.push(pkt.to_vec());
                }
            }
            return;
        }
        // Remove header protection
        let unprot = {
            let hp = if space == 2 {
                &self.one_rtt.as_ref().unwrap().hp_remote
            } else {
                &self.spaces[space].keys.as_ref().unwrap().remote.hp
            };
            unprotect_header(pkt, hdr.pn_offset, hp)
        };
        let (pn_len, tpn, first) = match unprot {
            Some(x) => x,
            None => return,
        };
        let pn = decode_pn(self.spaces[space].largest_rx, tpn, (pn_len * 8) as u32);
        let hdr_len = hdr.pn_offset + pn_len;
        if pkt.len() < hdr_len + TAG_LEN {
            return;
        }
        let (header, body) = pkt.split_at_mut(hdr_len);
        let bl = body.len();
        let (payload, tag) = body.split_at_mut(bl - TAG_LEN);
        let ok = if space == 2 {
            let no_protection = self.cfg.no_protection;
            let o = self.one_rtt.as_mut().unwrap();
            let key_phase = first & 0x04 != 0;
            if key_phase == o.phase {
                if no_protection {
                    true
                } else {
                    let r = o.remote.open(pn, header, payload, tag);
                    if !r {
                        // maybe a reordered packet from the previous phase
                        match &o.prev_remote {
                            Some(p) => p.open(pn, header, payload, tag),
                            None => false,
                        }
                    } else {
                        true
                    }
                }
            } else {
                // possible key update
                let is_newer = match o.first_pn_in_phase {
                    _ => self.spaces[2].largest_rx.map_or(true, |l| pn > l),
                };
                if no_protection {
                    if is_newer && o.phase_acked {
                        o.update();
                    }
                    true
                } else if let Some(prev) = &o.prev_remote {
                    if !is_newer {
                        prev.open(pn, header, payload, tag)
                    } else {
                        let k = o.next_remote_key();
                        if k.open(pn, header, payload, tag) {
                            o.update();
                            true
                        } else {
                            false
                        }
                    }
                } else {
                    let k = o.next_remote_key();
                    if k.open(pn, header, payload, tag) {
                        o.update();
                        true
                    } else {
                        false
                    }
                }
            }
        } else {
            self.spaces[space].keys.as_ref().unwrap().remote.aead.open(pn, header, payload, tag)
        };
        if !ok {
            return;
        }
        // reserved bits must be zero
        let reserved = if hdr.long.is_some() { first & 0x0c } else { first & 0x18 };
        if reserved != 0 {
            self.close_transport(now, 0x0a, None, "reserved bits set");
            return;
        }
        if self.spaces[space].rx.contains(pn) {
            return; // duplicate
        }
        if let Some(q) = &mut self.qlog {
            q.packet_received(now, space, pn);
        }
        // Client learns the server's connection ID from the first Initial/Handshake
        if self.side == Side::Client && hdr.long.is_some() && !self.got_server_scid {
            self.got_server_scid = true;
            self.rem_cid = hdr.scid.clone();
            self.rem_cids.insert(0, RemoteCid { cid: hdr.scid.clone(), reset_token: None });
        }
        if self.side == Side::Server && space == 1 && !self.address_validated {
            self.address_validated = true;
        }
        if self.side == Side::Server && space == 1 && self.spaces[0].keys.is_some() {
            self.discard_space(0);
        }
        let payload_copy: &[u8] = payload;
        let ack_eliciting = self.process_frames(now, space, payload_copy);
        if self.state == State::Drained || self.state == State::Draining {
            return;
        }
        // Record receipt
        let s = &mut self.spaces[space];
        let out_of_order = match s.largest_rx {
            Some(l) => pn != l + 1,
            None => false,
        };
        s.rx.insert_one(pn);
        while s.rx.len() > MAX_ACK_RANGES {
            if let Some(r) = s.rx.first_range() {
                s.rx.remove(r);
            }
        }
        if s.largest_rx.map_or(true, |l| pn > l) {
            s.largest_rx = Some(pn);
            s.largest_rx_time = Some(now);
        }
        s.unacked_rx = true;
        if ack_eliciting {
            s.ack_eliciting_since_ack += 1;
            if space != 2 || out_of_order || s.ack_eliciting_since_ack > self.ack_eliciting_threshold {
                s.ack_immediate = true;
            } else if s.ack_deadline.is_none() {
                s.ack_deadline = Some(now + self.local_max_ack_delay);
            }
        }
        self.sent_ack_eliciting_since_rx = false;
        if !self.idle_timeout.is_zero() && !self.is_closed() {
            self.idle_deadline = Some(now + self.idle_timeout.max(3 * self.pto_duration(2)));
        }
        if self.state == State::Closing {
            self.close_send_pending = true;
        }
        // Retry undecryptable packets now that keys may be available
        self.retry_undecryptable(now);
    }

    fn retry_undecryptable(&mut self, now: Instant) {
        for space in 1..3 {
            let have = if space == 2 { self.one_rtt.is_some() } else { self.spaces[space].keys.is_some() };
            if !have || self.spaces[space].undecryptable.is_empty() {
                continue;
            }
            let pkts = std::mem::take(&mut self.spaces[space].undecryptable);
            for mut p in pkts {
                if let Some(ParsedHeader::Packet(h)) = parse_header(&p, LOCAL_CID_LEN) {
                    let l = h.packet_len.min(p.len());
                    self.handle_packet(now, h, &mut p[..l]);
                }
            }
        }
    }

    fn process_frames(&mut self, now: Instant, space: usize, payload: &[u8]) -> bool {
        let mut ack_eliciting = false;
        let mut it = FrameIter::new(payload);
        let mut count = 0;
        while let Some(f) = it.next() {
            count += 1;
            self.stats.frame_rx.record(&f);
            if f.is_ack_eliciting() {
                ack_eliciting = true;
            }
            if space != 2 {
                match f {
                    Frame::Padding
                    | Frame::Ping
                    | Frame::Ack(_)
                    | Frame::Crypto { .. }
                    | Frame::ConnectionClose { .. } => {}
                    _ => {
                        self.close_transport(now, 0x0a, None, "illegal frame type in handshake");
                        return false;
                    }
                }
            }
            if let Err((code, reason)) = self.process_frame(now, space, f) {
                self.close_transport(now, code, None, reason);
                return false;
            }
            if self.state == State::Drained || self.state == State::Draining {
                return false;
            }
        }
        if it.error || count == 0 {
            self.close_transport(now, 0x07, None, "malformed frame");
            return false;
        }
        ack_eliciting
    }

    fn process_frame(&mut self, now: Instant, space: usize, f: Frame) -> Result<(), (u64, &'static str)> {
        match f {
            Frame::Padding | Frame::Ping => {}
            Frame::Ack(ack) => self.on_ack_received(now, space, ack)?,
            Frame::Crypto { offset, data } => {
                let level = match space {
                    0 => Level::Initial,
                    1 => Level::Handshake,
                    _ => Level::OneRtt,
                };
                let s = &mut self.spaces[space];
                if offset + data.len() as u64 > s.crypto_recv.read_offset + 1 << 20 {
                    return Err((0x0d, "crypto buffer exceeded"));
                }
                let _ = s.crypto_recv.ingest(offset, data, false);
                let mut buf = Vec::new();
                s.crypto_recv.read(usize::MAX, Some(&mut buf));
                if !buf.is_empty() {
                    if let Err(e) = self.tls.read_handshake(level, &buf) {
                        self.close_transport_owned(now, 0x100 + e.alert as u64, None, e.reason);
                        return Ok(());
                    }
                    self.process_tls_output();
                    if self.tls.complete && !self.handshake_complete {
                        self.on_handshake_complete(now);
                        if self.side == Side::Client {
                            // client discards initial keys once it sends handshake packets
                            self.discard_space(0);
                        }
                    }
                }
            }
            Frame::Stream { id, offset, data, fin } => self.on_stream_frame(id, offset, data, fin)?,
            Frame::ResetStream { id, error, final_size } => {
                if self.is_local_uni(id) {
                    return Err((0x05, "RESET_STREAM on send-only stream"));
                }
                self.ensure_remote_stream(id)?;
                if let Some(rs) = self.recv_streams.get_mut(&id) {
                    if let Some(fs) = rs.final_size {
                        if fs != final_size {
                            return Err((0x06, "final size changed"));
                        }
                    }
