    }

    fn is_local(&self, id: u64) -> bool {
        is_client_initiated(id) == (self.side == Side::Client)
    }

    fn is_local_uni(&self, id: u64) -> bool {
        !is_bidi(id) && self.is_local(id)
    }

    fn is_remote_uni(&self, id: u64) -> bool {
        !is_bidi(id) && !self.is_local(id)
    }

    /// Opens remote-initiated streams implicitly up to `id`.
    fn ensure_remote_stream(&mut self, id: u64) -> Result<(), (u64, &'static str)> {
        let index = id >> 2;
        if self.is_local(id) {
            let opened = if is_bidi(id) { self.next_bidi } else { self.next_uni };
            if index >= opened {
                return Err((0x05, "frame for unopened local stream"));
            }
            return Ok(());
        }
        let bidi = is_bidi(id);
        let (opened, limit) = if bidi {
            (self.remote_bidi_opened, self.local_max_bidi)
        } else {
            (self.remote_uni_opened, self.local_max_uni)
        };
        if index < opened {
            return Ok(());
        }
        if index >= limit {
            return Err((0x04, "stream limit exceeded"));
        }
        let peer_params = self.peer_params.clone().unwrap_or_default();
        for i in opened..=index {
            let sid = (i << 2) | (id & 3);
            let window = self.cfg.stream_window;
            self.recv_streams.insert(sid, RecvStream::new(sid, window));
            if bidi {
                self.send_streams.insert(sid, SendStream::new(sid, peer_params.initial_max_stream_data_bidi_local));
                self.accept_bidi.push_back(sid);
            } else {
                self.accept_uni.push_back(sid);
            }
        }
        if bidi {
            self.remote_bidi_opened = index + 1;
        } else {
            self.remote_uni_opened = index + 1;
        }
        Ok(())
    }

    fn on_stream_frame(&mut self, id: u64, offset: u64, data: &[u8], fin: bool) -> Result<(), (u64, &'static str)> {
        if self.is_local_uni(id) {
            return Err((0x05, "STREAM frame on send-only stream"));
        }
        if offset + data.len() as u64 > VARINT_MAX {
            return Err((0x03, "stream offset too large"));
        }
        self.ensure_remote_stream(id)?;
        let rs = match self.recv_streams.get_mut(&id) {
            Some(r) => r,
            None => return Ok(()), // already closed
        };
        let inc = match rs.ingest(offset, data, fin) {
            Ok(i) => i,
            Err(RecvError::FlowControl) => return Err((0x03, "stream flow control exceeded")),
            Err(RecvError::FinalSize) => return Err((0x06, "final size error")),
        };
        self.data_received += inc;
        if self.data_received > self.local_max_data {
            return Err((0x03, "connection flow control exceeded"));
        }
        Ok(())
    }

    fn on_peer_close(&mut self, now: Instant, err: ConnError) {
        if self.state == State::Draining || self.state == State::Drained {
            return;
        }
        let was_closing = self.state == State::Closing;
        self.state = State::Draining;
        self.close_deadline = Some(now + 3 * self.pto_duration(2));
        if !was_closing {
            // respond once with a close frame
            let mut f = Vec::new();
            put_varint(&mut f, ty::CONNECTION_CLOSE);
            put_varint(&mut f, 0);
            put_varint(&mut f, 0);
            put_varint(&mut f, 0);
            self.close_frame = Some(f);
            self.close_send_pending = true;
            self.set_error(err);
        }
    }

    fn set_error(&mut self, err: ConnError) {
        if self.error.is_none() {
            self.error = Some(err.clone());
            self.events.push_back(Event::Lost(err));
        }
    }
