            }
            Frame::PathResponse(_) => {}
            Frame::ConnectionClose { error, frame_type, reason } => {
                let ft = if frame_type == 0 { None } else { Some(frame_type) };
                self.on_peer_close(now, ConnError::ConnectionClosed { code: error, frame_type: ft, reason: reason.to_vec() });
            }
            Frame::ApplicationClose { error, reason } => {
                self.on_peer_close(now, ConnError::ApplicationClosed { code: error, reason: reason.to_vec() });
            }
            Frame::HandshakeDone => {
                if self.side == Side::Server {
