                            self.send_streams.remove(&id);
                            self.maybe_free_stream(id);
                        }
                    }
                }
                SentFrame::ResetStream(id) => {
                    if let Some(ss) = self.send_streams.get_mut(&id) {
                        ss.reset_acked = true;
                        self.send_streams.remove(&id);
                        self.maybe_free_stream(id);
                    }
                }
                SentFrame::HandshakeDone => {}
                _ => {}
            }
        }
    }

    fn detect_lost(&mut self, now: Instant, space: usize) {
        let largest_acked = match self.spaces[space].largest_acked {
            Some(l) => l,
            None => return,
        };
        let loss_delay = (self.rtt.conservative() * 9 / 8).max(GRANULARITY);
        let lost_send_time = now.checked_sub(loss_delay);
        let mut lost: Vec<(u64, SentPacket)> = Vec::new();
        let mut loss_time: Option<Instant> = None;
        {
            let s = &mut self.spaces[space];
            let candidates: Vec<u64> = s.sent.range(..largest_acked).map(|(&pn, _)| pn).collect();
            for pn in candidates {
                let p = s.sent.get(&pn).unwrap();
                let time_lost = match lost_send_time {
                    Some(t) => p.time <= t,
                    None => false,
                };
                if time_lost || largest_acked >= pn + PACKET_THRESHOLD {
                    let p = s.sent.remove(&pn).unwrap();
                    lost.push((pn, p));
                } else {
                    let t = p.time + loss_delay;
                    loss_time = Some(match loss_time {
                        Some(x) => x.min(t),
                        None => t,
                    });
                }
            }
            s.loss_time = loss_time;
        }
        if lost.is_empty() {
            return;
        }
        let mut largest_lost_time: Option<Instant> = None;
        for (pn, p) in lost {
            if p.in_flight {
                self.bytes_in_flight = self.bytes_in_flight.saturating_sub(p.size as u64);
                let s = &mut self.spaces[space];
                s.in_flight_bytes = s.in_flight_bytes.saturating_sub(p.size as u64);
                if p.ack_eliciting {
                    s.ack_eliciting_in_flight = s.ack_eliciting_in_flight.saturating_sub(1);
                }
            }
            if let Some(q) = &mut self.qlog {
                q.packet_lost(now, space, pn, p.size);
            }
            if let Some(size) = p.mtu_probe {
                self.stats.path.lost_plpmtud_probes += 1;
                if let Some((ppn, _)) = self.mtud.in_flight {
                    if ppn == pn {
                        self.mtud.in_flight = None;
                        self.mtud.failures += 1;
                        if self.mtud.failures >= 3 {
                            self.mtud.upper = size - 1;
                            self.mtud.failures = 0;
                            if self.mtud.upper <= self.mtud.lower {
                                self.mtud.done = true;
                            }
                        }
                        self.mtud.next_probe_at = Some(now);
                    }
                }
                continue;
            }
            self.stats.path.lost_packets += 1;
            self.stats.path.lost_bytes += p.size as u64;
            if p.in_flight && p.ack_eliciting {
                largest_lost_time = Some(match largest_lost_time {
                    Some(t) => t.max(p.time),
                    None => p.time,
                });
            }
            self.requeue_frames(space, p.frames);
        }
        if let Some(t) = largest_lost_time {
            self.cc.on_congestion_event(now, t, false);
            if let Some(q) = &mut self.qlog {
                q.metrics(now, &self.rtt, self.cc.window, self.bytes_in_flight);
            }
        }
    }

    fn requeue_frames(&mut self, space: usize, frames: Vec<SentFrame>) {
        for f in frames {
            match f {
                SentFrame::Crypto { offset, len } => {
                    let cs = &mut self.spaces[space].crypto_send;
                    let mut r = RangeSet::new();
                    r.insert(offset..offset + len);
                    for a in cs.acked.iter() {
                        r.remove(a);
                    }
                    for x in r.iter() {
                        cs.retransmit.insert(x);
                    }
                }
                SentFrame::Stream { id, offset, len, fin } => {
                    if let Some(ss) = self.send_streams.get_mut(&id) {
                        ss.on_lost(offset, len, fin);
                        if ss.has_pending(1) && self.pending_set.insert(id) {
                            self.pending_streams.push_back(id);
                        }
                    }
                }
                SentFrame::MaxData => self.max_data_pending = true,
                SentFrame::MaxStreamData(id) => {
                    if self.recv_streams.contains_key(&id) {
                        self.max_stream_data_pending.insert(id);
                    }
                }
                SentFrame::MaxStreams(bidi) => {
                    if bidi {
                        self.max_streams_bidi_pending = true;
                    } else {
                        self.max_streams_uni_pending = true;
                    }
                }
                SentFrame::NewCid(seq) => {
                    if self.local_cids.iter().any(|c| c.seq == seq) {
                        self.new_cid_pending.push(seq);
                    }
                }
                SentFrame::RetireCid(seq) => self.retire_pending.push(seq),
                SentFrame::HandshakeDone => self.handshake_done_pending = true,
                SentFrame::ResetStream(id) => {
                    if self.send_streams.contains_key(&id) {
                        self.reset_pending.push_back(id);
                    }
                }
                SentFrame::StopSending(id) => {
                    if self.recv_streams.contains_key(&id) {
                        self.stop_pending.push_back(id);
                    }
                }
                SentFrame::AckFrequency => self.ack_frequency_pending = true,
            }
        }
    }

    fn loss_detection_deadline(&self) -> Option<(Instant, usize, bool)> {
        // (time, space, is_loss_time)
        let mut best: Option<(Instant, usize, bool)> = None;
        for i in 0..3 {
            if let Some(t) = self.spaces[i].loss_time {
                if best.map_or(true, |b| t < b.0) {
                    best = Some((t, i, true));
                }
            }
        }
        if best.is_some() {
            return best;
        }
        // PTO
        let backoff = 1u32 << self.pto_count.min(16);
        let any_in_flight = self.spaces.iter().any(|s| s.ack_eliciting_in_flight > 0);
        if !any_in_flight {
            // anti-deadlock for clients without confirmed handshake
            if self.side == Side::Client && !self.handshake_confirmed && self.state == State::Handshake {
                let space = if self.spaces[1].keys.is_some() { 1 } else { 0 };
                let base = self.spaces[space].time_of_last_ack_eliciting.unwrap_or(self.start);
                return Some((base + self.pto_duration(space) * backoff, space, false));
            }
            return None;
        }
        for i in 0..3 {
            let s = &self.spaces[i];
            if s.ack_eliciting_in_flight == 0 {
                continue;
            }
            if i == 2 && !self.handshake_confirmed {
                continue;
            }
            let t = match s.time_of_last_ack_eliciting {
                Some(t) => t + self.pto_duration(i) * backoff,
                None => continue,
            };
            if best.map_or(true, |b| t < b.0) {
                best = Some((t, i, false));
            }
        }
        best
    }

    fn on_loss_timeout(&mut self, now: Instant) {
        let (t, space, is_loss) = match self.loss_detection_deadline() {
            Some(x) => x,
            None => return,
        };
        if t > now {
            return;
        }
        if is_loss {
            self.detect_lost(now, space);
            return;
        }
        // PTO: send probes
        self.pto_count += 1;
        if let Some(q) = &mut self.qlog {
            q.pto(now, self.pto_count);
        }
        let mut sp = space;
        if self.spaces[sp].keys.is_none() && sp < 2 {
            sp = if self.spaces[1].keys.is_some() { 1 } else { 2 };
        }
        self.spaces[sp].probes = 2;
        // queue retransmission of the oldest in-flight data
        let frames: Vec<SentFrame> = {
            let s = &self.spaces[sp];
            let mut v = Vec::new();
            for (_, p) in s.sent.iter().filter(|(_, p)| p.ack_eliciting).take(2) {
                for f in &p.frames {
                    match f {
                        SentFrame::Crypto { .. } | SentFrame::Stream { .. } => v.push(f.clone()),
                        _ => {}
                    }
                }
            }
            v
        };
        if frames.is_empty() {
            self.spaces[sp].ping_pending = true;
        } else {
            self.requeue_frames(sp, frames);
        }
        if sp != 2 && self.side == Side::Client && !self.handshake_confirmed && self.spaces[sp].crypto_send.has_pending() == false {
            self.spaces[sp].ping_pending = true;
        }
    }
