        if space == 2 && can_send_data && self.handshake_complete {
            if self.write_stream_frames(buf, limit, &mut frames) {
                ack_eliciting = true;
            }
        }
        // PING for probes
        let need_ping = {
            let s = &self.spaces[space];
            (s.ping_pending || s.probes > 0) && !ack_eliciting
        };
        if need_ping {
            buf.push(ty::PING as u8);
            self.stats.frame_tx.ping += 1;
            ack_eliciting = true;
        }
        if ack_eliciting {
            let s = &mut self.spaces[space];
            s.ping_pending = false;
            if s.probes > 0 {
                s.probes -= 1;
            }
        }
        if buf.len() == header_end {
            buf.truncate(start);
            return false;
        }
        // padding
        let mut target_end = buf.len();
        // header protection sample needs pn + payload >= 4 bytes
        if target_end - pn_off < 4 {
            target_end = pn_off + 4;
        }
        if let Some(p) = pad_to {
            let want = p.saturating_sub(TAG_LEN);
            if want > target_end {
                target_end = want.min(limit);
            }
        }
        if target_end > buf.len() {
            buf.resize(target_end, 0);
        }
        // finalize
        let payload_len = buf.len() - pn_off + TAG_LEN;
        if len_off != 0 {
            let v = (payload_len as u16) | 0x4000;
            buf[len_off..len_off + 2].copy_from_slice(&v.to_be_bytes());
        }
        let total_len = buf.len() + TAG_LEN - start;
        self.seal_packet(space, buf, start, pn_off, pn_len, pn);
        let s = &mut self.spaces[space];
        s.next_pn += 1;
        self.stats.path.sent_packets += 1;
        if let Some(q) = &mut self.qlog {
            q.packet_sent(now, space, pn, total_len);
        }
        if space == 2 {
            if let Some(o) = &mut self.one_rtt {
                o.sent_in_phase += 1;
                if o.first_pn_in_phase.is_none() {
                    o.first_pn_in_phase = Some(pn);
                }
            }
        }
        if ack_eliciting || !frames.is_empty() {
            let key_phase = self.one_rtt.as_ref().map_or(false, |o| o.phase);
            let s = &mut self.spaces[space];
            s.sent.insert(
                pn,
                SentPacket {
                    time: now,
                    size: total_len as u16,
                    ack_eliciting,
                    in_flight: true,
                    frames,
                    largest_ack,
                    mtu_probe: None,
                    key_phase,
                },
            );
            s.time_of_last_ack_eliciting = Some(now);
            s.ack_eliciting_in_flight += 1;
            s.in_flight_bytes += total_len as u64;
            self.bytes_in_flight += total_len as u64;
            if !self.sent_ack_eliciting_since_rx {
                self.sent_ack_eliciting_since_rx = true;
                if !self.idle_timeout.is_zero() {
                    self.idle_deadline = Some(now + self.idle_timeout.max(3 * self.pto_duration(2)));
                }
            }
        }
        true
    }

    fn seal_packet(&mut self, space: usize, buf: &mut Vec<u8>, start: usize, pn_off: usize, pn_len: usize, pn: u64) {
        let hdr_end = pn_off + pn_len;
        let mut tag = [0u8; TAG_LEN];
        {
            let (header, payload) = buf[start..].split_at_mut(hdr_end - start);
            if space == 2 {
                let o = self.one_rtt.as_ref().unwrap();
                if self.cfg.no_protection {
                    tag = [0x2a; TAG_LEN];
                } else {
                    o.local.seal(pn, header, payload, &mut tag);
                }
            } else {
                let k = self.spaces[space].keys.as_ref().unwrap();
                k.local.aead.seal(pn, header, payload, &mut tag);
            }
        }
        buf.extend_from_slice(&tag);
        let pkt = &mut buf[start..];
        let rel_pn = pn_off - start;
        if space == 2 {
            let o = self.one_rtt.as_ref().unwrap();
            protect_header(pkt, rel_pn, pn_len, &o.hp_local);
        } else {
            let k = self.spaces[space].keys.as_ref().unwrap();
            protect_header(pkt, rel_pn, pn_len, &k.local.hp);
        }
    }

    fn write_control_frames(&mut self, buf: &mut Vec<u8>, limit: usize, frames: &mut Vec<SentFrame>) {
        let room = |b: &Vec<u8>| limit.saturating_sub(b.len());
        while let Some(d) = self.path_responses.front().copied() {
            if room(buf) < 9 {
                return;
            }
            self.path_responses.pop_front();
            buf.push(ty::PATH_RESPONSE as u8);
            buf.extend_from_slice(&d);
            self.stats.frame_tx.path_response += 1;
            frames.push(SentFrame::AckFrequency); // placeholder: not retransmitted meaningfully
            frames.pop();
        }
        if self.handshake_done_pending && room(buf) >= 1 {
            self.handshake_done_pending = false;
            buf.push(ty::HANDSHAKE_DONE as u8);
            self.stats.frame_tx.handshake_done += 1;
            frames.push(SentFrame::HandshakeDone);
        }
        if self.ack_frequency_pending && room(buf) >= 16 {
            self.ack_frequency_pending = false;
            put_varint(buf, ty::ACK_FREQUENCY);
            put_varint(buf, 0);
            put_varint(buf, 1);
            put_varint(buf, 25_000);
            put_varint(buf, 2);
            self.stats.frame_tx.ack_frequency += 1;
            frames.push(SentFrame::AckFrequency);
        }
        if self.max_data_pending && room(buf) >= 9 {
            self.max_data_pending = false;
            put_varint(buf, ty::MAX_DATA);
            put_varint(buf, self.local_max_data);
            self.stats.frame_tx.max_data += 1;
            frames.push(SentFrame::MaxData);
        }
        if self.max_streams_bidi_pending && room(buf) >= 9 {
            self.max_streams_bidi_pending = false;
            put_varint(buf, ty::MAX_STREAMS_BIDI);
            put_varint(buf, self.local_max_bidi);
            self.stats.frame_tx.max_streams_bidi += 1;
            frames.push(SentFrame::MaxStreams(true));
        }
        if self.max_streams_uni_pending && room(buf) >= 9 {
            self.max_streams_uni_pending = false;
            put_varint(buf, ty::MAX_STREAMS_UNI);
            put_varint(buf, self.local_max_uni);
            self.stats.frame_tx.max_streams_uni += 1;
            frames.push(SentFrame::MaxStreams(false));
        }
        if !self.max_stream_data_pending.is_empty() {
            let ids: Vec<u64> = self.max_stream_data_pending.iter().copied().collect();
            for id in ids {
                if room(buf) < 17 {
                    break;
                }
                self.max_stream_data_pending.remove(&id);
                if let Some(rs) = self.recv_streams.get(&id) {
                    if rs.final_size.is_some() || rs.reset.is_some() {
                        continue;
                    }
                    put_varint(buf, ty::MAX_STREAM_DATA);
                    put_varint(buf, id);
                    put_varint(buf, rs.max_data);
                    self.stats.frame_tx.max_stream_data += 1;
                    frames.push(SentFrame::MaxStreamData(id));
                }
            }
        }
        while let Some(&seq) = self.new_cid_pending.last() {
            if room(buf) < 1 + 8 + 8 + 1 + 20 + 16 {
                break;
            }
            self.new_cid_pending.pop();
            if let Some(c) = self.local_cids.iter().find(|c| c.seq == seq) {
                put_varint(buf, ty::NEW_CONNECTION_ID);
                put_varint(buf, seq);
                put_varint(buf, 0);
                buf.push(c.cid.len() as u8);
                buf.extend_from_slice(&c.cid);
                buf.extend_from_slice(&c.reset_token);
                self.stats.frame_tx.new_connection_id += 1;
                frames.push(SentFrame::NewCid(seq));
            }
        }
        while let Some(&seq) = self.retire_pending.last() {
            if room(buf) < 9 {
                break;
            }
            self.retire_pending.pop();
            put_varint(buf, ty::RETIRE_CONNECTION_ID);
            put_varint(buf, seq);
            self.stats.frame_tx.retire_connection_id += 1;
            frames.push(SentFrame::RetireCid(seq));
        }
        while let Some(&id) = self.reset_pending.front() {
            if room(buf) < 25 {
                break;
            }
            self.reset_pending.pop_front();
            if let Some(ss) = self.send_streams.get_mut(&id) {
                if let Some(code) = ss.reset {
                    ss.reset_pending = false;
                    put_varint(buf, ty::RESET_STREAM);
                    put_varint(buf, id);
                    put_varint(buf, code);
                    put_varint(buf, ss.write_offset);
                    self.stats.frame_tx.reset_stream += 1;
                    frames.push(SentFrame::ResetStream(id));
                }
            }
        }
        while let Some(&id) = self.stop_pending.front() {
            if room(buf) < 17 {
                break;
            }
            self.stop_pending.pop_front();
            if let Some(rs) = self.recv_streams.get_mut(&id) {
                if let Some(code) = rs.stop_sending_pending {
                    put_varint(buf, ty::STOP_SENDING);
                    put_varint(buf, id);
                    put_varint(buf, code);
                    self.stats.frame_tx.stop_sending += 1;
                    frames.push(SentFrame::StopSending(id));
                }
            }
        }
    }

    fn write_stream_frames(&mut self, buf: &mut Vec<u8>, limit: usize, frames: &mut Vec<SentFrame>) -> bool {
        let mut wrote = false;
        let mut attempts = self.pending_streams.len();
        while attempts > 0 {
            attempts -= 1;
            let room = limit.saturating_sub(buf.len());
            if room < 24 {
                break;
            }
            let id = match self.pending_streams.pop_front() {
                Some(id) => id,
                None => break,
            };
            let credit = self.peer_max_data.saturating_sub(self.data_sent);
            let ss = match self.send_streams.get_mut(&id) {
                Some(s) => s,
                None => {
                    self.pending_set.remove(&id);
                    continue;
                }
            };
            if !ss.has_pending(credit) {
                self.pending_set.remove(&id);
                continue;
            }
            // choose range
            let (offset, avail, is_retx) = if let Some(r) = ss.retransmit.first_range() {
                (r.start, r.end - r.start, true)
            } else if ss.next_new < ss.write_offset {
                let lim = ss.write_offset.min(ss.max_data).min(ss.next_new + credit);
                (ss.next_new, lim.saturating_sub(ss.next_new), false)
            } else {
                (ss.next_new, 0, false)
            };
            let hdr = 1 + varint_len(id) + varint_len(offset) + 2;
            let len = avail.min(room.saturating_sub(hdr) as u64);
            let end = offset + len;
            let fin = ss.fin
                && end == ss.write_offset
                && (!is_retx || ss.retransmit.first_range().map_or(true, |r| r.end <= end))
                && (!ss.fin_sent || ss.fin_pending)
                && (is_retx || len == avail);
            if len == 0 && !fin {
                // flow control blocked or nothing to do
                if ss.has_pending(credit) {
                    self.pending_streams.push_back(id);
                } else {
                    self.pending_set.remove(&id);
                }
                continue;
            }
            let mut t = ty::STREAM | 0x02;
            if offset > 0 {
                t |= 0x04;
            }
            if fin {
                t |= 0x01;
            }
            buf.push(t as u8);
            put_varint(buf, id);
            if offset > 0 {
                put_varint(buf, offset);
            }
            put_varint_len(buf, len, 2);
            if len > 0 {
                ss.copy_range(offset, len as usize, buf);
            }
            if is_retx {
                ss.retransmit.remove(offset..end);
            } else {
                ss.next_new = end;
                self.data_sent += len;
            }
            if fin {
                ss.fin_sent = true;
                ss.fin_pending = false;
            }
            frames.push(SentFrame::Stream { id, offset, len, fin });
            self.stats.frame_tx.stream += 1;
            wrote = true;
            let credit = self.peer_max_data.saturating_sub(self.data_sent);
            if ss.has_pending(credit) {
                self.pending_streams.push_back(id);
            } else {
                self.pending_set.remove(&id);
            }
        }
        wrote
    }

    fn try_mtu_probe(&mut self, now: Instant, buf: &mut Vec<u8>) -> bool {
        if self.mtud.done || self.mtud.in_flight.is_some() || !self.handshake_confirmed || self.state != State::Established {
            return false;
        }
        match self.mtud.next_probe_at {
            Some(t) if t <= now => {}
            _ => return false,
        }
        let lower = self.mtud.lower;
        let upper = self.mtud.upper;
        let mut size = ((lower as u32 + upper as u32) / 2) as u16;
        if upper - size < 20 {
            size = upper;
        }
        if size <= lower {
            self.mtud.done = true;
            return false;
        }
        if self.bytes_in_flight + size as u64 > self.cc.window {
            return false;
        }
        let pn = self.spaces[2].next_pn;
        let pn_len = pn_len_for(pn, self.spaces[2].largest_acked);
        let (pn_off, _) = self.write_header(2, buf, pn, pn_len);
        buf.push(ty::PING as u8);
        self.stats.frame_tx.ping += 1;
        if self.peer_params.as_ref().map_or(false, |p| p.min_ack_delay.is_some()) {
            buf.push(ty::IMMEDIATE_ACK as u8);
            self.stats.frame_tx.immediate_ack += 1;
        }
        buf.resize(size as usize - TAG_LEN, 0);
        self.seal_packet(2, buf, 0, pn_off, pn_len, pn);
        self.spaces[2].next_pn += 1;
        self.stats.path.sent_packets += 1;
        self.stats.path.sent_plpmtud_probes += 1;
        if let Some(q) = &mut self.qlog {
            q.packet_sent(now, 2, pn, size as usize);
        }
        let key_phase = self.one_rtt.as_ref().map_or(false, |o| o.phase);
        if let Some(o) = &mut self.one_rtt {
            o.sent_in_phase += 1;
        }
        let s = &mut self.spaces[2];
        s.sent.insert(
            pn,
            SentPacket {
                time: now,
                size,
                ack_eliciting: true,
                in_flight: true,
                frames: Vec::new(),
                largest_ack: None,
                mtu_probe: Some(size),
                key_phase,
            },
        );
        s.time_of_last_ack_eliciting = Some(now);
        s.ack_eliciting_in_flight += 1;
        s.in_flight_bytes += size as u64;
        self.bytes_in_flight += size as u64;
        self.mtud.in_flight = Some((pn, size));
        self.mtud.next_probe_at = None;
        self.stats.udp_tx.datagrams += 1;
        self.stats.udp_tx.bytes += buf.len() as u64;
        true
    }

    fn write_close(&mut self, now: Instant, buf: &mut Vec<u8>) -> bool {
        let frame = match &self.close_frame {
            Some(f) => f.clone(),
            None => return false,
        };
        let max_size = (self.mtu as usize).max(1200);
        let mut wrote = false;
        let spaces: Vec<usize> = (0..3).filter(|&s| self.space_has_keys(s)).collect();
        let has_initial = spaces.contains(&0);
        for &space in &spaces {
            if space == 2 && !self.handshake_complete && self.side == Side::Client {
                continue;
            }
            let mut f = frame.clone();
            if space < 2 && self.close_app {
                // application close must be sent as a transport close before handshake completes
                f.clear();
                put_varint(&mut f, ty::CONNECTION_CLOSE);
                put_varint(&mut f, 0x0c);
                put_varint(&mut f, 0);
                put_varint(&mut f, 0);
            }
            let start = buf.len();
            let pn = self.spaces[space].next_pn;
            let pn_len = pn_len_for(pn, self.spaces[space].largest_acked);
            let (pn_off, len_off) = self.write_header(space, buf, pn, pn_len);
            if self.spaces[space].unacked_rx {
                self.write_ack(now, space, buf);
            }
            buf.extend_from_slice(&f);
            self.stats.frame_tx.connection_close += 1;
            let mut target = buf.len();
            if target - pn_off < 4 {
                target = pn_off + 4;
            }
            if has_initial && self.side == Side::Client && space == *spaces.last().unwrap() {
                target = target.max(1200 - TAG_LEN);
            }
            buf.resize(target.min(max_size - TAG_LEN), 0);
            if len_off != 0 {
                let payload_len = buf.len() - pn_off + TAG_LEN;
                let v = (payload_len as u16) | 0x4000;
                buf[len_off..len_off + 2].copy_from_slice(&v.to_be_bytes());
            }
            let total = buf.len() + TAG_LEN - start;
            self.seal_packet(space, buf, start, pn_off, pn_len, pn);
            self.spaces[space].next_pn += 1;
            self.stats.path.sent_packets += 1;
            if let Some(q) = &mut self.qlog {
                q.packet_sent(now, space, pn, total);
            }
            wrote = true;
        }
        if wrote {
            self.stats.udp_tx.datagrams += 1;
            self.stats.udp_tx.bytes += buf.len() as u64;
        }
        wrote
    }
EOF
