    // ------------------------------------------------------------------
    // Timers

    pub fn poll_timeout(&self) -> Option<Instant> {
        let mut t: Option<Instant> = None;
        let mut consider = |x: Option<Instant>| {
            if let Some(x) = x {
                t = Some(match t {
                    Some(c) => c.min(x),
                    None => x,
                });
            }
        };
        match self.state {
            State::Drained => return None,
            State::Closing | State::Draining => {
                consider(self.close_deadline);
                return t;
            }
            _ => {}
        }
        consider(self.idle_deadline);
        consider(self.loss_detection_deadline().map(|x| x.0));
        for s in &self.spaces {
            if s.unacked_rx {
                consider(s.ack_deadline);
            }
        }
        if !self.mtud.done && self.mtud.in_flight.is_none() {
            consider(self.mtud.next_probe_at);
        }
        t
    }

    pub fn handle_timeout(&mut self, now: Instant) {
        match self.state {
            State::Drained => return,
            State::Closing | State::Draining => {
                if self.close_deadline.map_or(false, |d| d <= now) {
                    self.state = State::Drained;
                }
                return;
            }
            _ => {}
        }
        if self.idle_deadline.map_or(false, |d| d <= now) {
            self.set_error(ConnError::TimedOut);
            self.state = State::Drained;
            return;
        }
        if let Some((t, _, _)) = self.loss_detection_deadline() {
            if t <= now {
                self.on_loss_timeout(now);
            }
        }
        for s in self.spaces.iter_mut() {
            if s.unacked_rx && s.ack_deadline.map_or(false, |d| d <= now) {
                s.ack_immediate = true;
            }
        }
    }

    // ------------------------------------------------------------------
    // Closing

    pub fn close(&mut self, now: Instant, code: u64, reason: &[u8]) {
        if self.is_closed() {
            return;
        }
        let mut f = Vec::new();
        put_varint(&mut f, ty::APPLICATION_CLOSE);
        put_varint(&mut f, code);
        put_varint(&mut f, reason.len() as u64);
        f.extend_from_slice(reason);
        self.close_frame = Some(f);
        self.close_app = true;
        self.enter_closing(now);
        self.set_error(ConnError::LocallyClosed);
