                std::ptr::write_unaligned(p, segment as u16);
            }
        }
        loop {
            let r = unsafe { libc::sendmsg(self.fd, &hdr, 0) };
            if r >= 0 {
                return Ok(());
            }
            let e = io::Error::last_os_error();
            match e.raw_os_error() {
                Some(libc::EINTR) => continue,
                Some(libc::EIO) | Some(libc::EINVAL) if self.gso && data.len() > segment => {
                    // GSO unsupported on this path: fall back to individual sends
                    self.gso = false;
                    let mut off = 0;
                    while off < data.len() {
                        let end = (off + segment).min(data.len());
                        let _ = self.send_gso(dest, &data[off..end], segment);
                        off = end;
                    }
                    return Ok(());
                }
                _ => return Err(e),
            }
        }
    }

