    pub fn writable(&self) -> bool {
        let mut fds = [libc::pollfd { fd: self.fd, events: libc::POLLOUT, revents: 0 }];
        let r = unsafe { libc::poll(fds.as_mut_ptr(), 1, 0) };
        r > 0 && (fds[0].revents & libc::POLLOUT) != 0
    }

    pub fn wait_writable(&self, timeout_ms: i32) {
        let mut fds = [libc::pollfd { fd: self.fd, events: libc::POLLOUT, revents: 0 }];
        unsafe {
            libc::poll(fds.as_mut_ptr(), 1, timeout_ms);
        }
    }
}
