    pub fn recv_batch(&self, bufs: &mut [Vec<u8>], meta: &mut [(usize, SocketAddr)]) -> usize {
        let n = bufs.len().min(meta.len());
        let mut iovs: Vec<libc::iovec> = Vec::with_capacity(n);
        let mut addrs: Vec<libc::sockaddr_storage> = vec![unsafe { mem::zeroed() }; n];
        let mut hdrs: Vec<libc::mmsghdr> = Vec::with_capacity(n);
        for b in bufs.iter_mut().take(n) {
            iovs.push(libc::iovec { iov_base: b.as_mut_ptr() as *mut libc::c_void, iov_len: b.len() });
        }
        for i in 0..n {
            let mut h: libc::mmsghdr = unsafe { mem::zeroed() };
            h.msg_hdr.msg_name = &mut addrs[i] as *mut _ as *mut libc::c_void;
            h.msg_hdr.msg_namelen = mem::size_of::<libc::sockaddr_storage>() as libc::socklen_t;
            h.msg_hdr.msg_iov = &mut iovs[i] as *mut libc::iovec;
            h.msg_hdr.msg_iovlen = 1;
            hdrs.push(h);
        }
        let r = unsafe { libc::recvmmsg(self.fd, hdrs.as_mut_ptr(), n as libc::c_uint, libc::MSG_DONTWAIT, std::ptr::null_mut()) };
        if r <= 0 {
            return 0;
        }
        let r = r as usize;
        for i in 0..r {
            let addr = from_sockaddr(&addrs[i]).unwrap_or(SocketAddr::new(IpAddr::V4(Ipv4Addr::UNSPECIFIED), 0));
            meta[i] = (hdrs[i].msg_len as usize, normalize(addr));
        }
        r
    }

    /// Sends a GSO batch: `data` contains datagrams of `segment` bytes (last may be shorter).
    pub fn send_gso(&mut self, dest: &SocketAddr, data: &[u8], segment: usize) -> io::Result<()> {
        let (sa, salen) = to_sockaddr(dest, self.ipv6);
        let mut iov = libc::iovec { iov_base: data.as_ptr() as *mut libc::c_void, iov_len: data.len() };
        let mut hdr: libc::msghdr = unsafe { mem::zeroed() };
        hdr.msg_name = &sa as *const _ as *mut libc::c_void;
        hdr.msg_namelen = salen;
        hdr.msg_iov = &mut iov;
        hdr.msg_iovlen = 1;
        let mut cmsg_buf = [0u8; 64];
        if self.gso && data.len() > segment {
            unsafe {
                let space = libc::CMSG_SPACE(mem::size_of::<u16>() as u32) as usize;
                hdr.msg_control = cmsg_buf.as_mut_ptr() as *mut libc::c_void;
                hdr.msg_controllen = space;
                let cmsg = libc::CMSG_FIRSTHDR(&hdr);
                (*cmsg).cmsg_level = libc::SOL_UDP;
                (*cmsg).cmsg_type = 103; // UDP_SEGMENT
                (*cmsg).cmsg_len = libc::CMSG_LEN(mem::size_of::<u16>() as u32) as usize;
                let p = libc::CMSG_DATA(cmsg) as *mut u16;
                std::ptr::write_unaligned(p, segment as u16);
            }
        }
        loop {
            let r = unsafe { libc::sendmsg(self.fd, &hdr, 0) };
            if r >= 0 {
                return Ok(());
            }
            let e = io::Error::last_os_error();
            match e.raw_os_error() {
                Some(libc::EINTR) => continue,
                Some(libc::EIO) | Some(libc::EINVAL) if self.gso && data.len() > segment => {
                    // GSO unsupported on this path: fall back to individual sends
                    self.gso = false;
                    let mut off = 0;
                    while off < data.len() {
                        let end = (off + segment).min(data.len());
                        let _ = self.send_gso(dest, &data[off..end], segment);
                        off = end;
                    }
                    return Ok(());
                }
                _ => return Err(e),
            }
        }
    }

    /// Whether the socket send buffer has room (poll for POLLOUT without blocking).
    pub fn writable(&self) -> bool {
        let mut fds = [libc::pollfd { fd: self.fd, events: libc::POLLOUT, revents: 0 }];
        let r = unsafe { libc::poll(fds.as_mut_ptr(), 1, 0) };
        r > 0 && (fds[0].revents & libc::POLLOUT) != 0
    }

    pub fn wait_writable(&self, timeout_ms: i32) {
        let mut fds = [libc::pollfd { fd: self.fd, events: libc::POLLOUT, revents: 0 }];
        unsafe {
            libc::poll(fds.as_mut_ptr(), 1, timeout_ms);
        }
    }
}
