//! A small HdrHistogram-compatible histogram (3 significant digits).

pub struct Histogram {
    counts: Vec<u64>,
    total: u64,
    max_value: u64,
    min_nz: u64,
}

const SUB_BUCKET_COUNT: u64 = 2048;
const SUB_BUCKET_HALF_COUNT: u64 = 1024;
const SUB_BUCKET_HALF_COUNT_MAGNITUDE: u32 = 10;
const SUB_BUCKET_MASK: u64 = SUB_BUCKET_COUNT - 1;
const LEADING_ZERO_COUNT_BASE: u32 = 64 - SUB_BUCKET_HALF_COUNT_MAGNITUDE - 1;

impl Default for Histogram {
    fn default() -> Self {
        Histogram { counts: Vec::new(), total: 0, max_value: 0, min_nz: u64::MAX }
    }
}

fn bucket_index(v: u64) -> u32 {
    LEADING_ZERO_COUNT_BASE - (v | SUB_BUCKET_MASK).leading_zeros()
}

fn sub_bucket_index(v: u64, b: u32) -> u64 {
    v >> b
}

fn counts_index(b: u32, sb: u64) -> usize {
    let bucket_base = ((b as u64) + 1) << SUB_BUCKET_HALF_COUNT_MAGNITUDE;
    (bucket_base + sb - SUB_BUCKET_HALF_COUNT) as usize
}

fn index_for(v: u64) -> usize {
    let b = bucket_index(v);
    counts_index(b, sub_bucket_index(v, b))
}

fn value_for(index: usize) -> u64 {
    let index = index as u64;
    let mut bucket = (index >> SUB_BUCKET_HALF_COUNT_MAGNITUDE) as i64 - 1;
    let mut sub = (index & (SUB_BUCKET_HALF_COUNT - 1)) + SUB_BUCKET_HALF_COUNT;
    if bucket < 0 {
        sub -= SUB_BUCKET_HALF_COUNT;
        bucket = 0;
    }
    sub << bucket
}

fn size_of_equivalent_range(v: u64) -> u64 {
    let b = bucket_index(v);
    let sb = sub_bucket_index(v, b);
    let adjusted = if sb >= SUB_BUCKET_COUNT { b + 1 } else { b };
    1u64 << adjusted
}

fn lowest_equivalent(v: u64) -> u64 {
    let b = bucket_index(v);
    let sb = sub_bucket_index(v, b);
    sb << b
}

fn highest_equivalent(v: u64) -> u64 {
    let next = lowest_equivalent(v).saturating_add(size_of_equivalent_range(v));
    next.saturating_sub(1)
}

fn median_equivalent(v: u64) -> u64 {
    lowest_equivalent(v).saturating_add(size_of_equivalent_range(v) >> 1)
}

impl Histogram {
    pub fn record(&mut self, v: u64) {
        let idx = index_for(v);
        if idx >= self.counts.len() {
            self.counts.resize(idx + 1, 0);
        }
        self.counts[idx] += 1;
        self.total += 1;
        if v > self.max_value {
            self.max_value = v;
        }
        if v != 0 && v < self.min_nz {
            self.min_nz = v;
        }
    }

    pub fn len(&self) -> u64 {
        self.total
    }

    pub fn mean(&self) -> f64 {
        if self.total == 0 {
            return 0.0;
        }
        let mut total = 0.0f64;
        for (i, &c) in self.counts.iter().enumerate() {
            if c == 0 {
                continue;
            }
            let v = highest_equivalent(value_for(i));
            total += median_equivalent(v) as f64 * c as f64 / self.total as f64;
        }
        total
    }

    pub fn value_at_quantile(&self, q: f64) -> u64 {
        let q = if q > 1.0 { 1.0 } else { q };
        let fractional = q * self.total as f64;
        let mut count_at = fractional.ceil() as u64;
        if count_at == 0 {
            count_at = 1;
        }
        let mut acc = 0u64;
        for (i, &c) in self.counts.iter().enumerate() {
            acc += c;
            if acc >= count_at {
                let v = value_for(i);
                return if q == 0.0 { lowest_equivalent(v) } else { highest_equivalent(v) };
            }
        }
        0
    }

    pub fn min(&self) -> u64 {
        if self.total == 0 || self.counts.first().copied().unwrap_or(0) > 0 {
            0
        } else {
            lowest_equivalent(self.min_nz)
        }
    }

    pub fn max(&self) -> u64 {
        if self.max_value == 0 {
            0
        } else {
            highest_equivalent(self.max_value)
        }
    }
}
