//! tracing-subscriber compatible log output (fmt layer with EnvFilter semantics).

use std::io::Write;
use std::sync::OnceLock;

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Level {
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

struct Directive {
    target: Option<String>,
    level: u8, // 0 = off
}

struct Filter {
    directives: Vec<Directive>,
    ansi: bool,
}

static FILTER: OnceLock<Filter> = OnceLock::new();

fn parse_level(s: &str) -> Option<u8> {
    match s.to_ascii_lowercase().as_str() {
        "off" | "0" => Some(0),
        "error" | "1" => Some(1),
        "warn" | "2" => Some(2),
        "info" | "3" => Some(3),
        "debug" | "4" => Some(4),
        "trace" | "5" => Some(5),
        _ => None,
    }
}

fn parse_directive(s: &str) -> Result<Option<Directive>, ()> {
    if let Some(l) = parse_level(s) {
        return Ok(Some(Directive { target: None, level: l }));
    }
    let (lhs, level) = match s.rfind('=') {
        Some(i) => {
            let lvl = parse_level(&s[i + 1..]).ok_or(())?;
            (&s[..i], lvl)
        }
        None => (s, 5),
    };
    let (target, has_span) = match lhs.find('[') {
        Some(i) => {
            if !lhs.ends_with(']') {
                return Err(());
            }
            (&lhs[..i], true)
        }
        None => (lhs, false),
    };
    if target.is_empty() && !has_span {
        return Err(());
    }
    if target.contains(|c: char| c == '{' || c == '}' || c == '[' || c == ']' || c == '=' || c.is_whitespace()) {
        return Err(());
    }
    if has_span {
        // span-scoped directives never match since we emit no spans
        return Ok(None);
    }
    Ok(Some(Directive { target: Some(target.to_string()), level }))
}

fn build_filter() -> Filter {
    let ansi = match std::env::var_os("NO_COLOR") {
        Some(v) => v.is_empty(),
        None => true,
    };
    let default = || vec![Directive { target: None, level: 2 }];
    let directives = match std::env::var("RUST_LOG") {
        Ok(v) => {
            let mut ds = Vec::new();
            let mut ok = true;
            for part in v.split(',').filter(|p| !p.is_empty()) {
                match parse_directive(part) {
                    Ok(Some(d)) => ds.push(d),
                    Ok(None) => {}
                    Err(()) => {
                        ok = false;
                        break;
                    }
                }
            }
            if ok {
                ds
            } else {
                default()
            }
        }
        Err(_) => default(),
    };
    Filter { directives, ansi }
}

pub fn init() {
    let _ = FILTER.get_or_init(build_filter);
}

fn filter() -> &'static Filter {
    FILTER.get_or_init(build_filter)
}

pub fn enabled(level: Level, target: &str) -> bool {
    let f = filter();
    // most specific matching directive wins (longest target); level-only is least specific
    let mut best: Option<&Directive> = None;
    for d in &f.directives {
        let matches = match &d.target {
            Some(t) => target.starts_with(t.as_str()),
            None => true,
        };
        if !matches {
            continue;
        }
        let spec = d.target.as_ref().map_or(0, |t| t.len() + 1);
        match best {
            Some(b) => {
                let bspec = b.target.as_ref().map_or(0, |t| t.len() + 1);
                if spec >= bspec {
                    best = Some(d);
                }
            }
            None => best = Some(d),
        }
    }
    match best {
        Some(d) => (level as u8) <= d.level,
        None => false,
    }
}

fn timestamp() -> String {
    let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default();
    let secs = now.as_secs() as i64;
    let micros = now.subsec_micros();
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let (h, m, s) = (rem / 3600, (rem % 3600) / 60, rem % 60);
    // civil from days (Howard Hinnant)
    let z = days + 719468;
    let era = z.div_euclid(146097);
    let doe = z.rem_euclid(146097);
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let mo = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if mo <= 2 { y + 1 } else { y };
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z", y, mo, d, h, m, s, micros)
}

pub fn log(level: Level, target: &str, msg: std::fmt::Arguments) {
    if !enabled(level, target) {
        return;
    }
    let f = filter();
    let ts = timestamp();
    let line = if f.ansi {
        let lvl = match level {
            Level::Error => "\x1b[31mERROR\x1b[0m",
            Level::Warn => "\x1b[33m WARN\x1b[0m",
            Level::Info => "\x1b[32m INFO\x1b[0m",
            Level::Debug => "\x1b[34mDEBUG\x1b[0m",
            Level::Trace => "\x1b[35mTRACE\x1b[0m",
        };
        format!("\x1b[2m{}\x1b[0m {} \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}\n", ts, lvl, target, msg)
    } else {
        let lvl = match level {
            Level::Error => "ERROR",
            Level::Warn => " WARN",
            Level::Info => " INFO",
            Level::Debug => "DEBUG",
            Level::Trace => "TRACE",
        };
        format!("{} {} {}: {}\n", ts, lvl, target, msg)
    };
    let out = std::io::stdout();
    let mut lock = out.lock();
    let _ = lock.write_all(line.as_bytes());
    let _ = lock.flush();
}

#[macro_export]
macro_rules! log_error {
    ($target:expr, $($arg:tt)*) => { $crate::log::log($crate::log::Level::Error, $target, format_args!($($arg)*)) };
}
#[macro_export]
macro_rules! log_warn {
    ($target:expr, $($arg:tt)*) => { $crate::log::log($crate::log::Level::Warn, $target, format_args!($($arg)*)) };
}
#[macro_export]
macro_rules! log_info {
    ($target:expr, $($arg:tt)*) => { $crate::log::log($crate::log::Level::Info, $target, format_args!($($arg)*)) };
}
#[macro_export]
macro_rules! log_debug {
    ($target:expr, $($arg:tt)*) => {
        if $crate::log::enabled($crate::log::Level::Debug, $target) {
            $crate::log::log($crate::log::Level::Debug, $target, format_args!($($arg)*))
        }
    };
}
EOF
echo ok"}

