//! Endpoint: owns the UDP socket and routes datagrams to connections.

use crate::conn::{Config, Connection, EndpointEvent, LOCAL_CID_LEN};
use crate::packet::{parse_header, LongType, ParsedHeader, QUIC_V1};
use crate::tls::ServerCrypto;
use crate::udp::UdpSocket;
use std::collections::HashMap;
use std::io::Write;
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::Instant;

pub struct Endpoint {
    pub socket: UdpSocket,
    pub conns: Vec<Option<Connection>>,
    cid_map: HashMap<Vec<u8>, usize>,
    server: Option<Arc<ServerCrypto>>,
    pub cfg: Arc<Config>,
    pub accepted: Vec<usize>,
    rx_bufs: Vec<Vec<u8>>,
    rx_meta: Vec<(usize, SocketAddr)>,
    tx_batch: Vec<u8>,
    tx_one: Vec<u8>,
    pub qlog: Option<std::fs::File>,
}

const RX_BATCH: usize = 64;
const RX_BUF: usize = 2048;

impl Endpoint {
    pub fn new(socket: UdpSocket, cfg: Arc<Config>, server: Option<Arc<ServerCrypto>>) -> Endpoint {
        Endpoint {
            socket,
            conns: Vec::new(),
            cid_map: HashMap::new(),
            server,
            cfg,
            accepted: Vec::new(),
            rx_bufs: (0..RX_BATCH).map(|_| vec![0u8; RX_BUF]).collect(),
            rx_meta: vec![(0, SocketAddr::from(([0, 0, 0, 0], 0))); RX_BATCH],
            tx_batch: Vec::with_capacity(65536),
            tx_one: Vec::with_capacity(2048),
            qlog: None,
        }
    }

    pub fn connect(&mut self, remote: SocketAddr, server_name: &str, now: Instant) -> usize {
        let c = Connection::new_client(self.cfg.clone(), remote, server_name, now);
        let idx = self.insert(c);
        idx
    }

    fn insert(&mut self, mut c: Connection) -> usize {
        let idx = match self.conns.iter().position(|x| x.is_none()) {
            Some(i) => i,
            None => {
                self.conns.push(None);
                self.conns.len() - 1
            }
        };
        self.cid_map.insert(c.local_cid().to_vec(), idx);
        if let Some(q) = &mut c.qlog {
            q.set_group(crate::coding::hex(c.local_cid()));
        }
        self.conns[idx] = Some(c);
        idx
    }

    pub fn conn(&mut self, idx: usize) -> Option<&mut Connection> {
        self.conns.get_mut(idx).and_then(|c| c.as_mut())
    }

    /// Reads all pending datagrams. Returns true if anything was received.
    pub fn handle_input(&mut self, now: Instant) -> bool {
        let mut any = false;
        for _round in 0..16 {
            let n = self.socket.recv_batch(&mut self.rx_bufs, &mut self.rx_meta);
            if n == 0 {
                break;
            }
            any = true;
            for i in 0..n {
                let (len, from) = self.rx_meta[i];
                let mut buf = std::mem::take(&mut self.rx_bufs[i]);
                self.handle_datagram(now, from, &mut buf[..len]);
                self.rx_bufs[i] = buf;
            }
            if n < RX_BATCH {
                break;
            }
        }
        any
    }

    fn handle_datagram(&mut self, now: Instant, from: SocketAddr, data: &mut [u8]) {
        if data.is_empty() {
            return;
        }
        let dcid: Vec<u8> = if data[0] & 0x80 != 0 {
            if data.len() < 6 {
                return;
            }
            let l = data[5] as usize;
            if data.len() < 6 + l {
                return;
            }
            data[6..6 + l].to_vec()
        } else {
            if data.len() < 1 + LOCAL_CID_LEN {
                return;
            }
            data[1..1 + LOCAL_CID_LEN].to_vec()
        };
        let idx = match self.cid_map.get(&dcid) {
            Some(&i) => Some(i),
            None => {
                if self.server.is_none() {
                    // client: route everything to the single connection
                    self.conns.iter().position(|c| c.is_some())
                } else {
                    None
                }
            }
        };
        if let Some(i) = idx {
            if let Some(c) = self.conns[i].as_mut() {
                c.handle_datagram(now, data, 1);
            }
            self.process_endpoint_events(i);
            return;
        }
