        let server = match &self.server {
            Some(s) => s.clone(),
            None => return,
        };
        match parse_header(data, LOCAL_CID_LEN) {
            Some(ParsedHeader::Packet(h)) => {
                if h.long != Some(LongType::Initial) || data.len() < 1200 || h.dcid.len() < 8 {
                    return;
                }
                let mut local = vec![0u8; LOCAL_CID_LEN];
                crate::crypto::random_bytes(&mut local);
                let c = Connection::new_server(self.cfg.clone(), server, from, &h.dcid, &h.scid, local, now);
                let idx = self.insert(c);
                self.cid_map.insert(h.dcid.clone(), idx);
                self.accepted.push(idx);
                if let Some(c) = self.conns[idx].as_mut() {
                    c.handle_datagram(now, data, 1);
                }
                self.process_endpoint_events(idx);
            }
            Some(ParsedHeader::Unsupported { dcid, scid, .. }) => {
                if data.len() < 1200 {
                    return;
                }
                // Version negotiation
                let mut p = Vec::new();
                let mut r = [0u8; 1];
                crate::crypto::random_bytes(&mut r);
                p.push(0x80 | r[0]);
                p.extend_from_slice(&0u32.to_be_bytes());
                p.push(scid.len() as u8);
                p.extend_from_slice(&scid);
                p.push(dcid.len() as u8);
                p.extend_from_slice(&dcid);
                p.extend_from_slice(&0x0a1a2a3au32.to_be_bytes());
                p.extend_from_slice(&QUIC_V1.to_be_bytes());
                let _ = self.socket.send_gso(&from, &p, p.len());
            }
            _ => {}
        }
    }

    fn process_endpoint_events(&mut self, idx: usize) {
        let mut evs = Vec::new();
        if let Some(c) = self.conns[idx].as_mut() {
            while let Some(e) = c.poll_endpoint_event() {
                evs.push(e);
            }
        }
        for e in evs {
            match e {
                EndpointEvent::NewCid(cid) => {
                    self.cid_map.insert(cid, idx);
                }
                EndpointEvent::RetireCid(cid) => {
                    self.cid_map.remove(&cid);
                }
            }
        }
    }

    pub fn handle_timeouts(&mut self, now: Instant) {
        for i in 0..self.conns.len() {
            if let Some(c) = self.conns[i].as_mut() {
                if c.poll_timeout().map_or(false, |t| t <= now) {
                    c.handle_timeout(now);
                }
            }
        }
    }

    pub fn next_timeout(&self) -> Option<Instant> {
        self.conns.iter().filter_map(|c| c.as_ref().and_then(|c| c.poll_timeout())).min()
    }

    /// Sends everything the connections want to send.
    pub fn flush(&mut self, now: Instant) {
        for i in 0..self.conns.len() {
            let mut conn = match self.conns[i].take() {
                Some(c) => c,
                None => continue,
            };
            let dest = conn.remote;
            self.tx_batch.clear();
            let mut segment = 0usize;
            let mut count = 0usize;
            let mut budget = 256usize;
            loop {
                if budget == 0 {
                    break;
                }
                budget -= 1;
                if !conn.poll_transmit(now, &mut self.tx_one) {
                    break;
                }
                let len = self.tx_one.len();
                let fits = self.socket.gso
                    && count > 0
                    && len <= segment
                    && count < 64
                    && self.tx_batch.len() + len <= 65000;
                if count > 0 && !fits {
                    self.send_batch(&mut conn, dest, segment);
                    count = 0;
                }
                if count == 0 {
                    segment = len;
                }
                self.tx_batch.extend_from_slice(&self.tx_one);
                count += 1;
                if len < segment {
                    // a short datagram must end the batch
                    self.send_batch(&mut conn, dest, segment);
                    count = 0;
                }
            }
            if count > 0 {
                self.send_batch(&mut conn, dest, segment);
            }
            if let Some(f) = &mut self.qlog {
                if let Some(q) = &mut conn.qlog {
                    if !q.buf.is_empty() {
                        let _ = f.write_all(&q.buf);
                        q.buf.clear();
                    }
                }
            }
            self.conns[i] = Some(conn);
            self.process_endpoint_events(i);
        }
    }

    fn send_batch(&mut self, conn: &mut Connection, dest: SocketAddr, segment: usize) {
        if self.tx_batch.is_empty() {
            return;
        }
        loop {
            match self.socket.send_gso(&dest, &self.tx_batch, segment) {
                Ok(()) => break,
                Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                    self.socket.wait_writable(10);
                    continue;
                }
                Err(_) => break,
            }
        }
        conn.stats.udp_tx.ios += 1;
        self.tx_batch.clear();
    }

    /// Removes drained connections, returning their indices.
    pub fn reap(&mut self) -> Vec<usize> {
        let mut out = Vec::new();
        for i in 0..self.conns.len() {
            let drained = self.conns[i].as_ref().map_or(false, |c| c.is_drained());
            if drained {
                self.conns[i] = None;
                self.cid_map.retain(|_, v| *v != i);
                out.push(i);
            }
        }
        out
    }

    pub fn is_idle(&self) -> bool {
        self.conns.iter().all(|c| c.is_none())
    }
}
