use crate::hdr::Histogram;
use std::cell::RefCell;
use std::rc::Rc;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

pub struct StreamStats {
    pub id: u64,
    pub request_size: u64,
    pub bytes: u64,
    pub sender: bool,
    pub finished: bool,
}

pub type StreamStatsRef = Rc<RefCell<StreamStats>>;

#[derive(Default)]
pub struct OpenStreamStats {
    pub list: Vec<StreamStatsRef>,
}

impl OpenStreamStats {
    pub fn new_stream(&mut self, id: u64, size: u64, sender: bool) -> StreamStatsRef {
        let s = Rc::new(RefCell::new(StreamStats { id, request_size: size, bytes: 0, sender, finished: false }));
        self.list.push(s.clone());
        s
    }
}

struct StreamInterval {
    id: u64,
    bytes: u64,
    sender: bool,
}

struct Interval {
    start: f64,
    end: f64,
    streams: Vec<StreamInterval>,
}

pub struct Stats {
    pub start: Instant,
    start_unix: u64,
    pub requests: u64,
    pub upload_duration: Histogram,
    pub download_duration: Histogram,
    pub fbl: Histogram,
    pub upload_throughput: Histogram,
    pub download_throughput: Histogram,
    intervals: Vec<Interval>,
}

impl Stats {
    pub fn new(now: Instant) -> Stats {
        Stats {
            start: now,
            start_unix: SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0),
            requests: 0,
            upload_duration: Histogram::default(),
            download_duration: Histogram::default(),
            fbl: Histogram::default(),
            upload_throughput: Histogram::default(),
            download_throughput: Histogram::default(),
            intervals: Vec::new(),
        }
    }

    pub fn record_upload(&mut self, size: u64, d: Duration) {
        self.upload_duration.record(d.as_micros() as u64);
        self.upload_throughput.record(throughput(size, d));
    }

    pub fn record_download(&mut self, size: u64, d: Duration, fbl: Duration) {
        self.requests += 1;
        self.download_duration.record(d.as_micros() as u64);
        self.fbl.record(fbl.as_micros() as u64);
        self.download_throughput.record(throughput(size, d));
    }

    pub fn on_interval(&mut self, start: Instant, now: Instant, open: &mut OpenStreamStats) {
        let s = start.saturating_duration_since(self.start).as_secs_f64();
        let e = now.saturating_duration_since(self.start).as_secs_f64();
        let mut streams = Vec::new();
        open.list.retain(|st| {
            let mut st = st.borrow_mut();
            if st.request_size > 0 {
                streams.push(StreamInterval { id: st.id, bytes: st.bytes, sender: st.sender });
            }
            st.bytes = 0;
            !st.finished
        });
        self.intervals.push(Interval { start: s, end: e, streams });
    }

    pub fn print(&self, now: Instant) -> String {
        let dt = now.saturating_duration_since(self.start);
        let rps = self.requests as f64 / dt.as_secs_f64();
        let mut out = String::new();
        out.push_str("Overall stats:\n");
        out.push_str(&format!("RPS: {:.2} ({} requests in {:.2?})\n", rps, self.requests, dt));
        out.push('\n');
        out.push_str("Stream metrics:\n\n");
        out.push_str("      │ Upload Duration │ Download Duration | FBL        | Upload Throughput | Download Throughput\n");
        out.push_str("──────┼─────────────────┼───────────────────┼────────────┼───────────────────┼────────────────────\n");
        let dur = |h: &Histogram, f: &dyn Fn(&Histogram) -> u64| format!("{:.2?}", Duration::from_micros(f(h)));
        let thr = |h: &Histogram, f: &dyn Fn(&Histogram) -> f64| format!("{:.2} Mb/s", f(h) * 8.0 / 1_000_000.0);
        let rows: [(&str, Option<f64>); 6] =
            [("AVG", None), ("P0", Some(0.0)), ("P10", Some(0.1)), ("P50", Some(0.5)), ("P90", Some(0.9)), ("P100", Some(1.0))];
        for (label, q) in rows.iter() {
            let (ud, dd, fb, ut, dtp) = match q {
                None => (
                    dur(&self.upload_duration, &|h| h.mean() as u64),
                    dur(&self.download_duration, &|h| h.mean() as u64),
                    dur(&self.fbl, &|h| h.mean() as u64),
                    thr(&self.upload_throughput, &|h| h.mean()),
                    thr(&self.download_throughput, &|h| h.mean()),
                ),
                Some(q) => {
                    let q = *q;
                    (
                        dur(&self.upload_duration, &|h| h.value_at_quantile(q)),
                        dur(&self.download_duration, &|h| h.value_at_quantile(q)),
                        dur(&self.fbl, &|h| h.value_at_quantile(q)),
                        thr(&self.upload_throughput, &|h| h.value_at_quantile(q) as f64),
                        thr(&self.download_throughput, &|h| h.value_at_quantile(q) as f64),
                    )
                }
            };
            out.push_str(&format!(
                " {:<4} │ {:>15} │ {:>17} │ {:>10} │ {:>17} │ {:>18}\n",
                label, ud, dd, fb, ut, dtp
            ));
        }
        out.push('\n');
        out
    }

    pub fn json(&self) -> String {
        let mut s = String::new();
        s.push_str(&format!("{{\"start\":{{\"timestamp\":{{\"timesecs\":{}}}}},\"intervals\":[", self.start_unix));
        for (i, iv) in self.intervals.iter().enumerate() {
            if i > 0 {
                s.push(',');
            }
            let secs = iv.end - iv.start;
            s.push_str("{\"streams\":[");
            for (j, st) in iv.streams.iter().enumerate() {
                if j > 0 {
                    s.push(',');
                }
                s.push_str(&format!(
                    "{{\"id\":{},\"start\":{},\"end\":{},\"seconds\":{},\"bytes\":{},\"bits_per_second\":{},\"sender\":{}}}",
                    st.id,
                    json_f64(iv.start),
                    json_f64(iv.end),
                    json_f64(secs),
                    st.bytes,
                    json_f64(st.bytes as f64 * 8.0 / secs),
                    st.sender
                ));
            }
            let any_sender = iv.streams.iter().any(|x| x.sender);
            let bytes: u64 = iv.streams.iter().filter(|x| x.sender == any_sender).map(|x| x.bytes).sum();
            s.push_str(&format!(
                "],\"sum\":{{\"start\":{},\"end\":{},\"seconds\":{},\"bytes\":{},\"bits_per_second\":{},\"sender\":{}}}}}",
                json_f64(iv.start),
                json_f64(iv.end),
                json_f64(secs),
                bytes,
                json_f64(bytes as f64 * 8.0 / secs),
                any_sender
            ));
        }
        s.push_str("]}");
        s
    }
}

fn throughput(size: u64, d: Duration) -> u64 {
    let secs = d.as_secs_f64();
    (size as f64 / secs) as u64
}

/// Formats an f64 the way serde_json (ryu) does.
pub fn json_f64(v: f64) -> String {
    if !v.is_finite() {
        return "null".to_string();
    }
    if v == 0.0 {
        return if v.is_sign_negative() { "-0.0".into() } else { "0.0".into() };
    }
    let e = format!("{:e}", v);
    let (mant, exp) = e.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let neg = mant.starts_with('-');
    let mant = mant.trim_start_matches('-');
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    let len = digits.len() as i32;
    let kk = exp + 1; // position of decimal point relative to digits start
    let mut out = String::new();
    if neg {
        out.push('-');
    }
    if 0 <= exp && kk <= 16 && len <= kk {
        // integer
        out.push_str(&digits);
        for _ in 0..(kk - len) {
            out.push('0');
        }
        out.push_str(".0");
    } else if 0 < kk && kk <= 16 {
        out.push_str(&digits[..kk as usize]);
        out.push('.');
        out.push_str(&digits[kk as usize..]);
    } else if -5 < kk && kk <= 0 {
        out.push_str("0.");
        for _ in 0..(-kk) {
            out.push('0');
        }
        out.push_str(&digits);
    } else if len == 1 {
        out.push_str(&digits);
        out.push('e');
        out.push_str(&(kk - 1).to_string());
    } else {
        out.push_str(&digits[..1]);
        out.push('.');
        out.push_str(&digits[1..]);
        out.push('e');
        out.push_str(&(kk - 1).to_string());
    }
    out
}
EOF
