{"command":"cat > /workspace/src/error.rs <<'EOF'
//! anyhow-like error with a context chain, displayed as "ctx: cause: cause".

use std::fmt;

#[derive(Debug, Clone)]
pub struct Error {
    chain: Vec<String>,
}

impl Error {
    pub fn msg<S: Into<String>>(s: S) -> Error {
        Error { chain: vec![s.into()] }
    }
    pub fn from_std<E: std::error::Error>(e: &E) -> Error {
        let mut chain = vec![e.to_string()];
        let mut src = e.source();
        while let Some(s) = src {
            chain.push(s.to_string());
            src = s.source();
        }
        Error { chain }
    }
    pub fn context<S: Into<String>>(mut self, c: S) -> Error {
        self.chain.insert(0, c.into());
        self
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.chain.join(": "))
    }
}

pub trait Context<T> {
    fn context<S: Into<String>>(self, c: S) -> Result<T, Error>;
}

impl<T, E: std::error::Error> Context<T> for Result<T, E> {
    fn context<S: Into<String>>(self, c: S) -> Result<T, Error> {
        self.map_err(|e| Error::from_std(&e).context(c))
    }
}

pub type Result<T> = std::result::Result<T, Error>;
