//! Shared helpers for client and server.

use crate::cli::CommonOpt;
use crate::conn::Config;
use crate::error::{Context, Result};
use crate::recovery::CongestionAlgorithm;
use crate::udp::UdpSocket;
use crate::{log_warn};
use std::net::SocketAddr;
use std::time::Duration;

pub fn bind_socket(addr: SocketAddr, send_buffer_size: u64, recv_buffer_size: u64) -> Result<UdpSocket> {
    let socket = UdpSocket::bind(addr).context("binding endpoint")?;
    let send = send_buffer_size as usize;
    if let Err(e) = socket.set_send_buffer_size(send) {
        log_warn!("perf", "Unable to set desired send buffer size: {}", e);
    }
    if let Ok(actual) = socket.send_buffer_size() {
        if actual < send {
            log_warn!("perf", "Unable to set desired send buffer size. Desired: {}, Actual: {}", send, actual);
        }
    }
    let recv = recv_buffer_size as usize;
    if let Err(e) = socket.set_recv_buffer_size(recv) {
        log_warn!("perf", "Unable to set desired recv buffer size: {}", e);
    }
    if let Ok(actual) = socket.recv_buffer_size() {
        if actual < recv {
            log_warn!("perf", "Unable to set desired recv buffer size. Desired: {}, Actual: {}", recv, actual);
        }
    }
    Ok(socket)
}

pub fn transport_config(opt: &CommonOpt, qlog_title: &str) -> Config {
    let mut c = Config::default();
    c.initial_mtu = opt.initial_mtu;
    c.max_udp_payload = opt.max_udp_payload_size;
    c.mtu_upper = 1452u16.min(opt.max_udp_payload_size.max(1200));
    if c.initial_mtu > c.mtu_upper {
        c.mtu_upper = c.initial_mtu;
    }
    if let Some(r) = opt.initial_rtt {
        c.initial_rtt = Duration::from_millis(r);
    }
    if let Some(w) = opt.stream_receive_window {
        c.stream_window = w.min(crate::coding::VARINT_MAX);
    }
    if let Some(w) = opt.receive_window {
        c.conn_window = w.min(crate::coding::VARINT_MAX);
    }
    if let Some(w) = opt.send_window {
        c.send_window = w;
    }
    c.cc = opt.cong_alg.unwrap_or(CongestionAlgorithm::Cubic);
    c.ack_frequency = opt.ack_frequency;
    c.no_protection = opt.no_protection;
    c.keylog = opt.keylog;
    if opt.qlog_file.is_some() {
        c.qlog_title = Some(qlog_title.to_string());
    }
    c
}

pub fn open_qlog(opt: &CommonOpt, title: &str) -> Result<Option<std::fs::File>> {
    match &opt.qlog_file {
        None => Ok(None),
        Some(p) => {
            use std::io::Write;
            let mut f = std::fs::File::create(p).context("creating qlog file")?;
            let q = crate::qlog::Qlog::new(title.to_string(), std::time::Instant::now());
            let _ = f.write_all(&q.header());
            Ok(Some(f))
        }
    }
}

/// Static buffer of payload bytes.
pub static DATA: [u8; 65536] = [42u8; 65536];

pub fn stream_name(id: u64) -> String {
    let initiator = if id & 1 == 0 { "client" } else { "server" };
    let dir = if id & 2 == 0 { "bidirectional" } else { "unidirectional" };
    format!("{} {} stream {}", initiator, dir, id >> 2)
}

pub fn print_out(s: &str) {
    use std::io::Write;
    let out = std::io::stdout();
    let mut l = out.lock();
    let _ = l.write_all(s.as_bytes());
    let _ = l.flush();
}
