fn install_sigint() -> i32 {
    let mut fds = [0i32; 2];
    unsafe {
        if libc::pipe2(fds.as_mut_ptr(), libc::O_NONBLOCK | libc::O_CLOEXEC) == 0 {
            WAKE_FD = fds[1];
        } else {
            fds[0] = -1;
        }
        libc::signal(libc::SIGINT, on_sigint as usize);
    }
    fds[0]
}

/// Validates a DNS name the way rustls-pki-types does.
fn valid_dns_name(s: &str) -> bool {
    #[derive(Clone, Copy)]
    enum St {
        Start,
        Next,
        NumericOnly(usize),
        NextAfterNumericOnly,
        Subsequent(usize),
        Hyphen(usize),
    }
    let b = s.as_bytes();
    if b.len() > 253 {
        return false;
    }
    let mut st = St::Start;
    for &ch in b {
        st = match (st, ch) {
            (St::Start | St::Next | St::NextAfterNumericOnly | St::Hyphen(_), b'.') => return false,
            (St::Subsequent(_), b'.') => St::Next,
            (St::NumericOnly(_), b'.') => St::NextAfterNumericOnly,
            (St::Subsequent(l) | St::NumericOnly(l) | St::Hyphen(l), _) if l >= 63 => return false,
            (St::Start | St::Next | St::NextAfterNumericOnly, b'0'..=b'9') => St::NumericOnly(1),
            (St::NumericOnly(l), b'0'..=b'9') => St::NumericOnly(l + 1),
            (St::Start | St::Next | St::NextAfterNumericOnly, b'a'..=b'z' | b'A'..=b'Z' | b'_') => St::Subsequent(1),
            (St::Subsequent(l) | St::NumericOnly(l) | St::Hyphen(l), b'-') => St::Hyphen(l + 1),
            (St::Subsequent(l) | St::NumericOnly(l) | St::Hyphen(l), b'a'..=b'z' | b'A'..=b'Z' | b'_' | b'0'..=b'9') => {
                St::Subsequent(l + 1)
            }
            _ => return false,
        };
    }
    !matches!(st, St::Start | St::Hyphen(_) | St::NumericOnly(_))
}

#[derive(PartialEq, Eq, Clone, Copy, Debug)]
enum Phase {
    Uploading,
    WaitAck,
    AcceptResponse,
    Downloading,
}

struct Request {
    bidi: bool,
    send_id: u64,
    recv_id: Option<u64>,
    phase: Phase,
    start: Instant,
    header: [u8; 8],
    header_written: usize,
    upload_left: u64,
    upload_size: u64,
    download_size: u64,
    download_start: Instant,
    first_byte: Option<Duration>,
    send_stats: Option<StreamStatsRef>,
    recv_stats: Option<StreamStatsRef>,
    acked: bool,
}

enum Outcome {
    Pending,
    Done,
    Failed(Error),
}

fn conn_lost(e: &ConnError) -> Error {
    Error::msg(e.to_string()).context("connection lost")
}

fn stream_err(e: StreamError) -> Error {
    match e {
        StreamError::ConnectionLost(c) => conn_lost(&c),
        other => Error::msg(other.to_string()),
    }
}

impl Request {
    fn new(bidi: bool, id: u64, upload: u64, download: u64, now: Instant, open: &mut OpenStreamStats) -> Request {
        let send_stats = if upload > 0 { Some(open.new_stream(id, upload, true)) } else { None };
        Request {
            bidi,
            send_id: id,
            recv_id: if bidi { Some(id) } else { None },
            phase: Phase::Uploading,
            start: now,
            header: download.to_be_bytes(),
            header_written: 0,
            upload_left: upload,
            upload_size: upload,
            download_size: download,
            download_start: now,
            first_byte: None,
            send_stats,
            recv_stats: None,
            acked: false,
        }
    }

    fn start_download(&mut self, now: Instant, open: &mut OpenStreamStats) {
        self.download_start = now;
        if self.download_size > 0 {
            if let Some(rid) = self.recv_id {
                self.recv_stats = Some(open.new_stream(rid, self.download_size, false));
            }
        }
    }

    fn after_upload(&mut self, now: Instant, stats: &mut Stats, open: &mut OpenStreamStats) -> Outcome {
        // upload phase complete (or skipped)
        if self.download_size == 0 {
            return Outcome::Done;
        }
        if self.bidi {
            self.phase = Phase::Downloading;
            self.start_download(now, open);
        } else {
            self.phase = Phase::AcceptResponse;
            self.download_start = now;
        }
        let _ = stats;
        Outcome::Pending
    }

    fn poll(
        &mut self,
        conn: &mut Connection,
        now: Instant,
        stats: &mut Stats,
        open: &mut OpenStreamStats,
        uni_queue: &mut std::collections::VecDeque<u64>,
    ) -> Outcome {
        loop {
            match self.phase {
                Phase::Uploading => {
                    while self.header_written < 8 {
                        match conn.write(self.send_id, &self.header[self.header_written..]) {
                            Ok(0) => return Outcome::Pending,
                            Ok(n) => self.header_written += n,
                            Err(e) => return Outcome::Failed(stream_err(e)),
                        }
                    }
                    while self.upload_left > 0 {
                        let chunk = (self.upload_left as usize).min(DATA.len());
                        match conn.write(self.send_id, &DATA[..chunk]) {
                            Ok(0) => return Outcome::Pending,
                            Ok(n) => {
                                self.upload_left -= n as u64;
                                if let Some(s) = &self.send_stats {
                                    s.borrow_mut().bytes += n as u64;
                                }
                            }
                            Err(e) => {
                                let err = stream_err(e);
                                return Outcome::Failed(if self.bidi { err.context("sending response") } else { err });
                            }
                        }
                    }
                    if let Err(e) = conn.finish(self.send_id) {
                        return Outcome::Failed(stream_err(e));
                    }
                    if self.upload_size > 0 {
                        self.phase = Phase::WaitAck;
                    } else {
                        match self.after_upload(now, stats, open) {
                            Outcome::Pending => continue,
                            o => return o,
                        }
                    }
                }
                Phase::WaitAck => {
                    if !self.acked {
                        if let Some(e) = conn.error() {
                            return Outcome::Failed(conn_lost(e));
                        }
                        return Outcome::Pending;
                    }
                    let d = now.saturating_duration_since(self.start);
                    if let Some(s) = &self.send_stats {
                        s.borrow_mut().finished = true;
                    }
                    stats.record_upload(self.upload_size, d);
                    log_debug!("perf::client", "upload finished on {}", stream_name(self.send_id));
                    match self.after_upload(now, stats, open) {
                        Outcome::Pending => continue,
                        o => return o,
                    }
                }
                Phase::AcceptResponse => {
                    if let Some(id) = uni_queue.pop_front() {
                        self.recv_id = Some(id);
                        self.phase = Phase::Downloading;
                        let ds = self.download_start;
                        self.start_download(ds, open);
                        continue;
                    }
                    if let Some(e) = conn.error() {
                        return Outcome::Failed(Error::msg(e.to_string()));
                    }
                    return Outcome::Pending;
                }
                Phase::Downloading => {
                    let rid = self.recv_id.unwrap();
                    loop {
                        match conn.read(rid, usize::MAX, None) {
                            Ok(Some(0)) => return Outcome::Pending,
                            Ok(Some(n)) => {
                                if self.first_byte.is_none() {
                                    self.first_byte = Some(now.saturating_duration_since(self.download_start));
                                }
                                if let Some(s) = &self.recv_stats {
                                    s.borrow_mut().bytes += n as u64;
                                }
                            }
                            Ok(None) => {
                                let d = now.saturating_duration_since(self.download_start);
                                if let Some(s) = &self.recv_stats {
                                    s.borrow_mut().finished = true;
                                }
                                let fbl = self.first_byte.unwrap_or(d);
                                stats.record_download(self.download_size, d, fbl);
                                log_debug!("perf::client", "response finished on {}", stream_name(rid));
                                return Outcome::Done;
                            }
                            Err(e) => return Outcome::Failed(stream_err(e)),
                        }
                    }
                }
            }
        }
    }
}

pub fn run(opt: ClientOpt) -> Result<()> {
    let mut host_parts = opt.host.split(':');
    let host_name = host_parts.next().unwrap().to_string();
    let host_port: u16 = host_parts.next().map_or(Ok(443), |x| x.parse::<u16>()).context("parsing port")?;
    let addr = match opt.ip {
        None => opt.host.to_socket_addrs().context("resolving host")?.next().unwrap(),
        Some(ip) => SocketAddr::new(ip, host_port),
    };
    log_info!("perf::client", "connecting to {} at {}", host_name, addr);
    let bind_addr = opt.local_addr.unwrap_or_else(|| {
        let unspec = if addr.is_ipv4() { Ipv4Addr::UNSPECIFIED.into() } else { Ipv6Addr::UNSPECIFIED.into() };
        SocketAddr::new(unspec, 0)
    });
    log_info!("perf::client", "local addr {:?}", bind_addr);
    let socket = bind_socket(bind_addr, opt.common.send_buffer_size, opt.common.recv_buffer_size)?;
    let cfg = Arc::new(transport_config(&opt.common, "perf-client"));
    let qlog = open_qlog(&opt.common, "perf-client")?;
    let mut ep = Endpoint::new(socket, cfg, None);
    ep.qlog = qlog;

    let server_name_ok = valid_dns_name(&host_name) || host_name.parse::<std::net::IpAddr>().is_ok();
    if !server_name_ok {
        return Err(Error::msg(format!("invalid server name: {}", host_name)));
    }
    let now = Instant::now();
    let idx = ep.connect(addr, &host_name, now);

    // Handshake
    loop {
        let now = Instant::now();
        ep.flush(now);
        let mut connected = false;
        let mut failed: Option<ConnError> = None;
        {
            let c = ep.conn(idx).unwrap();
            while let Some(ev) = c.poll_event() {
                match ev {
                    Event::Connected => connected = true,
                    Event::Lost(e) => failed = Some(e),
                    _ => {}
                }
            }
        }
        if let Some(e) = failed {
            // drain the endpoint before reporting
            wait_idle(&mut ep, -1);
            return Err(Error::msg(e.to_string()).context("connecting"));
        }
        if connected {
            break;
        }
        if ep.conn(idx).map_or(true, |c| c.is_drained()) {
            return Err(Error::msg("closed").context("connecting"));
        }
        wait_for_io(&mut ep, None, -1);
    }
    log_info!("perf::client", "established");

    let wake_fd = install_sigint();
    let start = Instant::now();
    let mut stats = Stats::new(start);
    let mut open = OpenStreamStats::default();
    let interval = Duration::from_secs(opt.interval);
    let deadline = start + Duration::from_secs(opt.duration) + Duration::from_millis(200);
    let mut interval_start = start;
    let mut next_report = start + interval;
    let mut bi: Vec<Option<Request>> = (0..opt.bi_requests.min(1 << 20)).map(|_| None).collect();
    let mut uni: Vec<Option<Request>> = (0..opt.uni_requests.min(1 << 20)).map(|_| None).collect();
    let mut uni_queue: std::collections::VecDeque<u64> = std::collections::VecDeque::new();
    let mut drive_failed = false;
    let mut shutting_down = false;

    loop {
        let now = Instant::now();
        {
            let c = ep.conn(idx);
            let c = match c {
                Some(c) => c,
                None => break,
            };
            // events
            while let Some(ev) = c.poll_event() {
                if let Event::StreamAcked(id) = ev {
                    for r in bi.iter_mut().chain(uni.iter_mut()).flatten() {
                        if r.send_id == id {
                            r.acked = true;
                        }
                    }
                }
            }
            while let Ok(Some(id)) = c.accept_stream(false) {
                uni_queue.push_back(id);
            }
            // progress requests
            for (slots, bidi) in [(&mut bi, true), (&mut uni, false)] {
                for slot in slots.iter_mut() {
                    loop {
                        if slot.is_none() {
                            if drive_failed || shutting_down {
                                break;
                            }
                            match c.open_stream(bidi) {
                                Ok(Some(id)) => {
                                    log_debug!("perf::client", "sending request on {}", stream_name(id));
                                    *slot = Some(Request::new(bidi, id, opt.upload_size, opt.download_size, now, &mut open));
                                }
                                Ok(None) => break,
                                Err(_) => {
                                    drive_failed = true;
                                    break;
                                }
                            }
                        }
                        let r = slot.as_mut().unwrap();
                        match r.poll(c, now, &mut stats, &mut open, &mut uni_queue) {
                            Outcome::Pending => break,
                            Outcome::Done => {
                                *slot = None;
                            }
                            Outcome::Failed(e) => {
                                if bidi {
                                    log_error!("perf::client", "request failed: {}", e);
                                } else {
                                    log_error!("perf::client", "sending request failed: {}", e);
                                }
                                *slot = None;
                                if c.error().is_some() {
                                    drive_failed = true;
                                }
                                break;
                            }
                        }
                    }
                }
            }
        }
        if shutting_down {
            if bi.iter().chain(uni.iter()).all(|s| s.is_none()) || ep.conn(idx).map_or(true, |c| c.is_drained()) {
                // all requests reported; wait for the connection to drain
            }
        }
        let now = Instant::now();
        if !shutting_down && !drive_failed {
            // stats reporting
            if now >= next_report {
                stats.on_interval(interval_start, now, &mut open);
                let mut out = stats.print(now);
                if opt.common.conn_stats {
                    if let Some(c) = ep.conn(idx) {
                        out.push_str(&format!("{:?}\n\n", c.stats()));
                    }
                }
                print_out(&out);
                interval_start = Instant::now();
                next_report = interval_start + interval;
            }
            let interrupted = INTERRUPTED.load(Ordering::SeqCst);
            if now >= deadline || interrupted {
                log_info!("perf::client", "shutting down");
                shutting_down = true;
                if let Some(c) = ep.conn(idx) {
                    c.close(now, 0, if interrupted { b"interrupted" } else { b"done" });
                }
                continue;
            }
        }
        ep.flush(Instant::now());
        ep.reap();
        if ep.is_idle() {
            break;
        }
        if (drive_failed || shutting_down) && bi.iter().chain(uni.iter()).all(|s| s.is_none()) {
            wait_idle(&mut ep, wake_fd);
            break;
        }
        let app_deadline = if shutting_down || drive_failed { None } else { Some(next_report.min(deadline)) };
        wait_for_io(&mut ep, app_deadline, wake_fd);
    }

    if let Some(path) = &opt.json {
        let json = stats.json();
        if path.as_os_str() == "-" {
            print_out(&json);
        } else {
            std::fs::write(path, json.as_bytes()).map_err(|e| Error::from_std(&e))?;
        }
    }
    Ok(())
}

/// Runs the endpoint until all connections are drained.
pub fn wait_idle(ep: &mut Endpoint, wake_fd: i32) {
    loop {
        let now = Instant::now();
        ep.flush(now);
        ep.reap();
        if ep.is_idle() {
            return;
        }
        wait_for_io(ep, None, wake_fd);
    }
}

pub fn wait_for_io(ep: &mut Endpoint, app_deadline: Option<Instant>, wake_fd: i32) {
    let now = Instant::now();
    let t = match (ep.next_timeout(), app_deadline) {
        (Some(a), Some(b)) => Some(a.min(b)),
        (a, b) => a.or(b),
    };
    let timeout_ms: i32 = match t {
        None => 1000,
        Some(t) => {
            if t <= now {
                0
            } else {
                let d = t - now;
                let ms = (d.as_micros() + 999) / 1000;
                ms.min(1000) as i32
            }
        }
    };
    let extra = if wake_fd >= 0 { Some(wake_fd) } else { None };
    let readable = ep.socket.wait(timeout_ms, extra);
    if wake_fd >= 0 {
        let mut b = [0u8; 16];
        unsafe {
            libc::read(wake_fd, b.as_mut_ptr() as *mut libc::c_void, 16);
        }
    }
    let now = Instant::now();
    if readable {
        ep.handle_input(now);
    }
    ep.handle_timeouts(Instant::now());
}
