//! The perf server.

use crate::cert;
use crate::cli::ServerOpt;
use crate::client::wait_for_io;
use crate::common::*;
use crate::conn::{Connection, ConnectionStats, Event, StreamError};
use crate::endpoint::Endpoint;
use crate::error::{Error, Result};
use crate::tls::ServerCrypto;
use crate::{log_debug, log_error, log_info};
use std::collections::{HashMap, VecDeque};
use std::sync::Arc;
use std::time::{Duration, Instant};

fn panic_unwrap(msg: &str) -> ! {
    let tid = unsafe { libc::syscall(libc::SYS_gettid) };
    let text = format!(
        "\nthread 'main' ({}) panicked at /workspace/perf/src/server.rs:58:10:\ncalled `Result::unwrap()` on an `Err` value: {}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        tid, msg
    );
    use std::io::Write;
    let _ = std::io::stderr().write_all(text.as_bytes());
    std::process::exit(101);
}

fn build_crypto(opt: &ServerOpt) -> Result<ServerCrypto> {
    if let (Some(key_path), Some(cert_path)) = (&opt.key, &opt.cert) {
        let (fmt, der) = cert::read_private_key(key_path).map_err(|e| Error::msg(e.to_string()).context("reading private key"))?;
        let certs = match cert::read_certs(cert_path) {
            Err(e) => return Err(Error::msg(e.to_string()).context("reading certificate chain file")),
            Ok(Err(e)) => return Err(Error::msg(e.to_string()).context("reading certificate chain")),
            Ok(Ok(c)) => c,
        };
        let key = match cert::load_private_key(&fmt, &der) {
            Some(k) => k,
            None => panic_unwrap("General(\"failed to parse private key as RSA, ECDSA, or EdDSA\")"),
        };
        if key.kind() == crate::crypto::KeyKind::EcP384 {
            panic_unwrap("General(\"failed to parse private key as RSA, ECDSA, or EdDSA\")");
        }
        if certs.is_empty() {
            panic_unwrap("NoCertificatesPresented");
        }
        let spki = match cert::extract_spki(&certs[0]) {
            Some(s) => s,
            None => panic_unwrap("InvalidCertificate(BadEncoding)"),
        };
        if spki != key.public_spki() {
            panic_unwrap("InconsistentKeys(KeyMismatch)");
        }
        Ok(ServerCrypto { cert_chain: certs, key })
    } else {
        let (c, key) = cert::generate_self_signed().ok_or_else(|| Error::msg("failed to generate certificate"))?;
        Ok(ServerCrypto { cert_chain: vec![c], key })
    }
}

#[derive(PartialEq, Eq, Clone, Copy)]
enum SPhase {
    Header,
    Drain,
    OpenResponse,
    Respond,
}

struct SReq {
    recv_id: u64,
    send_id: Option<u64>,
    bidi: bool,
    phase: SPhase,
    header: Vec<u8>,
    remaining: u64,
}

struct SConn {
    reqs: Vec<SReq>,
    connected: bool,
}

struct StatsPrinter {
    conn: usize,
    next: Instant,
    last: Option<ConnectionStats>,
}

fn conn_lost_msg(e: StreamError) -> Error {
    match e {
        StreamError::ConnectionLost(c) => Error::msg(c.to_string()).context("connection lost"),
        other => Error::msg(other.to_string()),
    }
}

impl SReq {
    /// Returns Ok(true) when finished.
    fn poll(&mut self, c: &mut Connection) -> std::result::Result<bool, Error> {
        loop {
            match self.phase {
                SPhase::Header => {
                    let mut buf = Vec::new();
                    let need = 8 - self.header.len();
                    match c.read(self.recv_id, need, Some(&mut buf)) {
                        Ok(Some(0)) => return Ok(false),
                        Ok(Some(_)) => {
                            self.header.extend_from_slice(&buf);
                            if self.header.len() == 8 {
                                let mut b = [0u8; 8];
                                b.copy_from_slice(&self.header);
                                self.remaining = u64::from_be_bytes(b);
                                log_debug!(
                                    "perf::server",
                                    "got req for {} bytes on {}",
                                    self.remaining,
                                    stream_name(self.recv_id)
                                );
                                self.phase = SPhase::Drain;
                            }
                        }
                        Ok(None) => {
                            return Err(Error::msg(format!("stream finished early ({} bytes read)", self.header.len()))
                                .context("reading request"))
                        }
                        Err(e) => return Err(conn_lost_msg(e).context("reading request")),
                    }
                }
                SPhase::Drain => match c.read(self.recv_id, usize::MAX, None) {
                    Ok(Some(0)) => return Ok(false),
                    Ok(Some(_)) => {}
                    Ok(None) => {
                        log_debug!("perf::server", "finished reading {}", stream_name(self.recv_id));
                        self.phase = if self.bidi { SPhase::Respond } else { SPhase::OpenResponse };
                        if self.bidi {
                            self.send_id = Some(self.recv_id);
                        }
                    }
                    Err(e) => return Err(conn_lost_msg(e)),
                },
                SPhase::OpenResponse => match c.open_stream(false) {
                    Ok(Some(id)) => {
                        self.send_id = Some(id);
                        self.phase = SPhase::Respond;
                    }
                    Ok(None) => return Ok(false),
                    Err(e) => return Err(Error::msg(e.to_string())),
                },
                SPhase::Respond => {
                    let id = self.send_id.unwrap();
                    while self.remaining > 0 {
                        let chunk = (self.remaining as usize).min(DATA.len());
                        match c.write(id, &DATA[..chunk]) {
                            Ok(0) => return Ok(false),
                            Ok(n) => self.remaining -= n as u64,
                            Err(e) => return Err(conn_lost_msg(e).context("sending response")),
                        }
                    }
                    if let Err(e) = c.finish(id) {
                        return Err(conn_lost_msg(e).context("sending response"));
                    }
                    log_debug!("perf::server", "finished responding on {}", stream_name(id));
                    return Ok(true);
                }
            }
        }
    }
}

pub fn run(opt: ServerOpt) -> Result<()> {
    let crypto = Arc::new(build_crypto(&opt)?);
    let cfg = Arc::new(transport_config(&opt.common, "perf-server"));
    let qlog = open_qlog(&opt.common, "perf-server").map_err(|e| e)?;
    let socket = bind_socket(opt.listen, opt.common.send_buffer_size, opt.common.recv_buffer_size)?;
    let local = socket.local_addr().map_err(|e| Error::from_std(&e))?;
    let mut ep = Endpoint::new(socket, cfg, Some(crypto));
    ep.qlog = qlog;
    log_info!("perf::server", "listening on {}", local);

    let mut conns: HashMap<usize, SConn> = HashMap::new();
    let mut printers: Vec<StatsPrinter> = Vec::new();
    let conn_stats = opt.common.conn_stats;

    loop {
        let now = Instant::now();
        for idx in std::mem::take(&mut ep.accepted) {
            conns.insert(idx, SConn { reqs: Vec::new(), connected: false });
        }
        let idxs: Vec<usize> = conns.keys().copied().collect();
        for idx in idxs {
            let c = match ep.conn(idx) {
                Some(c) => c,
                None => {
                    conns.remove(&idx);
                    continue;
                }
            };
            let sc = conns.get_mut(&idx).unwrap();
            while let Some(ev) = c.poll_event() {
                match ev {
                    Event::Connected => {
                        sc.connected = true;
                        log_debug!("perf::server", "{} connected", c.remote);
                        if conn_stats {
                            printers.push(StatsPrinter { conn: idx, next: now + Duration::from_secs(2), last: None });
                        }
                    }
                    _ => {}
                }
            }
            if !sc.connected {
                continue;
            }
            while let Ok(Some(id)) = c.accept_stream(true) {
                sc.reqs.push(SReq { recv_id: id, send_id: None, bidi: true, phase: SPhase::Header, header: Vec::new(), remaining: 0 });
            }
            while let Ok(Some(id)) = c.accept_stream(false) {
                sc.reqs.push(SReq { recv_id: id, send_id: None, bidi: false, phase: SPhase::Header, header: Vec::new(), remaining: 0 });
            }
            sc.reqs.retain_mut(|r| match r.poll(c) {
                Ok(true) => false,
                Ok(false) => true,
                Err(e) => {
                    log_error!("perf::server", "request failed: {}", e);
                    false
                }
            });
        }
        // connection statistics printers (run for the lifetime of the process)
        let now = Instant::now();
        for p in printers.iter_mut() {
            if let Some(c) = ep.conn(p.conn) {
                p.last = Some(c.stats());
            }
            if now >= p.next {
                if let Some(s) = &p.last {
                    print_out(&format!("{:?}\n\n", s));
                }
                p.next = now + Duration::from_secs(2);
            }
        }
        ep.flush(Instant::now());
        for idx in ep.reap() {
            conns.remove(&idx);
            for p in printers.iter_mut() {
                if p.conn == idx {
                    p.conn = usize::MAX;
                }
            }
        }
        let next_print = printers.iter().map(|p| p.next).min();
        wait_for_io(&mut ep, next_print, -1);
    }
}

