//! Development-only sampling profiler (feature "prof").
use std::sync::atomic::{AtomicUsize, Ordering};

const N: usize = 1 << 20;
static mut SAMPLES: [usize; N] = [0; N];
static IDX: AtomicUsize = AtomicUsize::new(0);

extern "C" fn handler(_sig: libc::c_int, _info: *mut libc::siginfo_t, ctx: *mut libc::c_void) {
    unsafe {
        let uc = ctx as *mut libc::ucontext_t;
        let rip = (*uc).uc_mcontext.gregs[libc::REG_RIP as usize] as usize;
        let i = IDX.fetch_add(1, Ordering::Relaxed);
        if i < N {
            SAMPLES[i] = rip;
        }
    }
}

pub fn start() {
    if std::env::var_os("PERF_PROF").is_none() {
        return;
    }
    unsafe {
        let mut sa: libc::sigaction = std::mem::zeroed();
        sa.sa_sigaction = handler as usize;
        sa.sa_flags = libc::SA_SIGINFO | libc::SA_RESTART;
        libc::sigaction(libc::SIGPROF, &sa, std::ptr::null_mut());
        let tv = libc::itimerval {
            it_interval: libc::timeval { tv_sec: 0, tv_usec: 500 },
            it_value: libc::timeval { tv_sec: 0, tv_usec: 500 },
        };
        libc::setitimer(libc::ITIMER_PROF, &tv, std::ptr::null_mut());
    }
}

pub fn dump() {
    let path = match std::env::var_os("PERF_PROF") {
        Some(p) => p,
        None => return,
    };
    let n = IDX.load(Ordering::Relaxed).min(N);
    let maps = std::fs::read_to_string("/proc/self/maps").unwrap_or_default();
    let exe = std::fs::read_link("/proc/self/exe").unwrap_or_default();
    let mut out = String::new();
    out.push_str(&format!("EXE {}\n", exe.display()));
    for l in maps.lines() {
        out.push_str("MAP ");
        out.push_str(l);
        out.push('\n');
    }
    for i in 0..n {
        out.push_str(&format!("{:x}\n", unsafe { SAMPLES[i] }));
    }
    let _ = std::fs::write(path, out);
}
