    pub buf: Vec<u8>,
    group: String,
    last: Option<Metrics>,
}

impl Qlog {
    pub fn new(title: String, start: Instant) -> Qlog {
        Qlog { title, start, buf: Vec::new(), group: String::new(), last: None }
    }
    pub fn set_group(&mut self, g: String) {
        self.group = g;
    }
    fn t(&self, now: Instant) -> f32 {
        (now.saturating_duration_since(self.start).as_secs_f64() * 1000.0) as f32
    }
    fn space_name(space: usize) -> &'static str {
        match space {
            0 => "initial",
            1 => "handshake",
            _ => "1RTT",
        }
    }
