            "{{\"time\":{},\"name\":\"{}\",\"data\":{},\"group_id\":\"{}\"}}\n",
            fmt_f32(t),
            name,
            data,
            self.group
        );
        self.buf.extend_from_slice(line.as_bytes());
    }
    pub fn packet_sent(&mut self, now: Instant, space: usize, pn: u64, len: usize) {
        let d = format!(
            "{{\"header\":{{\"packet_type\":\"{}\",\"packet_number\":{},\"length\":{}}}}}",
            Self::space_name(space),
            pn,
            len
        );
        self.emit(now, "transport:packet_sent", d);
    }
    pub fn packet_received(&mut self, now: Instant, space: usize, pn: u64) {
        let d = format!("{{\"header\":{{\"packet_type\":\"{}\",\"packet_number\":{}}}}}", Self::space_name(space), pn);
        self.emit(now, "transport:packet_received", d);
    }
    pub fn packet_lost(&mut self, now: Instant, space: usize, pn: u64, len: u16, time: bool) {
        let d = format!(
            "{{\"header\":{{\"packet_type\":\"{}\",\"packet_number\":{},\"length\":{}}},\"trigger\":\"{}\"}}",
            Self::space_name(space),
            pn,
            len,
            if time { "time_threshold" } else { "reordering_threshold" }
        );
        self.emit(now, "recovery:packet_lost", d);
    }
    pub fn metrics(&mut self, now: Instant, m: Metrics) {
        let mut fields: Vec<String> = Vec::new();
        let last = self.last;
        macro_rules! f32field {
            ($name:ident) => {
                if last.map_or(true, |l| l.$name != m.$name) {
                    fields.push(format!("\"{}\":{}", stringify!($name), fmt_f32(m.$name)));
                }
            };
        }
        macro_rules! intfield {
            ($name:ident) => {
                if last.map_or(true, |l| l.$name != m.$name) {
                    fields.push(format!("\"{}\":{}", stringify!($name), m.$name));
                }
            };
        }
