        f32field!(smoothed_rtt);
        f32field!(latest_rtt);
        f32field!(rtt_variance);
        intfield!(pto_count);
        intfield!(congestion_window);
        intfield!(bytes_in_flight);
        intfield!(ssthresh);
        intfield!(packets_in_flight);
        self.last = Some(m);
        if fields.is_empty() {
            return;
        }
        let d = format!("{{{}}}", fields.join(","));
        self.emit(now, "recovery:metrics_updated", d);
    }
    pub fn header(title: &str) -> Vec<u8> {
        let mut v = vec![0x1e];
        v.extend_from_slice(
            format!(
                "{{\"qlog_version\":\"0.3\",\"qlog_format\":\"JSON-SEQ\",\"title\":\"{}\",\"trace\":{{\"vantage_point\":{{\"type\":\"unknown\"}},\"title\":\"{}\",\"configuration\":{{\"time_offset\":0.0}}}}}}\n",
                title, title
            )
            .as_bytes(),
        );
        v
    }
}

fn fmt_f32(f: f32) -> String {
    let s = format!("{}", f);
    if s.contains('.') || s.contains('e') || s.contains("inf") || s.contains("NaN") {
        s
    } else {
        format!("{}.0", s)
    }
}
