    if l.startswith('EXE '): exe = l[4:]
    elif l.startswith('MAP '):
        p = l[4:].split()
        if len(p) >= 6 and 'x' in p[1]:
            a, b = p[0].split('-')
            maps.append((int(a,16), int(b,16), int(p[2],16), p[5]))
    elif l.strip():
        samples.append(int(l,16))
# exe symbols via nm
syms = []
out = subprocess.run(['nm', '-C', '--defined-only', exe], capture_output=True, text=True).stdout
for l in out.split('\n'):
    p = l.split(' ', 2)
    if len(p) == 3 and p[1] in 'tTwW':
        syms.append((int(p[0],16), p[2]))
syms.sort()
addrs = [s[0] for s in syms]
# compute exe load bias: find mapping of exe with offset 0
bias = None
for a,b,off,path in maps:
    if path == exe:
        if bias is None or a - off < bias: bias = a - off
func = collections.Counter()
for s in samples:
    hit = None
    for a,b,off,path in maps:
        if a <= s < b: hit = (a,off,path); break
    if hit is None: func['?'] += 1; continue
    a,off,path = hit
    if path == exe:
