{"command":"cd /workspace && cat >> src/recovery.rs <<'EOF'

/// Token-bucket pacer (similar in spirit to quinn's).
pub struct Pacer {
    capacity: u64,
    tokens: u64,
    last: Instant,
    last_window: u64,
    last_mtu: u16,
}

const TARGET_BURST_INTERVAL_NS: u128 = 2_000_000;
const MIN_BURST: u64 = 10;
const MAX_BURST: u64 = 256;

fn optimal_capacity(rtt: Duration, window: u64, mtu: u16) -> u64 {
    let rtt_ns = rtt.as_nanos().max(1);
    let cap = (window as u128 * TARGET_BURST_INTERVAL_NS / rtt_ns) as u64;
    cap.clamp(MIN_BURST * mtu as u64, MAX_BURST * mtu as u64)
}

impl Pacer {
    pub fn new(rtt: Duration, window: u64, mtu: u16, now: Instant) -> Pacer {
        let capacity = optimal_capacity(rtt, window, mtu);
        Pacer { capacity, tokens: capacity, last: now, last_window: window, last_mtu: mtu }
    }

    /// Returns the time at which `bytes` may be sent, or None if allowed now.
    pub fn delay(&mut self, rtt: Duration, bytes: u64, mtu: u16, window: u64, now: Instant) -> Option<Instant> {
        if window != self.last_window || mtu != self.last_mtu {
            self.capacity = optimal_capacity(rtt, window, mtu);
            self.tokens = self.tokens.min(self.capacity);
            self.last_window = window;
            self.last_mtu = mtu;
        }
        if self.tokens >= bytes {
            return None;
        }
        let rtt_s = rtt.as_secs_f64().max(1e-6);
        let rate = window as f64 * 1.25 / rtt_s; // bytes per second
        let elapsed = now.saturating_duration_since(self.last).as_secs_f64();
        let new_tokens = (elapsed * rate) as u64;
        self.tokens = self.tokens.saturating_add(new_tokens).min(self.capacity);
        self.last = now;
        if self.tokens >= bytes {
            return None;
        }
        let need = (bytes - self.tokens) as f64;
        Some(now + Duration::from_secs_f64(need / rate))
    }

    pub fn on_transmit(&mut self, bytes: u64) {
        self.tokens = self.tokens.saturating_sub(bytes);
    }
}
